1	/**
2	 * Environment variable configuration and validation
3	 *
4	 * This module centralizes all environment variable access and provides
5	 * validation at startup to catch misconfigurations early.
6	 */
7	
8	interface EnvConfig {
9	  // Server
10	  nodeEnv: 'development' | 'production' | 'test';
11	  port: number;
12	  apiUrl: string;
13	  clientUrl: string;
14	  sessionSecret: string;
15	
16	  // Database
17	  databaseUrl: string;
18	
19	  // Google OAuth (required for user login)
20	  googleClientId: string;
21	  googleClientSecret: string;
22	
23	  // GitHub OAuth (optional - for repo access)
24	  githubClientId?: string;
25	  githubClientSecret?: string;
26	
27	  // AI Providers
28	  anthropicApiKey?: string;
29	  openaiApiKey?: string;
30	  openrouterApiKey?: string;
31	
32	  // E2B Sandbox (optional until agent execution)
33	  e2bApiKey?: string;
34	
35	  // Job Queue
36	  maxConcurrentJobs: number;
37	  maxConcurrentSandboxes: number;
38	}
39	
40	function getEnvVar(key: string, required: boolean = false): string | undefined {
41	  const value = process.env[key];
42	  if (required && !value) {
43	    throw new Error(`Missing required environment variable: ${key}`);
44	  }
45	  return value;
46	}
47	
48	function getEnvVarOrDefault(key: string, defaultValue: string): string {
49	  return process.env[key] || defaultValue;
50	}
51	
52	function getEnvVarInt(key: string, defaultValue: number): number {
53	  const value = process.env[key];
54	  if (!value) return defaultValue;
55	  const parsed = parseInt(value, 10);
56	  if (isNaN(parsed)) {
57	    throw new Error(`Environment variable ${key} must be a valid integer`);
58	  }
59	  return parsed;
60	}
61	
62	/**
63	 * Validates and returns the environment configuration.
64	 * Call this at app startup to catch issues early.
65	 */
66	export function validateEnv(): EnvConfig {
67	  const nodeEnv = getEnvVarOrDefault('NODE_ENV', 'development') as EnvConfig['nodeEnv'];
68	  const isProduction = nodeEnv === 'production';
69	
70	  // In production, certain vars are required
71	  const googleClientId = getEnvVar('GOOGLE_CLIENT_ID', isProduction);
72	  const googleClientSecret = getEnvVar('GOOGLE_CLIENT_SECRET', isProduction);
73	  const sessionSecret = getEnvVarOrDefault('SESSION_SECRET', 'dev-secret-change-in-production');
74	
75	  if (isProduction && sessionSecret === 'dev-secret-change-in-production') {
76	    throw new Error('SESSION_SECRET must be set to a secure value in production');
77	  }
78	
79	  return {
80	    nodeEnv,
81	    port: getEnvVarInt('PORT', 3001),
82	    apiUrl: getEnvVarOrDefault('API_URL', 'http://localhost:3001'),
83	    clientUrl: getEnvVarOrDefault('CLIENT_URL', 'http://localhost:5173'),
84	    sessionSecret,
85	
86	    databaseUrl: getEnvVarOrDefault('DATABASE_URL', './data/devdash.db'),
87	
88	    googleClientId: googleClientId || '',
89	    googleClientSecret: googleClientSecret || '',
90	
91	    githubClientId: getEnvVar('GITHUB_CLIENT_ID'),
92	    githubClientSecret: getEnvVar('GITHUB_CLIENT_SECRET'),
93	
94	    anthropicApiKey: getEnvVar('ANTHROPIC_API_KEY'),
95	    openaiApiKey: getEnvVar('OPENAI_API_KEY'),
96	    openrouterApiKey: getEnvVar('OPENROUTER_API_KEY'),
97	
98	    e2bApiKey: getEnvVar('E2B_API_KEY'),
99	
100	    maxConcurrentJobs: getEnvVarInt('MAX_CONCURRENT_JOBS', 3),
101	    maxConcurrentSandboxes: getEnvVarInt('MAX_CONCURRENT_SANDBOXES', 5),
102	  };
103	}
104	
105	/**
106	 * Logs which optional features are enabled based on env vars.
107	 * Useful for debugging configuration issues.
108	 */
109	export function logEnvStatus(config: EnvConfig): void {
110	  console.log('Environment Configuration:');
111	  console.log(`  Mode: ${config.nodeEnv}`);
112	  console.log(`  API URL: ${config.apiUrl}`);
113	  console.log(`  Client URL: ${config.clientUrl}`);
114	  console.log('');
115	  console.log('Feature Status:');
116	  console.log(`  Google OAuth: ${config.googleClientId ? 'enabled' : 'disabled'}`);
117	  console.log(`  GitHub OAuth: ${config.githubClientId ? 'enabled' : 'disabled'}`);
118	  console.log(`  Anthropic AI: ${config.anthropicApiKey ? 'enabled' : 'disabled'}`);
119	  console.log(`  OpenAI: ${config.openaiApiKey ? 'enabled' : 'disabled'}`);
120	  console.log(`  OpenRouter: ${config.openrouterApiKey ? 'enabled' : 'disabled'}`);
121	  console.log(`  E2B Sandbox: ${config.e2bApiKey ? 'enabled' : 'disabled'}`);
122	  console.log('');
123	  console.log('Limits:');
124	  console.log(`  Max Concurrent Jobs: ${config.maxConcurrentJobs}`);
125	  console.log(`  Max Concurrent Sandboxes: ${config.maxConcurrentSandboxes}`);
126	}
127	
128	// Lazy-loaded singleton
129	let _config: EnvConfig | null = null;
130	
131	/**
132	 * Get the validated environment config.
133	 * Validates on first access, then caches.
134	 */
135	export function getConfig(): EnvConfig {
136	  if (!_config) {
137	    _config = validateEnv();
138	  }
139	  return _config;
140	}
