/**
 * Environment variable configuration and validation
 *
 * This module centralizes all environment variable access and provides
 * validation at startup to catch misconfigurations early.
 */

interface EnvConfig {
  // Server
  nodeEnv: 'development' | 'production' | 'test';
  port: number;
  apiUrl: string;
  clientUrl: string;
  sessionSecret: string;

  // Database
  databaseUrl: string;

  // Google OAuth (required for user login)
  googleClientId: string;
  googleClientSecret: string;

  // GitHub OAuth (optional - for repo access)
  githubClientId?: string;
  githubClientSecret?: string;

  // AI Providers
  anthropicApiKey?: string;
  openaiApiKey?: string;
  openrouterApiKey?: string;

  // E2B Sandbox (optional until agent execution)
  e2bApiKey?: string;

  // Job Queue
  maxConcurrentJobs: number;
  maxConcurrentSandboxes: number;
}

function getEnvVar(key: string, required: boolean = false): string | undefined {
  const value = process.env[key];
  if (required && !value) {
    throw new Error(`Missing required environment variable: ${key}`);
  }
  return value;
}

function getEnvVarOrDefault(key: string, defaultValue: string): string {
  return process.env[key] || defaultValue;
}

function getEnvVarInt(key: string, defaultValue: number): number {
  const value = process.env[key];
  if (!value) return defaultValue;
  const parsed = parseInt(value, 10);
  if (isNaN(parsed)) {
    throw new Error(`Environment variable ${key} must be a valid integer`);
  }
  return parsed;
}

/**
 * Validates and returns the environment configuration.
 * Call this at app startup to catch issues early.
 */
export function validateEnv(): EnvConfig {
  const nodeEnv = getEnvVarOrDefault('NODE_ENV', 'development') as EnvConfig['nodeEnv'];
  const isProduction = nodeEnv === 'production';

  // In production, certain vars are required
  const googleClientId = getEnvVar('GOOGLE_CLIENT_ID', isProduction);
  const googleClientSecret = getEnvVar('GOOGLE_CLIENT_SECRET', isProduction);
  const sessionSecret = getEnvVarOrDefault('SESSION_SECRET', 'dev-secret-change-in-production');

  if (isProduction && sessionSecret === 'dev-secret-change-in-production') {
    throw new Error('SESSION_SECRET must be set to a secure value in production');
  }

  return {
    nodeEnv,
    port: getEnvVarInt('PORT', 3001),
    apiUrl: getEnvVarOrDefault('API_URL', 'http://localhost:3001'),
    clientUrl: getEnvVarOrDefault('CLIENT_URL', 'http://localhost:5173'),
    sessionSecret,

    databaseUrl: getEnvVarOrDefault('DATABASE_URL', './data/devdash.db'),

    googleClientId: googleClientId || '',
    googleClientSecret: googleClientSecret || '',

    githubClientId: getEnvVar('GITHUB_CLIENT_ID'),
    githubClientSecret: getEnvVar('GITHUB_CLIENT_SECRET'),

    anthropicApiKey: getEnvVar('ANTHROPIC_API_KEY'),
    openaiApiKey: getEnvVar('OPENAI_API_KEY'),
    openrouterApiKey: getEnvVar('OPENROUTER_API_KEY'),

    e2bApiKey: getEnvVar('E2B_API_KEY'),

    maxConcurrentJobs: getEnvVarInt('MAX_CONCURRENT_JOBS', 3),
    maxConcurrentSandboxes: getEnvVarInt('MAX_CONCURRENT_SANDBOXES', 5),
  };
}

/**
 * Logs which optional features are enabled based on env vars.
 * Useful for debugging configuration issues.
 */
export function logEnvStatus(config: EnvConfig): void {
  console.log('Environment Configuration:');
  console.log(`  Mode: ${config.nodeEnv}`);
  console.log(`  API URL: ${config.apiUrl}`);
  console.log(`  Client URL: ${config.clientUrl}`);
  console.log('');
  console.log('Feature Status:');
  console.log(`  Google OAuth: ${config.googleClientId ? 'enabled' : 'disabled'}`);
  console.log(`  GitHub OAuth: ${config.githubClientId ? 'enabled' : 'disabled'}`);
  console.log(`  Anthropic AI: ${config.anthropicApiKey ? 'enabled' : 'disabled'}`);
  console.log(`  OpenAI: ${config.openaiApiKey ? 'enabled' : 'disabled'}`);
  console.log(`  OpenRouter: ${config.openrouterApiKey ? 'enabled' : 'disabled'}`);
  console.log(`  E2B Sandbox: ${config.e2bApiKey ? 'enabled' : 'disabled'}`);
  console.log('');
  console.log('Limits:');
  console.log(`  Max Concurrent Jobs: ${config.maxConcurrentJobs}`);
  console.log(`  Max Concurrent Sandboxes: ${config.maxConcurrentSandboxes}`);
}

// Lazy-loaded singleton
let _config: EnvConfig | null = null;

/**
 * Get the validated environment config.
 * Validates on first access, then caches.
 */
export function getConfig(): EnvConfig {
  if (!_config) {
    _config = validateEnv();
  }
  return _config;
}

