import Database from 'better-sqlite3';
import path from 'path';
import fs from 'fs';
import { encryptValue, isEncrypted } from '../utils/crypto.js';

// Ensure data directory exists
const dataDir = process.env.DATABASE_URL
  ? path.dirname(process.env.DATABASE_URL)
  : './data';

if (!fs.existsSync(dataDir)) {
  fs.mkdirSync(dataDir, { recursive: true });
}

const dbPath = process.env.DATABASE_URL || './data/devdash.db';
export const db = new Database(dbPath);

// SQLite performance and safety pragmas
db.pragma('journal_mode = WAL');           // concurrent reads + writes
db.pragma('foreign_keys = ON');            // enforce referential integrity
db.pragma('synchronous = NORMAL');         // safe with WAL, 2-3x faster writes
db.pragma('cache_size = -4000');           // 4MB page cache (default is 2MB)
db.pragma('temp_store = MEMORY');          // temp tables in memory
db.pragma('mmap_size = 268435456');        // 256MB memory-mapped I/O

// Initialize schema immediately
function initSchema() {
  // Users table
  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id TEXT PRIMARY KEY,
      username TEXT NOT NULL,
      display_name TEXT NOT NULL,
      avatar_url TEXT,
      email TEXT,
      access_token TEXT,
      google_id TEXT UNIQUE,
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now'))
    )
  `);

  // Add google_id column if it doesn't exist (for existing databases)
  try {
    db.exec('ALTER TABLE users ADD COLUMN google_id TEXT UNIQUE');
    console.log('Added google_id column to users table');
  } catch (e: any) {
    if (e.message?.includes('duplicate column')) {
      console.log('google_id column already exists');
    } else {
      console.error('Error adding google_id column:', e.message);
    }
  }

  // Add last_login_at column if it doesn't exist (for existing databases)
  try {
    db.exec('ALTER TABLE users ADD COLUMN last_login_at TEXT');
    console.log('Added last_login_at column to users table');
  } catch (e: any) {
    if (e.message?.includes('duplicate column')) {
      // Column already exists
    } else {
      console.error('Error adding last_login_at column:', e.message);
    }
  }

  // Add last_interaction_at column if it doesn't exist (for authenticated token activity)
  try {
    db.exec('ALTER TABLE users ADD COLUMN last_interaction_at TEXT');
    console.log('Added last_interaction_at column to users table');
  } catch (e: any) {
    if (e.message?.includes('duplicate column')) {
      // Column already exists
    } else {
      console.error('Error adding last_interaction_at column:', e.message);
    }
  }

  // Remove UNIQUE constraint from username if needed (migration for existing DBs)
  // Note: SQLite doesn't support DROP CONSTRAINT, so we just allow duplicates going forward

  // Index on users.email — used in OAuth login, invitations, user lookups
  db.exec(`CREATE INDEX IF NOT EXISTS idx_users_email ON users(email)`);

  // Sessions table
  db.exec(`
    CREATE TABLE IF NOT EXISTS sessions (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      expires_at TEXT NOT NULL,
      created_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id)
    )
  `);

  // Projects table
  db.exec(`
    CREATE TABLE IF NOT EXISTS projects (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,

    user_id TEXT NOT NULL,
    name TEXT NOT NULL,
    path TEXT NOT NULL,
    github_repo TEXT,
    description TEXT,
    ai_provider TEXT DEFAULT 'claude',
    ai_model TEXT DEFAULT 'claude-sonnet-4-20250514',
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id)
  )
`);

// Add description column if it doesn't exist (for existing databases)
try {
  db.exec('ALTER TABLE projects ADD COLUMN description TEXT');
} catch {
  // Column already exists
}

// Add merge_strategy column to projects (pr or direct)
try {
  db.exec("ALTER TABLE projects ADD COLUMN merge_strategy TEXT NOT NULL DEFAULT 'pr'");
} catch {
  // Column already exists
}

// Add last_accessed_at column to projects
try {
  db.exec('ALTER TABLE projects ADD COLUMN last_accessed_at TEXT');
} catch {
  // Column already exists
}

// Add init_status and init_result columns to projects (auto-initialization tracking)
try {
  db.exec('ALTER TABLE projects ADD COLUMN init_status TEXT');
  db.exec('ALTER TABLE projects ADD COLUMN init_result TEXT');
} catch {
  // Columns already exist
}

// Add github_sync_enabled column to projects (per-project sync toggle)
try {
  db.exec('ALTER TABLE projects ADD COLUMN github_sync_enabled INTEGER DEFAULT 0');
} catch {
  // Column already exists
}

// Reset stale 'running' init status on server startup (handles crashes)
db.exec("UPDATE projects SET init_status = 'pending' WHERE init_status = 'running'");

// Agents table
db.exec(`
  CREATE TABLE IF NOT EXISTS agents (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    prompt TEXT NOT NULL,
    status TEXT DEFAULT 'idle',
    started_at TEXT,
    completed_at TEXT,
    error TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (project_id) REFERENCES projects(id)
  )
`);

// Settings table (for API keys, encrypted)
db.exec(`
  CREATE TABLE IF NOT EXISTS settings (
    user_id TEXT NOT NULL,
    key TEXT NOT NULL,
    value TEXT NOT NULL,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    PRIMARY KEY (user_id, key),
    FOREIGN KEY (user_id) REFERENCES users(id)
  )
`);

// Cross-project orchestration plans
db.exec(`
  CREATE TABLE IF NOT EXISTS orchestration_plans (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    status TEXT DEFAULT 'draft',
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id)
  )
`);

// Plan items linking projects and tasks
db.exec(`
  CREATE TABLE IF NOT EXISTS plan_items (
    id TEXT PRIMARY KEY,
    plan_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    bead_id TEXT,
    github_issue_number INTEGER,
    sequence_order INTEGER,
    status TEXT DEFAULT 'pending',
    notes TEXT,
    FOREIGN KEY (plan_id) REFERENCES orchestration_plans(id),
    FOREIGN KEY (project_id) REFERENCES projects(id)
  )
`);

// Memory/context per project
db.exec(`
  CREATE TABLE IF NOT EXISTS project_memory (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    key TEXT NOT NULL,
    content TEXT NOT NULL,
    updated_at TEXT DEFAULT (datetime('now')),
    UNIQUE(project_id, key),
    FOREIGN KEY (project_id) REFERENCES projects(id)
  )
`);

// Cross-project/global memory
db.exec(`
  CREATE TABLE IF NOT EXISTS global_memory (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    key TEXT NOT NULL,
    content TEXT NOT NULL,
    updated_at TEXT DEFAULT (datetime('now')),
    UNIQUE(user_id, key),
    FOREIGN KEY (user_id) REFERENCES users(id)
  )
`);

// GitHub issue sync tracking
db.exec(`
  CREATE TABLE IF NOT EXISTS github_issue_sync (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    github_issue_number INTEGER NOT NULL,
    bead_id TEXT,
    sync_status TEXT DEFAULT 'synced',
    last_synced_at TEXT,
    UNIQUE(project_id, github_issue_number),
    FOREIGN KEY (project_id) REFERENCES projects(id)
  )
`);

// Agent session history
db.exec(`
  CREATE TABLE IF NOT EXISTS agent_sessions (
    id TEXT PRIMARY KEY,
    project_id TEXT,
    summary TEXT,
    context_used TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (project_id) REFERENCES projects(id)
  )
`);

// Agent jobs queue (replaces simple agents table with queue semantics)
db.exec(`
  CREATE TABLE IF NOT EXISTS agent_jobs (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    bead_id TEXT,
    prompt TEXT NOT NULL,
    status TEXT DEFAULT 'queued',
    worker_type TEXT DEFAULT 'docker',
    worker_id TEXT,
    priority INTEGER DEFAULT 2,
    started_at TEXT,
    completed_at TEXT,
    error TEXT,
    output_log TEXT,
    result TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (project_id) REFERENCES projects(id)
  )
`);

// Credentials storage (encrypted service tokens)
db.exec(`
  CREATE TABLE IF NOT EXISTS credentials (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    service TEXT NOT NULL,
    credential_type TEXT NOT NULL,
    encrypted_value TEXT NOT NULL,
    created_at TEXT DEFAULT (datetime('now')),
    expires_at TEXT,
    UNIQUE(user_id, service),
    FOREIGN KEY (user_id) REFERENCES users(id)
  )
`);

// Notifications for in-app notification center

