initSchema();

/**
 * Migrate plaintext credentials to AES-256-GCM encrypted values.
 * Safe to run multiple times — skips already-encrypted values.
 * Gracefully skips if CREDENTIAL_ENCRYPTION_KEY is not set (logs warning).
 */
export function migrateCredentialEncryption(): void {
  try {
    const rows = db.prepare('SELECT id, encrypted_value FROM credentials').all() as any[];
    let migrated = 0;
    for (const row of rows) {
      if (!row.encrypted_value) continue;
      if (isEncrypted(row.encrypted_value)) continue;

      const encrypted = encryptValue(row.encrypted_value);
      db.prepare('UPDATE credentials SET encrypted_value = ? WHERE id = ?').run(encrypted, row.id);
      migrated++;
    }
    if (migrated > 0) {
      console.log(`[DB] Migrated ${migrated} credential(s) to encrypted storage`);
    }
  } catch (err) {
    // Don't crash the server if encryption key isn't configured yet.
    // Credentials will continue to work unencrypted until the key is set.
    console.warn('[DB] Credential encryption migration skipped:', (err as Error).message);
  }
}

