import { pgTable, text, integer, boolean, timestamp, uniqueIndex, index, primaryKey } from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';

// Helper: default timestamp columns
const createdAt = () => timestamp('created_at').defaultNow().notNull();
const updatedAt = () => timestamp('updated_at').defaultNow().notNull();
const optionalCreatedAt = () => timestamp('created_at').defaultNow();
const optionalUpdatedAt = () => timestamp('updated_at').defaultNow();

// =============================================================================
// Users
// =============================================================================
export const users = pgTable('users', {
  id: text('id').primaryKey(),
  username: text('username').notNull(),
  displayName: text('display_name').notNull(),
  avatarUrl: text('avatar_url'),
  email: text('email'),
  accessToken: text('access_token'),
  googleId: text('google_id').unique(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
  lastLoginAt: timestamp('last_login_at'),
  lastInteractionAt: timestamp('last_interaction_at'),
  onboardingCompleted: boolean('onboarding_completed').notNull().default(false),
  systemRole: text('system_role'),
  ssoProvider: text('sso_provider'),
  ssoExternalId: text('sso_external_id'),
  primaryOrgId: text('primary_org_id'),
}, (t) => [
  index('idx_users_email').on(t.email),
]);

// =============================================================================
// Sessions
// =============================================================================
export const sessions = pgTable('sessions', {
  id: text('id').primaryKey(),
  userId: text('user_id').notNull().references(() => users.id),
  expiresAt: timestamp('expires_at').notNull(),
  createdAt: optionalCreatedAt(),
});

// =============================================================================
// Projects
// =============================================================================
export const projects = pgTable('projects', {
  id: text('id').primaryKey(),
  userId: text('user_id').notNull().references(() => users.id),
  name: text('name').notNull(),
  path: text('path').notNull(),
  githubRepo: text('github_repo'),
  description: text('description'),
  aiProvider: text('ai_provider').default('claude'),
  aiModel: text('ai_model').default('claude-sonnet-4-20250514'),
  mergeStrategy: text('merge_strategy').notNull().default('pr'),
  lastAccessedAt: timestamp('last_accessed_at'),
  initStatus: text('init_status'),
  initResult: text('init_result'),
  githubSyncEnabled: boolean('github_sync_enabled').default(false),
  accessLevel: text('access_level').default('full'),
  installationId: integer('installation_id'),
  orgId: text('org_id'),
  autoDispatchReady: boolean('auto_dispatch_ready').default(false),
  autoDispatchMinAutomability: integer('auto_dispatch_min_automability').default(60),
  autoDispatchMaxConcurrent: integer('auto_dispatch_max_concurrent').default(1),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  index('idx_projects_org').on(t.orgId),
]);

// =============================================================================
// Agents (legacy)
// =============================================================================
export const agents = pgTable('agents', {
  id: text('id').primaryKey(),
