  initStatus: text('init_status'),
  initResult: text('init_result'),
  githubSyncEnabled: boolean('github_sync_enabled').default(false),
  accessLevel: text('access_level').default('full'),
  installationId: integer('installation_id'),
  orgId: text('org_id'),
  autoDispatchReady: boolean('auto_dispatch_ready').default(false),
  autoDispatchMinAutomability: integer('auto_dispatch_min_automability').default(60),
  autoDispatchMaxConcurrent: integer('auto_dispatch_max_concurrent').default(1),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  index('idx_projects_org').on(t.orgId),
]);

