/**
 * Async Postgres ops layer — drop-in replacement for the synchronous SQLite ops.
 *
 * Each ops object mirrors the SQLite interface but returns Promises.
 * Consuming code changes: add `await` + make callers async.
 */
import { eq, and, or, lt, desc, asc, sql, like, isNull, count, sum, inArray } from 'drizzle-orm';
import { pgDb } from './postgres.js';
import * as s from './schema.js';
import { encryptValue, isEncrypted } from '../utils/crypto.js';

// =============================================================================
// Users
// =============================================================================
export const userOps = {
  findById: (id: string) =>
    pgDb.select().from(s.users).where(eq(s.users.id, id)).then(r => r[0] ?? null),

  findByUsername: (username: string) =>
    pgDb.select().from(s.users).where(eq(s.users.username, username)).then(r => r[0] ?? null),

  findByGoogleId: (googleId: string) =>
    pgDb.select().from(s.users).where(eq(s.users.googleId, googleId)).then(r => r[0] ?? null),

  findByEmail: (email: string) =>
    pgDb.select().from(s.users).where(eq(s.users.email, email)).then(r => r[0] ?? null),

  create: (id: string, username: string, displayName: string, avatarUrl: string | null, email: string | null, accessToken: string | null, googleId: string | null) =>
    pgDb.insert(s.users).values({ id, username, displayName, avatarUrl, email, accessToken, googleId }),

  update: (displayName: string, avatarUrl: string | null, email: string | null, accessToken: string | null, id: string) =>
    pgDb.update(s.users).set({ displayName, avatarUrl, email, accessToken, updatedAt: new Date() }).where(eq(s.users.id, id)),

  updateOnboardingCompleted: (onboardingCompleted: boolean, id: string) =>
    pgDb.update(s.users).set({ onboardingCompleted, updatedAt: new Date() }).where(eq(s.users.id, id)),

  updatePrimaryOrg: (primaryOrgId: string | null, id: string) =>
    pgDb.update(s.users).set({ primaryOrgId, updatedAt: new Date() }).where(eq(s.users.id, id)),

  updateSystemRole: (systemRole: string | null, id: string) =>
    pgDb.update(s.users).set({ systemRole, updatedAt: new Date() }).where(eq(s.users.id, id)),

  findAll: () =>
    pgDb.select({
      id: s.users.id, username: s.users.username, displayName: s.users.displayName,
      avatarUrl: s.users.avatarUrl, email: s.users.email, systemRole: s.users.systemRole,
      onboardingCompleted: s.users.onboardingCompleted, createdAt: s.users.createdAt, updatedAt: s.users.updatedAt,
    }).from(s.users).orderBy(desc(s.users.createdAt)),

  findAllFiltered: (pattern: string, _pattern2: string, _pattern3: string, limit: number, offset: number) =>
    pgDb.select({
      id: s.users.id, username: s.users.username, displayName: s.users.displayName,
      avatarUrl: s.users.avatarUrl, email: s.users.email, systemRole: s.users.systemRole,
      onboardingCompleted: s.users.onboardingCompleted, createdAt: s.users.createdAt, updatedAt: s.users.updatedAt,
      lastLoginAt: s.users.lastLoginAt, lastInteractionAt: s.users.lastInteractionAt,
    }).from(s.users)
      .where(or(like(s.users.email, pattern), like(s.users.displayName, pattern), like(s.users.username, pattern)))
      .orderBy(desc(s.users.createdAt))
      .limit(limit).offset(offset),

  countFiltered: (pattern: string, _pattern2: string, _pattern3: string) =>
    pgDb.select({ count: count() }).from(s.users)
      .where(or(like(s.users.email, pattern), like(s.users.displayName, pattern), like(s.users.username, pattern)))
      .then(r => r[0]),

  countAll: () =>
    pgDb.select({ count: count() }).from(s.users).then(r => r[0]),

  countAdmins: () =>
    pgDb.select({ count: count() }).from(s.users).where(eq(s.users.systemRole, 'admin')).then(r => r[0]),

  updateLastLogin: (id: string) =>
    pgDb.update(s.users).set({ lastLoginAt: new Date() }).where(eq(s.users.id, id)),

  updateLastInteraction: (id: string) =>
    pgDb.update(s.users).set({ lastInteractionAt: new Date() }).where(eq(s.users.id, id)),
};

// =============================================================================
// Sessions
// =============================================================================
