    }).where(eq(s.projects.id, id)),

  updateInitStatus: (initStatus: string | null, initResult: string | null, id: string) =>
    pgDb.update(s.projects).set({ initStatus, initResult, updatedAt: new Date() }).where(eq(s.projects.id, id)),

