    pgDb.select({ id: s.projects.id }).from(s.projects).where(like(s.projects.id, `${prefix}%`)).limit(2),

  findAccessibleByUserId: (userId: string, _userId2: string) =>
    pgDb.execute(sql`
      SELECT p.*, 'owner' as _role, NULL as _permissions
      FROM projects p WHERE p.user_id = ${userId}
      UNION ALL
      SELECT p.*, COALESCE(pm.role, 'member') as _role, pm.permissions as _permissions
      FROM project_members pm
      JOIN projects p ON p.id = pm.project_id
      WHERE pm.user_id = ${userId}
      ORDER BY updated_at DESC
    `),
};

