/**
 * Async Postgres ops layer — drop-in replacement for the synchronous SQLite ops.
 *
 * Each ops object mirrors the SQLite interface but returns Promises.
 * Consuming code changes: add `await` + make callers async.
 */
import { eq, and, or, lt, desc, asc, sql, like, isNull, count, sum, inArray } from 'drizzle-orm';
import { pgDb } from './postgres.js';
import * as s from './schema.js';
import { encryptValue, isEncrypted } from '../utils/crypto.js';

// =============================================================================
// Users
// =============================================================================
export const userOps = {
  findById: (id: string) =>
