 * Runs against live Railway Postgres — requires POSTGRES_URL env var.
 *
 * Usage: POSTGRES_URL="postgresql://..." npx vitest run src/db/__tests__/ops-smoke.test.ts
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { randomUUID } from 'crypto';

// Must set POSTGRES_URL before importing ops (postgres.ts reads it at module load)
if (!process.env.POSTGRES_URL) {
  throw new Error('POSTGRES_URL env var required for smoke tests');
}

const {
  userOps, sessionOps, projectOps, projectMemberOps, projectInvitationOps,
