    await pool.query('DELETE FROM project_agent_config WHERE project_id = $1', [projectId]);
    await pool.query('DELETE FROM bead_sync_state WHERE project_id = $1', [projectId]);
    await pool.query('DELETE FROM api_tokens WHERE user_id = $1', [userId]);
    await pool.query('DELETE FROM auth_events WHERE user_id = $1', [userId]);
    await pool.query('DELETE FROM projects WHERE id = $1', [projectId]);
    await pool.query('DELETE FROM sessions WHERE user_id = $1', [userId]);
    await pool.query('DELETE FROM users WHERE id = $1', [userId]);
    await pool.end();
  });

  // ── Users ──────────────────────────────────────────────────────────────
  it('creates and finds a user', async () => {
    await userOps.create(userId, 'testuser', 'Test User', 'https://avatar.test/1', 'test@example.com', null, 'google-123');
    const user = await userOps.findById(userId);
    expect(user).toBeTruthy();
    expect(user!.username).toBe('testuser');
    expect(user!.email).toBe('test@example.com');
  });

  it('finds user by google ID', async () => {
    const user = await userOps.findByGoogleId('google-123');
    expect(user).toBeTruthy();
    expect(user!.id).toBe(userId);
  });

  it('finds user by email', async () => {
    const user = await userOps.findByEmail('test@example.com');
    expect(user).toBeTruthy();
    expect(user!.id).toBe(userId);
  });

  it('updates a user', async () => {
    await userOps.update('Updated User', 'https://avatar.test/2', 'test@example.com', null, userId);
    const user = await userOps.findById(userId);
    expect(user!.displayName).toBe('Updated User');
  });

  it('updates last login', async () => {
    await userOps.updateLastLogin(userId);
    const user = await userOps.findById(userId);
    expect(user!.lastLoginAt).toBeTruthy();
  });

  it('counts users', async () => {
    const result = await userOps.countAll();
    expect(result!.count).toBeGreaterThanOrEqual(1);
  });

  it('filters users', async () => {
    const results = await userOps.findAllFiltered('%test%', '%test%', '%test%', 10, 0);
    expect(results.length).toBeGreaterThanOrEqual(1);
  });

  // ── Sessions ───────────────────────────────────────────────────────────
  it('creates and finds a session', async () => {
    const sessionId = randomUUID();
    const expires = new Date(Date.now() + 86400000).toISOString();
    await sessionOps.create(sessionId, userId, expires);
    const session = await sessionOps.findById(sessionId);
    expect(session).toBeTruthy();
    expect(session!.userId).toBe(userId);
  });

  // ── Projects ───────────────────────────────────────────────────────────
  it('creates and finds a project', async () => {
    await projectOps.create(projectId, userId, 'Test Project', '/test/path', 'user/repo', 'A test project', 'claude', 'claude-sonnet-4-20250514', 'pr', false);
    const project = await projectOps.findById(projectId);
    expect(project).toBeTruthy();
    expect(project!.name).toBe('Test Project');
    expect(project!.githubSyncEnabled).toBe(false);
  });

  it('finds projects by user', async () => {
    const projects = await projectOps.findByUserId(userId);
    expect(projects.length).toBeGreaterThanOrEqual(1);
  });

