    const membership = await projectMemberOps.findMembership(projectId, memberId);
    expect(membership).toBeTruthy();
    expect(membership!.role).toBe('member');

    // Test JOIN query
    const withUsers = await projectMemberOps.findByProjectIdWithUsers(projectId);
    expect(withUsers.length).toBeGreaterThanOrEqual(1);

    // Cleanup
    await projectMemberOps.remove(projectId, memberId);
    await pool.query('DELETE FROM users WHERE id = $1', [memberId]);
  });

  // ── Settings (upsert) ─────────────────────────────────────────────────
  it('upserts and reads settings', async () => {
    await settingsOps.set(userId, 'theme', 'dark', 'dark');
    const setting = await settingsOps.get(userId, 'theme');
    expect(setting).toBeTruthy();
    expect(setting!.value).toBe('dark');

    // Update via upsert
    await settingsOps.set(userId, 'theme', 'light', 'light');
    const updated = await settingsOps.get(userId, 'theme');
    expect(updated!.value).toBe('light');
  });

  // ── Beads ──────────────────────────────────────────────────────────────
  it('creates and finds a bead', async () => {
    await beadOps.create(beadId, projectId, 'Test Bead', 'A test bead description', 'pending', 2, null, null, null, null, null, null, null, null, 'task', null);
    const bead = await beadOps.findById(beadId);
    expect(bead).toBeTruthy();
    expect(bead!.subject).toBe('Test Bead');
    expect(bead!.status).toBe('pending');
  });

  it('updates bead status', async () => {
    await beadOps.updateStatus('in_progress', beadId);
    const bead = await beadOps.findById(beadId);
    expect(bead!.status).toBe('in_progress');
  });

  it('finds beads by project (paginated)', async () => {
    const beads = await beadOps.findByProjectIdPaginated(projectId, 10);
    expect(beads.length).toBeGreaterThanOrEqual(1);
  });

  it('finds beads filtered', async () => {
    const beads = await beadOps.findByProjectIdFiltered(
      projectId, 'in_progress', 'in_progress', null, null, null, null, null, null, null, null, null, 10
    );
    expect(beads.length).toBeGreaterThanOrEqual(1);
  });

  it('finds by ID prefix', async () => {
    const prefix = beadId.substring(0, 8);
    const results = await beadOps.findByIdPrefix(prefix);
    expect(results.length).toBeGreaterThanOrEqual(1);
  });

  // ── Bead Comments ──────────────────────────────────────────────────────
  it('creates and finds bead comments', async () => {
    const commentId = randomUUID();
    await beadCommentOps.create(commentId, beadId, projectId, userId, 'user', 'Test comment', null);
    const comments = await beadCommentOps.findByBeadId(beadId);
    expect(comments.length).toBe(1);
    expect(comments[0].content).toBe('Test comment');
  });

  // ── Agent Jobs ─────────────────────────────────────────────────────────
  it('creates and queries agent jobs', async () => {
    const jobId = randomUUID();
    await agentJobOps.create(jobId, projectId, beadId, 'Fix the bug', 'queued', 'e2b', 2, null, null, null, null, null, null, 'execution');
    const job = await agentJobOps.findById(jobId);
