    await notificationOps.markRead(notifId);
    const afterRead = await notificationOps.countUnread(userId);
    expect(afterRead!.count).toBeLessThan(unread!.count);
  });

  // ── Activity Log ───────────────────────────────────────────────────────
  it('creates and reads activity log', async () => {
