    expect(logs.length).toBeGreaterThanOrEqual(1);
  });

  // ── Project Memory (upsert) ───────────────────────────────────────────
  it('upserts and reads project memory', async () => {
    const memId = randomUUID();
    await projectMemoryOps.upsert(memId, projectId, 'context', 'initial value', null, 'initial value', null);
    const mem = await projectMemoryOps.findByProjectIdAndKey(projectId, 'context');
    expect(mem).toBeTruthy();
