    const updated = await projectMemoryOps.findByProjectIdAndKey(projectId, 'context');
    expect(updated!.content).toBe('updated value');
  });

  // ── Global Memory (upsert) ────────────────────────────────────────────
  it('upserts and reads global memory', async () => {
