  beforeAll(async () => {
    await initializeDatabase();
  });

  afterAll(async () => {
    // Clean up test data in reverse dependency order
    await pool.query('DELETE FROM team_projects WHERE team_id = $1', [teamId]);
    await pool.query('DELETE FROM team_members WHERE team_id = $1', [teamId]);
    await pool.query('DELETE FROM teams WHERE id = $1', [teamId]);
    await pool.query('DELETE FROM organization_members WHERE org_id = $1', [orgId]);
    await pool.query('DELETE FROM organizations WHERE id = $1', [orgId]);
    await pool.query('DELETE FROM bead_comments WHERE bead_id = $1', [beadId]);
    await pool.query('DELETE FROM beads WHERE project_id = $1', [projectId]);
    await pool.query('DELETE FROM agent_jobs WHERE project_id = $1', [projectId]);
    await pool.query('DELETE FROM activity_log WHERE project_id = $1', [projectId]);
    await pool.query('DELETE FROM notifications WHERE user_id = $1', [userId]);
    await pool.query('DELETE FROM settings WHERE user_id = $1', [userId]);
    await pool.query('DELETE FROM project_memory WHERE project_id = $1', [projectId]);
    await pool.query('DELETE FROM global_memory WHERE user_id = $1', [userId]);
    await pool.query('DELETE FROM project_members WHERE project_id = $1', [projectId]);
    await pool.query('DELETE FROM project_invitations WHERE project_id = $1', [projectId]);
    await pool.query('DELETE FROM project_agent_config WHERE project_id = $1', [projectId]);
    await pool.query('DELETE FROM bead_sync_state WHERE project_id = $1', [projectId]);
    await pool.query('DELETE FROM api_tokens WHERE user_id = $1', [userId]);
    await pool.query('DELETE FROM auth_events WHERE user_id = $1', [userId]);
    await pool.query('DELETE FROM projects WHERE id = $1', [projectId]);
    await pool.query('DELETE FROM sessions WHERE user_id = $1', [userId]);
    await pool.query('DELETE FROM users WHERE id = $1', [userId]);
    await pool.end();
  });

  // ── Users ──────────────────────────────────────────────────────────────
  it('creates and finds a user', async () => {
    await userOps.create(userId, 'testuser', 'Test User', 'https://avatar.test/1', 'test@example.com', null, 'google-123');
    const user = await userOps.findById(userId);
    expect(user).toBeTruthy();
    expect(user!.username).toBe('testuser');
    expect(user!.email).toBe('test@example.com');
  });

  it('finds user by google ID', async () => {
    const user = await userOps.findByGoogleId('google-123');
    expect(user).toBeTruthy();
    expect(user!.id).toBe(userId);
  });

  it('finds user by email', async () => {
    const user = await userOps.findByEmail('test@example.com');
    expect(user).toBeTruthy();
    expect(user!.id).toBe(userId);
  });

  it('updates a user', async () => {
    await userOps.update('Updated User', 'https://avatar.test/2', 'test@example.com', null, userId);
    const user = await userOps.findById(userId);
    expect(user!.displayName).toBe('Updated User');
  });

  it('updates last login', async () => {
    await userOps.updateLastLogin(userId);
    const user = await userOps.findById(userId);
    expect(user!.lastLoginAt).toBeTruthy();
  });

  it('counts users', async () => {
    const result = await userOps.countAll();
    expect(result!.count).toBeGreaterThanOrEqual(1);
  });

  it('filters users', async () => {
    const results = await userOps.findAllFiltered('%test%', '%test%', '%test%', 10, 0);
    expect(results.length).toBeGreaterThanOrEqual(1);
  });

  // ── Sessions ───────────────────────────────────────────────────────────
  it('creates and finds a session', async () => {
    const sessionId = randomUUID();
    const expires = new Date(Date.now() + 86400000).toISOString();
    await sessionOps.create(sessionId, userId, expires);
    const session = await sessionOps.findById(sessionId);
    expect(session).toBeTruthy();
    expect(session!.userId).toBe(userId);
  });

  // ── Projects ───────────────────────────────────────────────────────────
  it('creates and finds a project', async () => {
    await projectOps.create(projectId, userId, 'Test Project', '/test/path', 'user/repo', 'A test project', 'claude', 'claude-sonnet-4-20250514', 'pr', false);
    const project = await projectOps.findById(projectId);
    expect(project).toBeTruthy();
    expect(project!.name).toBe('Test Project');
    expect(project!.githubSyncEnabled).toBe(false);
  });

  it('finds projects by user', async () => {
    const projects = await projectOps.findByUserId(userId);
    expect(projects.length).toBeGreaterThanOrEqual(1);
  });

  it('finds accessible projects (UNION ALL query)', async () => {
    const projects = await projectOps.findAccessibleByUserId(userId, userId);
    expect(projects).toBeTruthy();
  });

  it('finds by ID prefix', async () => {
    const prefix = projectId.substring(0, 8);
    const results = await projectOps.findByIdPrefix(prefix);
    expect(results.length).toBeGreaterThanOrEqual(1);
  });

  // ── Project Members ────────────────────────────────────────────────────
  it('adds and finds project member', async () => {
    // Create a second user for membership
    const memberId = randomUUID();
    await userOps.create(memberId, 'member', 'Member User', null, 'member@test.com', null, null);
    await projectMemberOps.add(projectId, memberId, 'member', null);
    const membership = await projectMemberOps.findMembership(projectId, memberId);
    expect(membership).toBeTruthy();
    expect(membership!.role).toBe('member');

    // Test JOIN query
    const withUsers = await projectMemberOps.findByProjectIdWithUsers(projectId);
    expect(withUsers.length).toBeGreaterThanOrEqual(1);

    // Cleanup
    await projectMemberOps.remove(projectId, memberId);
    await pool.query('DELETE FROM users WHERE id = $1', [memberId]);
  });

  // ── Settings (upsert) ─────────────────────────────────────────────────
  it('upserts and reads settings', async () => {
    await settingsOps.set(userId, 'theme', 'dark', 'dark');
    const setting = await settingsOps.get(userId, 'theme');
    expect(setting).toBeTruthy();
    expect(setting!.value).toBe('dark');

    // Update via upsert
    await settingsOps.set(userId, 'theme', 'light', 'light');
    const updated = await settingsOps.get(userId, 'theme');
    expect(updated!.value).toBe('light');
  });

  // ── Beads ──────────────────────────────────────────────────────────────
  it('creates and finds a bead', async () => {
    await beadOps.create(beadId, projectId, 'Test Bead', 'A test bead description', 'pending', 2, null, null, null, null, null, null, null, null, 'task', null);
    const bead = await beadOps.findById(beadId);
    expect(bead).toBeTruthy();
    expect(bead!.subject).toBe('Test Bead');
    expect(bead!.status).toBe('pending');
  });

  it('updates bead status', async () => {
    await beadOps.updateStatus('in_progress', beadId);
    const bead = await beadOps.findById(beadId);
    expect(bead!.status).toBe('in_progress');
  });

  it('finds beads by project (paginated)', async () => {
    const beads = await beadOps.findByProjectIdPaginated(projectId, 10);
    expect(beads.length).toBeGreaterThanOrEqual(1);
  });

  it('finds beads filtered', async () => {
    const beads = await beadOps.findByProjectIdFiltered(
      projectId, 'in_progress', 'in_progress', null, null, null, null, null, null, null, null, null, 10
    );
    expect(beads.length).toBeGreaterThanOrEqual(1);
  });

  it('finds by ID prefix', async () => {
    const prefix = beadId.substring(0, 8);
    const results = await beadOps.findByIdPrefix(prefix);
    expect(results.length).toBeGreaterThanOrEqual(1);
  });

  // ── Bead Comments ──────────────────────────────────────────────────────
  it('creates and finds bead comments', async () => {
    const commentId = randomUUID();
    await beadCommentOps.create(commentId, beadId, projectId, userId, 'user', 'Test comment', null);
    const comments = await beadCommentOps.findByBeadId(beadId);
    expect(comments.length).toBe(1);
    expect(comments[0].content).toBe('Test comment');
  });

  // ── Agent Jobs ─────────────────────────────────────────────────────────
  it('creates and queries agent jobs', async () => {
    const jobId = randomUUID();
    await agentJobOps.create(jobId, projectId, beadId, 'Fix the bug', 'queued', 'e2b', 2, null, null, null, null, null, null, 'execution');
    const job = await agentJobOps.findById(jobId);
    expect(job).toBeTruthy();
    expect(job!.prompt).toBe('Fix the bug');

    const byBead = await agentJobOps.findByBeadId(beadId);
    expect(byBead.length).toBeGreaterThanOrEqual(1);

    const queued = await agentJobOps.findQueued('queued', 10);
    expect(queued.length).toBeGreaterThanOrEqual(1);
  });

  // ── Notifications ──────────────────────────────────────────────────────
  it('creates and reads notifications', async () => {
    const notifId = randomUUID();
    await notificationOps.create(notifId, userId, 'info', 'Test Notification', 'Hello', null, null, null, null);
    const unread = await notificationOps.countUnread(userId);
    expect(unread!.count).toBeGreaterThanOrEqual(1);

    await notificationOps.markRead(notifId);
    const afterRead = await notificationOps.countUnread(userId);
    expect(afterRead!.count).toBeLessThan(unread!.count);
  });

  // ── Activity Log ───────────────────────────────────────────────────────
  it('creates and reads activity log', async () => {
    const logId = randomUUID();
    await activityLogOps.create(logId, projectId, userId, 'user', 'bead.created', 'bead', beadId, null, null);
    const logs = await activityLogOps.findByProjectId(projectId, 10);
    expect(logs.length).toBeGreaterThanOrEqual(1);
  });

  // ── Project Memory (upsert) ───────────────────────────────────────────
  it('upserts and reads project memory', async () => {
    const memId = randomUUID();
    await projectMemoryOps.upsert(memId, projectId, 'context', 'initial value', null, 'initial value', null);
    const mem = await projectMemoryOps.findByProjectIdAndKey(projectId, 'context');
    expect(mem).toBeTruthy();
    expect(mem!.content).toBe('initial value');

    // Update via upsert
    await projectMemoryOps.upsert(memId, projectId, 'context', 'updated value', null, 'updated value', null);
    const updated = await projectMemoryOps.findByProjectIdAndKey(projectId, 'context');
    expect(updated!.content).toBe('updated value');
  });

  // ── Global Memory (upsert) ────────────────────────────────────────────
  it('upserts and reads global memory', async () => {
    const memId = randomUUID();
    await globalMemoryOps.upsert(memId, userId, 'pref', 'value1', 'value1');
    const mem = await globalMemoryOps.findByUserIdAndKey(userId, 'pref');
    expect(mem).toBeTruthy();
    expect(mem!.content).toBe('value1');
  });

  // ── Organizations ──────────────────────────────────────────────────────
  it('creates org with members', async () => {
    await orgOps.create(orgId, 'Test Org', 'test-org', userId, null, 'member');
    await orgMemberOps.add(orgId, userId, 'owner');

    const org = await orgOps.findById(orgId);
    expect(org).toBeTruthy();
    expect(org!.name).toBe('Test Org');

    const members = await orgMemberOps.findByOrgId(orgId);
    expect(members.length).toBe(1);

    const memberCount = await orgMemberOps.countByOrgId(orgId);
    expect(memberCount!.count).toBe(1);
  });

  // ── Teams ──────────────────────────────────────────────────────────────
  it('creates team with members and projects', async () => {
    await teamOps.create(teamId, orgId, 'Test Team', 'test-team', 'A test team');
    await teamMemberOps.add(teamId, userId, 'lead');
    await teamProjectOps.add(teamId, projectId, 'admin');

    const team = await teamOps.findById(teamId);
    expect(team).toBeTruthy();
    expect(team!.name).toBe('Test Team');

    const teamMembers = await teamMemberOps.findByTeamId(teamId);
    expect(teamMembers.length).toBe(1);

    const teamProjects = await teamProjectOps.findByTeamId(teamId);
    expect(teamProjects.length).toBe(1);
  });

  // ── API Tokens ─────────────────────────────────────────────────────────
  it('creates and finds API tokens', async () => {
    const tokenId = randomUUID();
    await apiTokenOps.create(tokenId, userId, 'Test Token', 'dd_test', 'hash_abc123');
    const token = await apiTokenOps.findByHash('hash_abc123');
    expect(token).toBeTruthy();
    expect(token!.name).toBe('Test Token');

    await apiTokenOps.revoke(tokenId, userId);
    const revoked = await apiTokenOps.findByHash('hash_abc123');
    expect(revoked).toBeNull(); // revoked tokens shouldn't be found
  });

  // ── Auth Events ────────────────────────────────────────────────────────
  it('creates and queries auth events', async () => {
    const eventId = randomUUID();
    await authEventOps.create(eventId, userId, 'test@example.com', 'login', 'google', '127.0.0.1', 'test-agent', null);

    const recent = await authEventOps.findRecent(10);
    expect(recent).toBeTruthy();

    const countByType = await authEventOps.countByType();
    expect(countByType).toBeTruthy();

    const last7 = await authEventOps.countLast7Days();
    expect(last7).toBeTruthy();
  });

  // ── Bead Sync State (upsert) ──────────────────────────────────────────
  it('upserts bead sync state', async () => {
    const now = new Date().toISOString();
    await beadSyncStateOps.upsert(projectId, 'hash123', now, null, 'hash123', now, null);
    const state = await beadSyncStateOps.findByProjectId(projectId);
    expect(state).toBeTruthy();
    expect(state!.localFileHash).toBe('hash123');
  });

  // ── Project Agent Config (upsert) ─────────────────────────────────────
  it('upserts agent config', async () => {
    const config = JSON.stringify({ model: 'claude-sonnet-4-20250514' });
    await agentConfigOps.upsert(projectId, config, config);
    const result = await agentConfigOps.findByProjectId(projectId);
    expect(result).toBeTruthy();
    expect(result!.config).toBe(config);
  });

  // ── Readiness Outcomes ─────────────────────────────────────────────────
  it('inserts and queries readiness outcomes', async () => {
    const outcomeId = randomUUID();
    await readinessOutcomeOps.insert(outcomeId, projectId, beadId, null, 'A', 'low', 'success', null, false);
    const stats = await readinessOutcomeOps.statsByGrade(projectId);
    expect(stats).toBeTruthy();
  });
});

