/**
 * Smoke test for the async Postgres ops layer.
 * Runs against live Railway Postgres — requires POSTGRES_URL env var.
 *
 * Usage: POSTGRES_URL="postgresql://..." npx vitest run src/db/__tests__/ops-smoke.test.ts
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { randomUUID } from 'crypto';

// Must set POSTGRES_URL before importing ops (postgres.ts reads it at module load)
if (!process.env.POSTGRES_URL) {
  throw new Error('POSTGRES_URL env var required for smoke tests');
}

const {
  userOps, sessionOps, projectOps, projectMemberOps, projectInvitationOps,
  agentOps, settingsOps, planOps, planItemOps, projectMemoryOps, globalMemoryOps,
  githubSyncOps, agentSessionOps, agentJobOps, credentialOps, beadOps,
  beadCommentOps, notificationOps, activityLogOps, apiTokenOps, orgOps,
  orgMemberOps, teamOps, teamMemberOps, teamProjectOps, drainOps,
  worktreeRunOps, beadSyncStateOps, readinessOutcomeOps, agentConfigOps,
  installationOps, installationRepoOps, orgInvitationOps, ssoLinkOps,
  authEventOps, auditLogOps, initializeDatabase,
} = await import('../ops.js');

import { pool } from '../postgres.js';

// Test IDs — cleaned up in afterAll
const userId = randomUUID();
const projectId = randomUUID();
const beadId = randomUUID();
const orgId = randomUUID();
const teamId = randomUUID();

async function cleanupTestData() {
  // Clean in reverse FK dependency order
  await pool.query('DELETE FROM team_projects WHERE team_id = $1', [teamId]);
  await pool.query('DELETE FROM team_members WHERE team_id = $1', [teamId]);
  await pool.query('DELETE FROM teams WHERE id = $1', [teamId]);
  await pool.query('DELETE FROM organization_invitations WHERE org_id = $1', [orgId]);
  await pool.query('DELETE FROM organization_members WHERE org_id = $1', [orgId]);
  await pool.query('DELETE FROM organizations WHERE id = $1', [orgId]);
  await pool.query('DELETE FROM bead_comments WHERE bead_id = $1', [beadId]);
  await pool.query('DELETE FROM readiness_outcomes WHERE project_id = $1', [projectId]);
  await pool.query('DELETE FROM agent_jobs WHERE project_id = $1', [projectId]);
  await pool.query('DELETE FROM beads WHERE project_id = $1', [projectId]);
  await pool.query('DELETE FROM activity_log WHERE project_id = $1', [projectId]);
  await pool.query('DELETE FROM notifications WHERE user_id = $1', [userId]);
  await pool.query('DELETE FROM settings WHERE user_id = $1', [userId]);
  await pool.query('DELETE FROM project_memory WHERE project_id = $1', [projectId]);
  await pool.query('DELETE FROM global_memory WHERE user_id = $1', [userId]);
  await pool.query('DELETE FROM project_members WHERE project_id = $1', [projectId]);
  await pool.query('DELETE FROM project_invitations WHERE project_id = $1', [projectId]);
  await pool.query('DELETE FROM project_agent_config WHERE project_id = $1', [projectId]);
  await pool.query('DELETE FROM bead_sync_state WHERE project_id = $1', [projectId]);
  await pool.query('DELETE FROM api_tokens WHERE user_id = $1', [userId]);
  await pool.query('DELETE FROM auth_events WHERE user_id = $1', [userId]);
  await pool.query('DELETE FROM projects WHERE id = $1', [projectId]);
  await pool.query('DELETE FROM sessions WHERE user_id = $1', [userId]);
  // Clean up any user with google_id='google-123' from previous runs (cascade manually)
  const staleUsers = await pool.query("SELECT id FROM users WHERE google_id = 'google-123'");
  for (const row of staleUsers.rows) {
    await pool.query('DELETE FROM projects WHERE user_id = $1', [row.id]);
    await pool.query('DELETE FROM sessions WHERE user_id = $1', [row.id]);
    await pool.query('DELETE FROM settings WHERE user_id = $1', [row.id]);
    await pool.query('DELETE FROM global_memory WHERE user_id = $1', [row.id]);
    await pool.query('DELETE FROM notifications WHERE user_id = $1', [row.id]);
    await pool.query('DELETE FROM api_tokens WHERE user_id = $1', [row.id]);
    await pool.query('DELETE FROM auth_events WHERE user_id = $1', [row.id]);
    await pool.query('DELETE FROM users WHERE id = $1', [row.id]);
  }
  await pool.query('DELETE FROM users WHERE id = $1', [userId]);
}

