import { EventEmitter } from 'events';
import { v4 as uuidv4 } from 'uuid';
import { jobQueue, type AgentJob, type JobResult } from './job-queue.js';
import { runAgentLoop, type AgentLoopResult } from './agent-loop.js';
import type { Worker } from './workers/worker.js';
import { dockerWorkerPool } from './workers/docker-worker.js';
import { projectOps, beadOps, notificationOps, worktreeRunOps, agentJobOps, projectMemoryOps } from '../db/sqlite.js';
import { logActivity } from './activity-logger.js';
import { createSystemComment } from '../routes/bead-comments.js';
import { projectEvents as projEvents } from './project-events.js';
import { resolveGitHubToken } from './github-app.js';
import { githubService } from './github.js';
import { syncOutbox } from './sync-outbox.js';
import { transitionStatus } from './bead-lifecycle.js';
import { detectProjectRuntime, invalidateRuntimeCache, type ProjectRuntime } from './project-runtime.js';
import { runFailurePostflight } from './failure-postflight.js';
import {
  getAIProvider,
  callAIStructured,
  selectRelevantFiles,
  runAnalysis,
  type TaskAnalysis,
} from './task-analyzer.js';
import { repoAnalyzer, type RepoAnalysis } from './repo-analyzer.js';
import { resolveModel } from './model-resolver.js';

// Lazy-load E2B to avoid crashing if the e2b package isn't compatible with the Node version
let _e2bPool: any = null;
async function getE2BPool() {
  if (!_e2bPool) {
    const mod = await import('./workers/e2b-worker.js');
    _e2bPool = mod.workerPool;
  }
  return _e2bPool as import('./workers/e2b-worker.js').E2BWorkerPool;
}

export interface DispatchEvent {
  jobId: string;
  type: 'started' | 'output' | 'completed' | 'failed' | 'cancelled';
  data?: any;
  timestamp: string;
}

/**
 * Shared sandbox context returned by prepareSandbox().
 * Both execution and analysis jobs use this after preflight.
 */
export interface SandboxContext {
  worker: Worker;
  runtime: ProjectRuntime;

