import { Router } from 'express';
import { requireAuth } from '../middleware/auth.js';
import { requireProjectAccess, getAccessibleProjectIds } from '../middleware/project-access.js';
import { projectEvents, type ProjectEvent } from '../services/project-events.js';
import { orgMemberOps, projectOps } from '../db/sqlite.js';

const router = Router();

router.use(requireAuth);

/**
 * GET /api/events?projectId=xxx - SSE stream for project data changes
 * GET /api/events?orgId=xxx    - SSE stream for org-wide data changes
 * GET /api/events              - SSE stream for all user-accessible projects
 *
 * Clients connect to this endpoint and receive events when beads or jobs
 * change. The user-level mode (no params) covers all projects the
 * authenticated user can access, enabling real-time updates on pages
 * like Dashboard and Jobs that aren't scoped to a single project or org.
 */
router.get('/', (req, res) => {
  const { projectId, orgId } = req.query;

  // User-level SSE: no projectId or orgId required — matches all accessible projects
  let userProjectIds: Set<string> | null = null;

  // Validate access
  if (projectId && typeof projectId === 'string') {
    const project = requireProjectAccess(projectId, req.user!.id);
    if (!project) {
      return res.status(404).json({ error: 'Project not found' });
    }
  }

  let orgProjectIds: Set<string> | null = null;
  if (orgId && typeof orgId === 'string') {
    const membership = orgMemberOps.findMembership.get(orgId, req.user!.id) as any;
    if (!membership) {
      return res.status(403).json({ error: 'Not an org member' });
    }
    // Get all project IDs for this org
    const orgProjects = projectOps.findByOrgId.all(orgId) as any[];
    orgProjectIds = new Set(orgProjects.map((p: any) => p.id));
  }

  // User-level fallback: no project or org specified — subscribe to all accessible projects
  if (!projectId && !orgId) {
    const accessibleIds = getAccessibleProjectIds(req.user!.id);
    userProjectIds = new Set(accessibleIds);
  }

  // SSE headers
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no'); // Disable nginx buffering
  res.flushHeaders();

  // Send initial heartbeat
  res.write(': connected\n\n');

  // Listen for project change events
  const onEvent = (event: ProjectEvent) => {
    const matches = projectId
      ? event.projectId === projectId
      : orgProjectIds?.has(event.projectId)
        ?? userProjectIds?.has(event.projectId)
        ?? false;

    if (matches) {
      const data = JSON.stringify({
        projectId: event.projectId,
        orgId: orgId || undefined,
        timestamp: Date.now(),
      });
      res.write(`event: ${event.type}\ndata: ${data}\n\n`);
    }
  };

  projectEvents.on('change', onEvent);

  // Heartbeat every 30 seconds to keep connection alive
  const heartbeat = setInterval(() => {
    res.write(': heartbeat\n\n');
  }, 30000);

  // Cleanup on disconnect
  req.on('close', () => {
    clearInterval(heartbeat);
    projectEvents.removeListener('change', onEvent);
  });
});

export default router;

