216	 *
217	 * Fetches live PR status from GitHub for all PRs created by a drain's jobs.
218	 */
219	router.get('/:projectId/drains/:drainId/pr-status', async (req, res) => {
220	  try {
221	    const { projectId, drainId } = req.params;
222	    const userId = (req.user as any).id;
223	
224	    const project = requirePermission(projectId, userId, 'dispatch_agents');
225	    if (!project) {
226	      return res.status(403).json({ error: 'dispatch_agents permission required' });
227	    }
228	
229	    const drain = drainOps.findById.get(drainId) as any;
230	    if (!drain || drain.project_id !== projectId) {
231	      return res.status(404).json({ error: 'Drain not found' });
232	    }
233	
234	    // Get all jobs for this drain that have PR URLs
235	    const jobs = agentJobOps.findByDrainId.all(drainId) as any[];
236	    const jobsWithPRs = jobs.filter((j) => {
237	      if (!j.result) return false;
238	      try {
239	        const result = typeof j.result === 'string' ? JSON.parse(j.result) : j.result;
240	        return !!result.prUrl;
241	      } catch {
242	        return false;
243	      }
244	    });
245	
246	    if (jobsWithPRs.length === 0) {
247	      return res.json({ data: [] });
248	    }
249	
250	    // Resolve GitHub token
251	    const resolved = await resolveGitHubToken(project.user_id, project.github_repo);
252	    if (!resolved) {
253	      return res.status(400).json({ error: 'No GitHub credentials available' });
254	    }
255	
256	    // Fetch PR status for each job
257	    const prStatuses = await Promise.all(
258	      jobsWithPRs.map(async (job) => {
259	        try {
260	          const result = typeof job.result === 'string' ? JSON.parse(job.result) : job.result;
261	          const prUrl: string = result.prUrl;
262	
263	          // Parse owner/repo/number from PR URL
264	          const match = prUrl.match(/github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/);
265	          if (!match) return null;
266	
267	          const [, owner, repo, numberStr] = match;
268	          const prNumber = parseInt(numberStr, 10);
269	
270	          // Fetch PR details
271	          const prResp = await fetch(
272	            `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
273	            { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
274	          );
275	          if (!prResp.ok) return null;
276	          const pr: any = await prResp.json();
277	
278	          // Determine CI status from the head commit
279	          let ciStatus: 'success' | 'failure' | 'pending' | 'none' = 'none';
280	          if (pr.head?.sha) {
281	            const statusResp = await fetch(
282	              `https://api.github.com/repos/${owner}/${repo}/commits/${pr.head.sha}/status`,
283	              { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
284	            );
285	            if (statusResp.ok) {
