287	              ciStatus = statusData.state === 'success' ? 'success'
288	                : statusData.state === 'failure' ? 'failure'
289	                : statusData.state === 'pending' ? 'pending'
290	                : 'none';
291	            }
292	          }
293	
294	          // Determine review status
