297	            `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}/reviews`,
298	            { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
299	          );
300	          if (reviewsResp.ok) {
301	            const reviews = await reviewsResp.json();
302	            if (Array.isArray(reviews) && reviews.length > 0) {
303	              // Use the latest review per user
304	              const latest = reviews[reviews.length - 1];
305	              if (latest.state === 'APPROVED') reviewStatus = 'approved';
306	              else if (latest.state === 'CHANGES_REQUESTED') reviewStatus = 'changes_requested';
307	              else reviewStatus = 'pending';
308	            }
309	          }
310	
