460	    if (!parentBead || parentBead.project_id !== projectId) {
461	      return res.status(404).json({ error: 'Parent bead not found in this project' });
462	    }
463	
464	    const children = beadOps.findChildrenByParent.all(parentBeadId) as any[];
465	    const childIds = new Set(children.map((c: any) => c.id));
466	
467	    // Auto-score unscored children
468	    const allBeads = beadOps.findByProjectId.all(projectId) as any[];
469	    for (const child of children) {
470	      if (child.automability_score == null && child.pre_instructions) {
471	        try { scoreAndPersist(child, allBeads); } catch { /* non-fatal */ }
472	      }
473	    }
474	
475	    // Re-read children to get updated scores
476	    const freshChildren = beadOps.findChildrenByParent.all(parentBeadId) as any[];
477	
478	    // Build dependency graph and compute phases (topological layers)
479	    const phases: any[][] = [];
480	    const placed = new Set<string>();
481	    let remaining = [...freshChildren];
482	
483	    while (remaining.length > 0) {
484	      const phase: any[] = [];
485	      const nextRemaining: any[] = [];
486	
487	      for (const child of remaining) {
488	        const blockedBy: string[] = child.blocked_by ? JSON.parse(child.blocked_by) : [];
489	        // Only consider dependencies within this epic's children
