import { Router } from 'express';
import { requireAuth } from '../middleware/auth.js';
import { requirePermission } from '../middleware/project-access.js';
import { validate } from '../middleware/validate.js';
import { StartDrainBody, DrainPreviewQuery, DrainListQuery, UpdateDrainChecklistBody } from '../schemas/index.js';
import { drainManager } from '../services/drain-manager.js';
import { drainOps, agentJobOps, beadOps } from '../db/sqlite.js';
import { resolveGitHubToken } from '../services/github-app.js';
import { logActivity } from '../services/activity-logger.js';
import { scoreProjectBeads, scoreSpecificBead, scoreAndPersist, scoreBeadWithAI, refreshStaleScores } from '../services/burn-scorer.js';

const router = Router();

router.use(requireAuth);

/**
 * POST /api/projects/:projectId/drain — Start a drain
 *
 * Body options (all optional):
 *   beadIds: string[]      — specific beads to process (+ their children as they unblock)
 *   autoSelect: boolean    — let server pick ready leaf beads
 *   maxAutoSelect: number  — cap for auto-select (default 10)
 *   maxJobs: number        — max total jobs before stopping (default unlimited)
 */
router.post('/:projectId/drain', validate({ body: StartDrainBody }), (req, res) => {
  try {
    const projectId = req.params.projectId as string;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const { beadIds, autoSelect, maxAutoSelect, maxJobs, minAutomability, parentBeadId, strategy } = req.body as StartDrainBody;

    const result = drainManager.start(projectId, userId, {
      beadIds,
      autoSelect,
      maxAutoSelect,
      maxJobs,
      minAutomability,
      parentBeadId,
      strategy: strategy as 'priority' | 'automability' | undefined,
    });

    logActivity({
      projectId,
      actorId: userId,
      actorType: 'user',
      action: 'drain.started',
      targetType: 'drain',
      targetId: result.drainId,
      metadata: { drainId: result.drainId, scopeSize: result.scopeSize, jobsCreated: result.jobsCreated.length },
    });

    res.json({
      success: true,
      active: true,
      ...result,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to start drain';
    console.error('[Drain Route] Start error:', message);
    res.status(500).json({ error: message });
  }
});

/**
 * GET /api/projects/:projectId/drain — Get drain status
 */
router.get('/:projectId/drain', (req, res) => {
  try {
    const { projectId } = req.params;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const status = drainManager.getStatus(projectId);
    res.json(status);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to get drain status';
    res.status(500).json({ error: message });
  }
});

/**
 * DELETE /api/projects/:projectId/drain — Stop a drain
 */
router.delete('/:projectId/drain', (req, res) => {
  try {
    const { projectId } = req.params;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const stopped = drainManager.stop(projectId);
    res.json({ success: true, wasDraining: stopped });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to stop drain';
    res.status(500).json({ error: message });
  }
});

/**
 * GET /api/projects/:projectId/drain/summary — Get last drain summary
 */
router.get('/:projectId/drain/summary', (req, res) => {
  try {
    const { projectId } = req.params;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const summary = drainManager.getLastSummary(projectId);
    if (!summary) {
      return res.status(404).json({ error: 'No drain summary available' });
    }

    res.json(summary);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to get drain summary';
    res.status(500).json({ error: message });
  }
});

/**
 * GET /api/projects/:projectId/drain/preview — Preview auto-select candidates
 *
 * Query params:
 *   maxCount: number (default 10)
 */
router.get('/:projectId/drain/preview', validate({ query: DrainPreviewQuery }), (req, res) => {
  try {
    const projectId = req.params.projectId as string;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const { maxCount = 10, minAutomability, strategy: rawStrategy } = req.query as unknown as DrainPreviewQuery;
    const strategy = rawStrategy === 'automability' ? 'automability' as const : undefined;
    const candidates = drainManager.previewAutoSelect(projectId, maxCount, minAutomability, strategy);

    res.json({ candidates, count: candidates.length });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to preview';
    res.status(500).json({ error: message });
  }
});

/**
 * GET /api/projects/:projectId/drains — List recent drains for a project
 *
 * Query params:
 *   limit: number (default 20)
 */
router.get('/:projectId/drains', validate({ query: DrainListQuery }), (req, res) => {
  try {
    const projectId = req.params.projectId as string;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const { limit } = req.query as unknown as DrainListQuery;
    const drains = drainOps.findByProjectIdPaginated.all(projectId, Math.min(limit, 100));
    res.json({ data: drains });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to list drains';
    res.status(500).json({ error: message });
  }
});

/**
 * GET /api/projects/:projectId/drains/:drainId — Single drain with its jobs
 */
router.get('/:projectId/drains/:drainId', (req, res) => {
  try {
    const { projectId, drainId } = req.params;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const drain = drainOps.findById.get(drainId) as any;
    if (!drain || drain.project_id !== projectId) {
      return res.status(404).json({ error: 'Drain not found' });
    }

    const jobs = agentJobOps.findByDrainId.all(drainId);
    res.json({ ...drain, jobs });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to get drain';
    res.status(500).json({ error: message });
  }
});

/**
 * GET /api/projects/:projectId/drains/:drainId/pr-status
 *
 * Fetches live PR status from GitHub for all PRs created by a drain's jobs.
 */
router.get('/:projectId/drains/:drainId/pr-status', async (req, res) => {
  try {
    const { projectId, drainId } = req.params;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const drain = drainOps.findById.get(drainId) as any;
    if (!drain || drain.project_id !== projectId) {
      return res.status(404).json({ error: 'Drain not found' });
    }

    // Get all jobs for this drain that have PR URLs
    const jobs = agentJobOps.findByDrainId.all(drainId) as any[];
    const jobsWithPRs = jobs.filter((j) => {
      if (!j.result) return false;
      try {
        const result = typeof j.result === 'string' ? JSON.parse(j.result) : j.result;
        return !!result.prUrl;
      } catch {
        return false;
      }
    });

    if (jobsWithPRs.length === 0) {
      return res.json({ data: [] });
    }

    // Resolve GitHub token
    const resolved = await resolveGitHubToken(project.user_id, project.github_repo);
    if (!resolved) {
      return res.status(400).json({ error: 'No GitHub credentials available' });
    }

    // Fetch PR status for each job
    const prStatuses = await Promise.all(
      jobsWithPRs.map(async (job) => {
        try {
          const result = typeof job.result === 'string' ? JSON.parse(job.result) : job.result;
          const prUrl: string = result.prUrl;

          // Parse owner/repo/number from PR URL
          const match = prUrl.match(/github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/);
          if (!match) return null;

          const [, owner, repo, numberStr] = match;
          const prNumber = parseInt(numberStr, 10);

          // Fetch PR details
          const prResp = await fetch(
            `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
            { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
          );
          if (!prResp.ok) return null;
          const pr: any = await prResp.json();

          // Determine CI status from the head commit
          let ciStatus: 'success' | 'failure' | 'pending' | 'none' = 'none';
          if (pr.head?.sha) {
            const statusResp = await fetch(
              `https://api.github.com/repos/${owner}/${repo}/commits/${pr.head.sha}/status`,
              { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
            );
            if (statusResp.ok) {
              const statusData: any = await statusResp.json();
              ciStatus = statusData.state === 'success' ? 'success'
                : statusData.state === 'failure' ? 'failure'
                : statusData.state === 'pending' ? 'pending'
                : 'none';
            }
          }

          // Determine review status
          let reviewStatus: 'approved' | 'changes_requested' | 'pending' | 'none' = 'none';
          const reviewsResp = await fetch(
            `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}/reviews`,
            { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
          );
          if (reviewsResp.ok) {
            const reviews = await reviewsResp.json();
            if (Array.isArray(reviews) && reviews.length > 0) {
              // Use the latest review per user
              const latest = reviews[reviews.length - 1];
              if (latest.state === 'APPROVED') reviewStatus = 'approved';
              else if (latest.state === 'CHANGES_REQUESTED') reviewStatus = 'changes_requested';
              else reviewStatus = 'pending';
            }
          }

          return {
            jobId: job.id,
            prUrl,
            prNumber,
            state: pr.merged ? 'merged' as const : pr.state as 'open' | 'closed',
            mergeable: pr.mergeable,
            ciStatus,
            reviewStatus,
            title: pr.title,
            mergedAt: pr.merged_at || null,
          };
        } catch (err) {
          console.warn(`[PR Status] Failed to fetch PR status for job ${job.id}:`, err);
          return null;
        }
      })
    );

    res.json({ data: prStatuses.filter(Boolean) });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to fetch PR statuses';
    console.error('[Drain Route] PR status error:', message);
    res.status(500).json({ error: message });
  }
});

/**
 * POST /api/projects/:projectId/pulls/:prNumber/merge
 *
 * Merges a single PR via GitHub API using squash merge.
 */
router.post('/:projectId/pulls/:prNumber/merge', async (req, res) => {
  try {
    const { projectId, prNumber } = req.params;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    if (!project.github_repo) {
      return res.status(400).json({ error: 'Project has no GitHub repo configured' });
    }

    const resolved = await resolveGitHubToken(project.user_id, project.github_repo);
    if (!resolved) {
      return res.status(400).json({ error: 'No GitHub credentials available' });
    }

    const [owner, repo] = project.github_repo.split('/');

    // Double-check PR is mergeable before merging
    const prResp = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
      { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
    );
    if (!prResp.ok) {
      return res.status(404).json({ error: 'PR not found' });
    }
    const pr: any = await prResp.json();
    if (pr.merged) {
      return res.json({ merged: true, alreadyMerged: true });
    }
    if (pr.mergeable === false) {
      return res.status(409).json({ error: 'PR is not mergeable (has conflicts or failing checks)' });
    }

    // Merge with squash
    const mergeResp = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}/merge`,
      {
        method: 'PUT',
        headers: {
          Authorization: `token ${resolved.token}`,
          Accept: 'application/vnd.github.v3+json',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ merge_method: 'squash' }),
      }
    );

    if (!mergeResp.ok) {
      const errData: any = await mergeResp.json().catch(() => ({}));
      return res.status(mergeResp.status).json({
        error: errData.message || `Merge failed with status ${mergeResp.status}`,
      });
    }

    const mergeData: any = await mergeResp.json();
    res.json({ merged: true, sha: mergeData.sha, message: mergeData.message });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to merge PR';
    console.error('[Drain Route] Merge error:', message);
    res.status(500).json({ error: message });
  }
});

/**
 * PATCH /api/projects/:projectId/drains/:drainId/checklist
 *
 * Persists interactive checklist check state for a drain.
 * Body: { checked: boolean[] }
 */
router.patch('/:projectId/drains/:drainId/checklist', validate({ body: UpdateDrainChecklistBody }), (req, res) => {
  try {
    const projectId = req.params.projectId as string;
    const drainId = req.params.drainId as string;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const drain = drainOps.findById.get(drainId) as any;
    if (!drain || drain.project_id !== projectId) {
      return res.status(404).json({ error: 'Drain not found' });
    }

    const { checked } = req.body as UpdateDrainChecklistBody;

    drainOps.updateChecklistState.run(JSON.stringify(checked), drainId);

    res.json({ success: true, checklistState: checked });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to update checklist';
    res.status(500).json({ error: message });
  }
});

/**
 * GET /api/projects/:projectId/burn/epic/:parentBeadId — Epic burndown view
 *
 * Returns children of a parent bead with burn scores, grouped into phases
 * by dependency ordering. Children without dependencies come first.
 */
router.get('/:projectId/burn/epic/:parentBeadId', (req, res) => {
  try {
    const { projectId, parentBeadId } = req.params;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    // Verify parent bead exists in this project
    const parentBead = beadOps.findById.get(parentBeadId) as any;
    if (!parentBead || parentBead.project_id !== projectId) {
      return res.status(404).json({ error: 'Parent bead not found in this project' });
    }

    const children = beadOps.findChildrenByParent.all(parentBeadId) as any[];
    const childIds = new Set(children.map((c: any) => c.id));

    // Auto-score unscored children
    const allBeads = beadOps.findByProjectId.all(projectId) as any[];
    for (const child of children) {
      if (child.automability_score == null && child.pre_instructions) {
        try { scoreAndPersist(child, allBeads); } catch { /* non-fatal */ }
      }
    }

    // Re-read children to get updated scores
    const freshChildren = beadOps.findChildrenByParent.all(parentBeadId) as any[];

    // Build dependency graph and compute phases (topological layers)
    const phases: any[][] = [];
    const placed = new Set<string>();
    let remaining = [...freshChildren];

    while (remaining.length > 0) {
      const phase: any[] = [];
      const nextRemaining: any[] = [];

      for (const child of remaining) {
        const blockedBy: string[] = child.blocked_by ? JSON.parse(child.blocked_by) : [];
        // Only consider dependencies within this epic's children
        const unresolvedDeps = blockedBy.filter((id: string) => childIds.has(id) && !placed.has(id));
        if (unresolvedDeps.length === 0) {
          phase.push(child);
        } else {
          nextRemaining.push(child);
        }
      }

      if (phase.length === 0) {
        // Cycle detected — dump remaining into final phase
        phases.push(remaining);
        break;
      }

      // Sort phase by automability DESC
      phase.sort((a: any, b: any) => (b.automability_score ?? 0) - (a.automability_score ?? 0));
      phases.push(phase);
      for (const b of phase) placed.add(b.id);
      remaining = nextRemaining;
    }

    // Stats
    const burnableCount = freshChildren.filter((c: any) => c.status === 'pending' && c.pre_instructions).length;
    const completedCount = freshChildren.filter((c: any) => c.status === 'completed').length;
    const avgAutomability = freshChildren.reduce((sum: number, c: any) => sum + (c.automability_score ?? 0), 0) / (freshChildren.length || 1);

    res.json({
      parentBead: { id: parentBead.id, subject: parentBead.subject, status: parentBead.status },
      totalChildren: freshChildren.length,
      burnableCount,
      completedCount,
      avgAutomability: Math.round(avgAutomability),
      phases: phases.map((phase, i) => ({
        phase: i + 1,
        beads: phase.map((b: any) => ({
          id: b.id,
          subject: b.subject,
          status: b.status,
          priority: b.priority,
          hasPreInstructions: !!b.pre_instructions,
          complexityScore: b.complexity_score,
          automabilityScore: b.automability_score,
          automabilityGrade: b.automability_grade,
          blockedBy: b.blocked_by ? JSON.parse(b.blocked_by) : [],
        })),
      })),
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to get epic burn view';
    console.error('[Burn Route] Epic burn error:', message);
    res.status(500).json({ error: message });
  }
});

/**
 * POST /api/projects/:projectId/beads/score — Bulk heuristic scoring
 *
 * Scores all unscored pending beads with pre_instructions in the project.
 *
 * Body options:
 *   refresh: boolean — also rescore beads with stale scores (default false)
 */
router.post('/:projectId/beads/score', (req, res) => {
  try {
    const { projectId } = req.params;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const result = scoreProjectBeads(projectId);
    let refreshed = 0;

    if (req.body?.refresh) {
      refreshed = refreshStaleScores(projectId);
    }

    res.json({
      success: true,
      scored: result.scored,
      refreshed,
      results: result.results.map((r) => ({
        beadId: r.beadId,
        complexityScore: r.score.complexityScore,
        automabilityScore: r.score.automabilityScore,
        automabilityGrade: r.score.automabilityGrade,
        factors: r.score.factors,
      })),
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to score beads';
    console.error('[Burn Scorer Route] Bulk score error:', message);
    res.status(500).json({ error: message });
  }
});

/**
 * POST /api/projects/:projectId/beads/:beadId/score — Single bead scoring
 *
 * Body options:
 *   mode: 'heuristic' (default) | 'ai' — use AI-powered scoring for higher fidelity
 */
router.post('/:projectId/beads/:beadId/score', async (req, res) => {
  try {
    const { projectId, beadId } = req.params;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    // Verify bead belongs to this project
    const bead = beadOps.findById.get(beadId) as any;
    if (!bead || bead.project_id !== projectId) {
      return res.status(404).json({ error: 'Bead not found in this project' });
    }

    const mode = req.body?.mode || 'heuristic';
    let score;

    if (mode === 'ai') {
      score = await scoreBeadWithAI(beadId);
    } else {
      score = scoreSpecificBead(beadId);
    }

    if (!score) {
      return res.status(404).json({ error: 'Bead not found' });
    }

    res.json({
      success: true,
      beadId,
      mode,
      complexityScore: score.complexityScore,
      automabilityScore: score.automabilityScore,
      automabilityGrade: score.automabilityGrade,
      factors: score.factors,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to score bead';
    console.error('[Burn Scorer Route] Single score error:', message);
    res.status(500).json({ error: message });
  }
});

export default router;

