import { Router } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { requireAuth } from '../middleware/auth.js';
import { validate } from '../middleware/validate.js';
import { DispatchJobBody, ListJobsQuery, ConflictsQuery, AnalyzeJobBody, AuditJobBody, ReconcileBody, ClassifyBody, BacklogHealthBody, DecomposeBody, RetryJobBody, ProjectIdJobQuery } from '../schemas/index.js';
import { requireProjectAccess, requirePermission, getAccessibleProjectIds } from '../middleware/project-access.js';
import { jobQueue, DuplicateJobError, type CreateJobInput, type AgentJob } from '../services/job-queue.js';
import { agentDispatcher } from '../services/agent-dispatch.js';
import { db as sqliteDb } from '../db/sqlite.js';
import { worktreeExecutor, DuplicateRunError, NoChildrenError } from '../services/worktree-executor.js';
import { utc } from '../utils/timestamps.js';

/** Fix SQLite timestamps on job objects so the client parses them as UTC */
function formatJobTimestamps<T extends Record<string, any>>(job: T): T {
  return {
    ...job,
    created_at: utc(job.created_at),
    started_at: utc(job.started_at),
    completed_at: utc(job.completed_at),
    updated_at: utc(job.updated_at),
  };
}

export class AlreadyDecomposedError extends Error {
  constructor(public beadId: string, public decomposedAt: string) {
    super(`Bead ${beadId} was already decomposed at ${decomposedAt}`);
    this.name = 'AlreadyDecomposedError';
  }
}
import { beadOps, agentJobOps, projectMemoryOps } from '../db/sqlite.js';
import { scoreSpecificBead } from '../services/burn-scorer.js';
import { transitionStatus, deleteBead } from '../services/bead-lifecycle.js';
import { analyzeJobFailure, countRetryDepth, shouldOfferAnalysis, type RecoveryAction } from '../services/failure-analysis.js';
import { type SuggestedSubtask } from '../services/task-analyzer.js';
import { backlogHealth, type BacklogHealthReport } from '../services/backlog-health.js';
import { projectEvents } from '../services/project-events.js';
import { logActivity } from '../services/activity-logger.js';
import { checkConflicts } from '../services/conflict-detector.js';
import { startBackgroundTask, getTaskStatus } from '../services/background-tasks.js';

const router = Router();

/**
 * Create child beads from subtask suggestions and wire up dependencies.
 * Returns the created child bead info.
 */
export function decomposeBeadIntoSubtasks(
  projectId: string,
  parentBeadId: string,
  subtasks: SuggestedSubtask[]
): { id: string; subject: string; blockedBy: string[] }[] {
  const parentBead = beadOps.findById.get(parentBeadId) as any;
  if (!parentBead || parentBead.project_id !== projectId) {
    throw new Error('Parent bead not found');
  }

  // Guard: prevent double decomposition
  if (parentBead.decomposed_at) {
    throw new AlreadyDecomposedError(parentBeadId, parentBead.decomposed_at);
  }

  const createdBeadIds: string[] = [];
  const childBeads: { id: string; subject: string; blockedBy: string[] }[] = [];

  for (let i = 0; i < subtasks.length; i++) {
    const sub = subtasks[i];
    if (!sub.title) continue;

    const beadId = uuidv4();
    createdBeadIds.push(beadId);

    // Resolve dependsOn indices to actual bead IDs
    const blockedByIds: string[] = [];
    if (Array.isArray(sub.dependsOn)) {
      for (const depIdx of sub.dependsOn) {
        if (typeof depIdx === 'number' && depIdx >= 0 && depIdx < i) {
          blockedByIds.push(createdBeadIds[depIdx]);
        }
      }
    }

    beadOps.create.run(
      beadId,
      projectId,
      sub.title,
      sub.description || '',
      blockedByIds.length > 0 ? 'blocked' : 'pending',
      parentBead.priority || 2,
      null, // owner
      blockedByIds.length > 0 ? JSON.stringify(blockedByIds) : null,
      null, // blocks
      null, // github_issue_number
      null, // github_issue_url
      null, // local_bead_id
      null, // local_synced_at
      parentBeadId,
      'task',
      sub.preInstructions || null
    );

