  sqliteDb.prepare("UPDATE beads SET decomposed_at = datetime('now') WHERE id = ?").run(parentBeadId);

  return childBeads;
}

/**
 * Walk the retry_of chain for a job and count how many prior jobs used
 * escalated budgets (max_tokens > 500000). This determines which budget
 * tier the next retry would be.
 */
function countBudgetEscalations(jobId: string): number {
  let count = 0;
  let currentId: string | undefined = jobId;
  const visited = new Set<string>();

  while (currentId && !visited.has(currentId)) {
    visited.add(currentId);
    const job = agentJobOps.findById.get(currentId) as AgentJob | undefined;
    if (!job) break;

    if (job.max_tokens && job.max_tokens > 500_000) {
      count++;
    }
    currentId = job.retry_of || undefined;
  }

  return count;
}

