207	 * POST /api/jobs - Create a new job
208	 */
209	router.post('/', validate({ body: DispatchJobBody }), (req, res) => {
210	  try {
211	    const { projectId, beadId, prompt, workerType, priority, force } = req.body as DispatchJobBody;
212	
213	    const project = requirePermission(projectId, (req.user as any).id, 'dispatch_agents');
214	    if (!project) {
215	      return res.status(403).json({ error: 'dispatch_agents permission required' });
216	    }
217	
218	    // Guard: repo-less projects cannot dispatch agents
219	    if (!project.github_repo) {
220	      return res.status(400).json({ error: 'This project has no repository. Agent dispatch requires a linked repository.' });
221	    }
222	
223	    // Guard: thoughts cannot be dispatched
224	    if (beadId) {
225	      const beadForTypeCheck = beadOps.findById.get(beadId) as any;
226	      if (beadForTypeCheck?.bead_type === 'thought') {
227	        return res.status(400).json({ error: 'Thoughts cannot be dispatched as agent jobs' });
228	      }
229	    }
230	
231	    // Guard: warn on unanalyzed beads (can be overridden with force flag)
232	    if (beadId && !force) {
233	      const bead = beadOps.findById.get(beadId) as any;
234	      if (bead && !bead.pre_instructions) {
235	        return res.status(400).json({
236	          error: 'Task has not been analyzed. Analyze first for better results, or dispatch anyway.',
237	          code: 'UNANALYZED_BEAD',
238	        });
239	      }
240	    }
241	
242	    // Smart routing: if bead has children, delegate to worktree executor
243	    if (beadId) {
244	      const children = beadOps.findChildrenByParent.all(beadId) as any[];
245	      if (children && children.length > 0) {
246	        try {
247	          const result = worktreeExecutor.startRun(projectId, beadId, workerType, priority);
248	          projectEvents.emit('change', { type: 'jobs:changed', projectId });
249	          return res.status(201).json({ ...result, dispatchMode: 'worktree' });
250	        } catch (error) {
251	          if (error instanceof DuplicateRunError) {
252	            return res.status(409).json({ error: error.message, code: 'DUPLICATE_RUN' });
253	          }
254	          if (error instanceof NoChildrenError) {
255	            return res.status(400).json({ error: error.message, code: 'NO_CHILDREN' });
256	          }
257	          throw error;
258	        }
259	      }
260	    }
261	
262	    // Auto-create a bead when dispatching without one (freeform prompt).
263	    // Every job must trace back to a task — no orphaned jobs.
264	    let effectiveBeadId = beadId;
265	    let jobPrompt = prompt;
266	
267	    if (!effectiveBeadId) {
268	      const autoBeadId = uuidv4();
269	      beadOps.create.run(
270	        autoBeadId,
271	        projectId,
272	        prompt.length > 120 ? prompt.slice(0, 120) + '...' : prompt, // subject
273	        prompt,       // description (full prompt)
274	        'in_progress', // status — agent is about to run
275	        priority ?? 2,
276	        null,         // owner
277	        '[]',         // blocked_by
278	        '[]',         // blocks
279	        null,         // github_issue_number
280	        null,         // github_issue_url
281	        null,         // local_bead_id
282	        null,         // local_synced_at
283	        null,         // parent_bead_id
284	        'task',       // bead_type
285	        null          // pre_instructions
286	      );
287	      effectiveBeadId = autoBeadId;
288	      jobPrompt = prompt.length > 120 ? prompt.slice(0, 120) + '...' : prompt;
289	      projectEvents.emit('change', { type: 'beads:changed', projectId });
290	    } else {
291	      // Use bead subject as stored prompt for clean job titles.
292	      const bead = beadOps.findById.get(effectiveBeadId) as any;
293	      if (bead?.subject) {
294	        jobPrompt = bead.subject;
295	      }
296	    }
297	
298	    const input: CreateJobInput = {
299	      projectId,
300	      beadId: effectiveBeadId,
301	      prompt: jobPrompt,
302	      workerType,
303	      priority,
304	      dispatchedBy: (req.user as any).id,
305	    };
306	
307	    const job = jobQueue.createJob(input);
308	    projectEvents.emit('change', { type: 'jobs:changed', projectId });
309	    res.status(201).json({ ...job, dispatchMode: 'single' });
310	  } catch (error) {
311	    if (error instanceof DuplicateJobError) {
312	      return res.status(409).json({
313	        error: error.message,
314	        code: 'DUPLICATE_JOB',
315	        existingJobId: error.existingJobId,
316	      });
317	    }
318	    console.error('Error creating job:', error);
319	    res.status(500).json({ error: 'Failed to create job' });
320	  }
321	});
