324	 * GET /api/jobs - List jobs with optional filters (supports cursor-based pagination)
325	 */
326	router.get('/', validate({ query: ListJobsQuery }), (req, res) => {
327	  try {
328	    const { projectId, status, beadId, limit: validatedLimit, cursor } = req.query as unknown as ListJobsQuery;
329	    const userId = (req.user as any).id;
330	
331	    let jobs: AgentJob[];
332	    let paginated = false;
333	
334	    if (beadId) {
335	      // Use existing agentJobOps to find by bead_id
336	      jobs = (agentJobOps.findByBeadId.all(beadId) as AgentJob[]) || [];
337	      // Verify user has access to the job's project
338	      const accessibleIds = getAccessibleProjectIds(userId);
339	      jobs = jobs.filter(job => accessibleIds.includes(job.project_id));
340	    } else if (projectId) {
341	      const project = requireProjectAccess(projectId, userId);
342	      if (!project) {
343	        return res.status(404).json({ error: 'Project not found' });
344	      }
345	
346	      // Use cursor-based pagination when limit is specified
347	      const limit = validatedLimit;
348	      const fetchLimit = limit + 1;
349	
350	      if (cursor) {
351	        const separatorIdx = cursor.indexOf('|');
352	        if (separatorIdx === -1) {
353	          return res.status(400).json({ error: 'Invalid cursor format' });
354	        }
355	        const cursorDate = cursor.slice(0, separatorIdx);
356	        const cursorId = cursor.slice(separatorIdx + 1);
357	        jobs = agentJobOps.findByProjectIdAfterCursor.all(projectId, cursorDate, cursorDate, cursorId, fetchLimit) as AgentJob[];
358	      } else {
359	        jobs = agentJobOps.findByProjectIdPaginated.all(projectId, fetchLimit) as AgentJob[];
360	      }
361	
362	      const hasMore = jobs.length > limit;
363	      if (hasMore) jobs = jobs.slice(0, limit);
364	
365	      // Add shouldAnalyze to paginated jobs
366	      const jobsWithAnalysis = jobs.map((job: any) => {
367	        let failureAnalysis;
368	        if (job.status === 'failed') {
369	          const result = job.result ? JSON.parse(job.result) : undefined;
370	          failureAnalysis = result?.failureArtifacts?.failureAnalysis || analyzeJobFailure(job.error || '', job.output_log || '');
371	        }
372	
373	        const shouldAnalyze = (
374	          job.status === 'failed' && 
375	          ['agent_timeout', 'agent_token_limit', 'compile_error', 'test_failure', 'unknown'].includes(
376	            failureAnalysis?.category || ''
377	          )
378	        ) || (
379	          job.bead_id && 
380	          !(beadOps.findById.get(job.bead_id) as any)?.pre_instructions
381	        );
382	
383	        return { ...formatJobTimestamps(job), shouldAnalyze };
384	      });
385	
386	      const nextCursor = hasMore && jobsWithAnalysis.length > 0
387	        ? `${jobsWithAnalysis[jobsWithAnalysis.length - 1].created_at}|${jobsWithAnalysis[jobsWithAnalysis.length - 1].id}`
388	        : null;
389	
390	      return res.json({ data: jobsWithAnalysis, nextCursor, hasMore });
391	    } else if (status) {
392	      jobs = jobQueue.getJobsByStatus(status as any);
393	      const accessibleIds = getAccessibleProjectIds(userId);
394	      jobs = jobs.filter(job => accessibleIds.includes(job.project_id));
395	    } else {
396	      // Get all jobs for user's accessible projects
397	      const accessibleIds = getAccessibleProjectIds(userId);
398	      jobs = accessibleIds.flatMap(pid => jobQueue.getJobsByProject(pid));
399	    }
400	
401	    // Sort by created_at descending (non-paginated paths)
402	    jobs.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
403	
404	    // Add shouldAnalyze to non-paginated jobs
405	    const jobsWithAnalysis = jobs.map((job: any) => {
406	      let failureAnalysis;
407	      if (job.status === 'failed') {
408	        const result = job.result ? JSON.parse(job.result) : undefined;
409	        failureAnalysis = result?.failureArtifacts?.failureAnalysis || analyzeJobFailure(job.error || '', job.output_log || '');
410	      }
411	
412	      const shouldAnalyze = (
413	        job.status === 'failed' && 
414	        ['agent_timeout', 'agent_token_limit', 'compile_error', 'test_failure', 'unknown'].includes(
415	          failureAnalysis?.category || ''
416	        )
417	      ) || (
418	        job.bead_id && 
419	        !(beadOps.findById.get(job.bead_id) as any)?.pre_instructions
420	      );
421	
422	      return { ...formatJobTimestamps(job), shouldAnalyze };
423	    });
424	
425	    res.json({ data: jobsWithAnalysis, nextCursor: null, hasMore: false });
426	  } catch (error) {
427	    console.error('Error listing jobs:', error);
428	    res.status(500).json({ error: 'Failed to list jobs' });
429	  }
430	});
