/**
 * POST /api/jobs - Create a new job
 */
router.post('/', validate({ body: DispatchJobBody }), (req, res) => {
  try {
    const { projectId, beadId, prompt, workerType, priority, force } = req.body as DispatchJobBody;

    const project = requirePermission(projectId, (req.user as any).id, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    // Guard: repo-less projects cannot dispatch agents
    if (!project.github_repo) {
      return res.status(400).json({ error: 'This project has no repository. Agent dispatch requires a linked repository.' });
    }

    // Guard: thoughts cannot be dispatched
    if (beadId) {
      const beadForTypeCheck = beadOps.findById.get(beadId) as any;
      if (beadForTypeCheck?.bead_type === 'thought') {
        return res.status(400).json({ error: 'Thoughts cannot be dispatched as agent jobs' });
      }
    }

    // Guard: warn on unanalyzed beads (can be overridden with force flag)
    if (beadId && !force) {
      const bead = beadOps.findById.get(beadId) as any;
      if (bead && !bead.pre_instructions) {
        return res.status(400).json({
          error: 'Task has not been analyzed. Analyze first for better results, or dispatch anyway.',
          code: 'UNANALYZED_BEAD',
        });
      }
    }

    // Smart routing: if bead has children, delegate to worktree executor
    if (beadId) {
      const children = beadOps.findChildrenByParent.all(beadId) as any[];
      if (children && children.length > 0) {
        try {
          const result = worktreeExecutor.startRun(projectId, beadId, workerType, priority);
          projectEvents.emit('change', { type: 'jobs:changed', projectId });
          return res.status(201).json({ ...result, dispatchMode: 'worktree' });
        } catch (error) {
          if (error instanceof DuplicateRunError) {
            return res.status(409).json({ error: error.message, code: 'DUPLICATE_RUN' });
          }
          if (error instanceof NoChildrenError) {
            return res.status(400).json({ error: error.message, code: 'NO_CHILDREN' });
          }
          throw error;
        }
      }
    }

    // Auto-create a bead when dispatching without one (freeform prompt).
    // Every job must trace back to a task — no orphaned jobs.
    let effectiveBeadId = beadId;
    let jobPrompt = prompt;

    if (!effectiveBeadId) {
      const autoBeadId = uuidv4();
      beadOps.create.run(
        autoBeadId,
        projectId,
        prompt.length > 120 ? prompt.slice(0, 120) + '...' : prompt, // subject
        prompt,       // description (full prompt)
        'in_progress', // status — agent is about to run
        priority ?? 2,
        null,         // owner
        '[]',         // blocked_by
        '[]',         // blocks
        null,         // github_issue_number
        null,         // github_issue_url
        null,         // local_bead_id
        null,         // local_synced_at
        null,         // parent_bead_id
        'task',       // bead_type
        null          // pre_instructions
      );
      effectiveBeadId = autoBeadId;
      jobPrompt = prompt.length > 120 ? prompt.slice(0, 120) + '...' : prompt;
      projectEvents.emit('change', { type: 'beads:changed', projectId });
    } else {
      // Use bead subject as stored prompt for clean job titles.
      const bead = beadOps.findById.get(effectiveBeadId) as any;
      if (bead?.subject) {
        jobPrompt = bead.subject;
      }
    }

    const input: CreateJobInput = {
      projectId,
      beadId: effectiveBeadId,
      prompt: jobPrompt,
      workerType,
      priority,
      dispatchedBy: (req.user as any).id,
    };

    const job = jobQueue.createJob(input);
    projectEvents.emit('change', { type: 'jobs:changed', projectId });
    res.status(201).json({ ...job, dispatchMode: 'single' });
  } catch (error) {
    if (error instanceof DuplicateJobError) {
      return res.status(409).json({
        error: error.message,
        code: 'DUPLICATE_JOB',
        existingJobId: error.existingJobId,
      });
    }
    console.error('Error creating job:', error);
    res.status(500).json({ error: 'Failed to create job' });
  }
});

/**
 * GET /api/jobs - List jobs with optional filters (supports cursor-based pagination)
 */
router.get('/', validate({ query: ListJobsQuery }), (req, res) => {
  try {
    const { projectId, status, beadId, limit: validatedLimit, cursor } = req.query as unknown as ListJobsQuery;
    const userId = (req.user as any).id;

    let jobs: AgentJob[];
    let paginated = false;

    if (beadId) {
      // Use existing agentJobOps to find by bead_id
      jobs = (agentJobOps.findByBeadId.all(beadId) as AgentJob[]) || [];
      // Verify user has access to the job's project
      const accessibleIds = getAccessibleProjectIds(userId);
      jobs = jobs.filter(job => accessibleIds.includes(job.project_id));
    } else if (projectId) {
      const project = requireProjectAccess(projectId, userId);
      if (!project) {
        return res.status(404).json({ error: 'Project not found' });
      }

      // Use cursor-based pagination when limit is specified
      const limit = validatedLimit;
      const fetchLimit = limit + 1;

      if (cursor) {
        const separatorIdx = cursor.indexOf('|');
        if (separatorIdx === -1) {
          return res.status(400).json({ error: 'Invalid cursor format' });
        }
        const cursorDate = cursor.slice(0, separatorIdx);
        const cursorId = cursor.slice(separatorIdx + 1);
        jobs = agentJobOps.findByProjectIdAfterCursor.all(projectId, cursorDate, cursorDate, cursorId, fetchLimit) as AgentJob[];
      } else {
        jobs = agentJobOps.findByProjectIdPaginated.all(projectId, fetchLimit) as AgentJob[];
      }

      const hasMore = jobs.length > limit;
      if (hasMore) jobs = jobs.slice(0, limit);

      // Add shouldAnalyze to paginated jobs
      const jobsWithAnalysis = jobs.map((job: any) => {
        let failureAnalysis;
        if (job.status === 'failed') {
          const result = job.result ? JSON.parse(job.result) : undefined;
          failureAnalysis = result?.failureArtifacts?.failureAnalysis || analyzeJobFailure(job.error || '', job.output_log || '');
        }

        const shouldAnalyze = (
          job.status === 'failed' && 
          ['agent_timeout', 'agent_token_limit', 'compile_error', 'test_failure', 'unknown'].includes(
            failureAnalysis?.category || ''
          )
        ) || (
          job.bead_id && 
          !(beadOps.findById.get(job.bead_id) as any)?.pre_instructions
        );

        return { ...formatJobTimestamps(job), shouldAnalyze };
      });

      const nextCursor = hasMore && jobsWithAnalysis.length > 0
        ? `${jobsWithAnalysis[jobsWithAnalysis.length - 1].created_at}|${jobsWithAnalysis[jobsWithAnalysis.length - 1].id}`
        : null;

      return res.json({ data: jobsWithAnalysis, nextCursor, hasMore });
    } else if (status) {
      jobs = jobQueue.getJobsByStatus(status as any);
      const accessibleIds = getAccessibleProjectIds(userId);
      jobs = jobs.filter(job => accessibleIds.includes(job.project_id));
    } else {
      // Get all jobs for user's accessible projects
      const accessibleIds = getAccessibleProjectIds(userId);
      jobs = accessibleIds.flatMap(pid => jobQueue.getJobsByProject(pid));
    }

    // Sort by created_at descending (non-paginated paths)
    jobs.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

    // Add shouldAnalyze to non-paginated jobs
    const jobsWithAnalysis = jobs.map((job: any) => {
      let failureAnalysis;
      if (job.status === 'failed') {
        const result = job.result ? JSON.parse(job.result) : undefined;
        failureAnalysis = result?.failureArtifacts?.failureAnalysis || analyzeJobFailure(job.error || '', job.output_log || '');
      }

      const shouldAnalyze = (
        job.status === 'failed' && 
        ['agent_timeout', 'agent_token_limit', 'compile_error', 'test_failure', 'unknown'].includes(
          failureAnalysis?.category || ''
        )
      ) || (
        job.bead_id && 
        !(beadOps.findById.get(job.bead_id) as any)?.pre_instructions
      );

      return { ...formatJobTimestamps(job), shouldAnalyze };
    });

    res.json({ data: jobsWithAnalysis, nextCursor: null, hasMore: false });
  } catch (error) {
    console.error('Error listing jobs:', error);
    res.status(500).json({ error: 'Failed to list jobs' });
  }
});

/**
 * POST /api/jobs/analyze - Queue an analysis job to run in an E2B sandbox.
 * Returns immediately with a jobId; the dispatcher picks up the job and
 * runs task analysis in a sandbox with real file access.
 */
router.post('/analyze', validate({ body: AnalyzeJobBody }), (req, res) => {
  try {
    const { projectId, prompt, beadId } = req.body as AnalyzeJobBody;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'manage_tasks');
    if (!project) {
      return res.status(403).json({ error: 'manage_tasks permission required' });
    }
    if (!project.github_repo) {
      return res.status(400).json({ error: 'Project has no GitHub repository connected' });
    }

    // Guard: thoughts cannot be analyzed
    if (beadId) {
      const bead = beadOps.findById.get(beadId) as any;
      if (bead?.bead_type === 'thought') {
        return res.status(400).json({ error: 'Thoughts cannot be analyzed' });
      }
    }

    // When analyzing a bead, always use subject + description as the prompt
    // so the analyzer sees the task intent, not stale preInstructions
    let analyzerPrompt = prompt;
    if (beadId) {
      const bead = beadOps.findById.get(beadId) as any;
      if (bead && bead.project_id === projectId) {
        analyzerPrompt = bead.description
          ? `${bead.subject}\n\n${bead.description}`
          : bead.subject;
      }
    }

    // Queue analysis job — dispatcher will pick it up and run in E2B sandbox
    const analysisJob = jobQueue.createJob({
      projectId,
      beadId: beadId || undefined,
      prompt: analyzerPrompt,
      jobType: 'analysis',
      dispatchedBy: userId,
      skipDuplicateCheck: true, // Allow multiple analysis runs per bead
    });
    projectEvents.emit('change', { type: 'jobs:changed', projectId });

    res.json({ jobId: analysisJob.id, status: 'queued' });
  } catch (error) {
    console.error('Error queuing analysis job:', error);
    const message = error instanceof Error ? error.message : 'Failed to queue analysis';

    if (error instanceof Error && (
      error.message.includes('not found. Check the name') ||
      error.message.includes('No access to') ||
      error.message.includes('No GitHub credentials') ||
      error.message.includes('Connect GitHub to allow DevDash') ||
      error.message.includes('Install the Dev-Dash GitHub App')
    )) {
      return res.status(403).json({
        error: message,
        code: 'GITHUB_REPO_NOT_ACCESSIBLE',
      });
    }

    res.status(500).json({ error: message });
  }
});

/**
 * POST /api/jobs/audit - DEPRECATED: delegates to backlog-health for non-sandbox audits
 */
router.post('/audit', validate({ body: AuditJobBody }), (req, res) => {
  try {
    const { projectId } = req.body as AuditJobBody;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'manage_tasks');
    if (!project) {
      return res.status(403).json({ error: 'manage_tasks permission required' });
    }

    // Prevent duplicate audit jobs for the same project
    const projectJobs = jobQueue.getJobsByProject(projectId);
    const activeAudit = projectJobs.find(
      (j) => j.job_type === 'audit' && (j.status === 'queued' || j.status === 'running')
    );
    if (activeAudit) {
      return res.status(409).json({
        error: 'An audit is already running for this project',
        code: 'DUPLICATE_JOB',
        existingJobId: activeAudit.id,
      });
    }

    const auditJob = jobQueue.createJob({
      projectId,
      prompt: 'Strategic backlog audit',
      jobType: 'audit',
      dispatchedBy: userId,
      skipDuplicateCheck: true,
    });
    projectEvents.emit('change', { type: 'jobs:changed', projectId });

    res.json({ jobId: auditJob.id, status: 'queued' });
  } catch (error) {
    console.error('Error queuing audit job:', error);
    const message = error instanceof Error ? error.message : 'Failed to queue audit';
    res.status(500).json({ error: message });
  }
});

