 * POST /api/jobs/decompose - Create sub-beads from task analysis
 */
router.post('/decompose', validate({ body: DecomposeBody }), (req, res) => {
  try {
    const { projectId, parentBeadId, subtasks, force } = req.body as DecomposeBody;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'manage_tasks');
    if (!project) {
      return res.status(403).json({ error: 'manage_tasks permission required' });
    }

    // Force re-decomposition: delete existing children and clear decomposed_at
    if (force) {
      const parentBead = beadOps.findById.get(parentBeadId) as any;
      if (parentBead && parentBead.decomposed_at) {
        const existingChildren = beadOps.findChildrenByParent.all(parentBeadId) as any[];
        for (const child of existingChildren) {
          deleteBead(child.id, { projectId, userId, cascade: true });
        }
        sqliteDb.prepare("UPDATE beads SET decomposed_at = NULL WHERE id = ?").run(parentBeadId);
      }
    }

    const childBeads = decomposeBeadIntoSubtasks(projectId, parentBeadId, subtasks as SuggestedSubtask[]);

    res.status(201).json({
      parentBeadId,
      parentStatus: 'blocked',
      childBeads,
    });
  } catch (error) {
    if (error instanceof AlreadyDecomposedError) {
      return res.status(409).json({
        error: error.message,
        code: 'ALREADY_DECOMPOSED',
        decomposedAt: error.decomposedAt,
      });
    }
    console.error('Error decomposing task:', error);
    const message = error instanceof Error ? error.message : 'Failed to decompose task';
    res.status(500).json({ error: message });
  }
});

