/**
 * GET /api/jobs/:id - Get job details
 */
router.get('/:id', (req, res) => {
  try {
    let job = jobQueue.getJob(req.params.id);

    // Prefix resolution: if not found and ID is short, try prefix match
    if (!job && req.params.id.length < 36) {
      const matches = agentJobOps.findByIdPrefix.all(req.params.id + '%') as AgentJob[];
      if (matches.length === 1) {
        job = matches[0];
      } else if (matches.length > 1) {
        return res.status(400).json({
          error: `Ambiguous job ID prefix '${req.params.id}' matches ${matches.length} jobs`,
          matches: matches.map(m => ({ id: m.id, status: m.status, created_at: m.created_at })),
        });
      }
    }

    if (!job) {
      return res.status(404).json({ error: 'Job not found' });
    }

    const project = requireProjectAccess(job.project_id, (req.user as any).id);
    if (!project) {
      return res.status(404).json({ error: 'Job not found' });
    }

    // Parse result JSON if present
    const result = job.result ? JSON.parse(job.result) : undefined;

    // Compute budget escalations and retry depth for recovery action generation
    const escalations = job.status === 'failed' ? countBudgetEscalations(job.id) : 0;
    const { depth: retryDepth } = job.status === 'failed' ? countRetryDepth(job.id) : { depth: 0 };

    // Prefer stored failure analysis from postflight pipeline; fall back to lazy computation for old jobs
    // Always recompute recovery actions (they depend on escalation count and retry depth which change across retries)
    let failureAnalysis;
    if (job.status === 'failed') {
      const stored = result?.failureArtifacts?.failureAnalysis;
      const computed = analyzeJobFailure(job.error || '', job.output_log || '', result, escalations, retryDepth);
      failureAnalysis = stored
        ? { ...stored, recoveryActions: computed.recoveryActions }
        : computed;
    }

    // Determine if job should be analyzed
    const shouldAnalyze = (
      job.status === 'failed' && 
      ['agent_timeout', 'agent_token_limit', 'compile_error', 'test_failure', 'unknown'].includes(
        failureAnalysis?.category || ''
      )
    ) || (
      job.bead_id && 
      !(beadOps.findById.get(job.bead_id) as any)?.pre_instructions
    );

    res.json({ ...formatJobTimestamps(job), result, failureAnalysis, shouldAnalyze });
  } catch (error) {
    console.error('Error getting job:', error);
    res.status(500).json({ error: 'Failed to get job' });
  }
});

/**
 * POST /api/jobs/:id/cancel - Cancel a job (kills sandbox if running)
 */
router.post('/:id/cancel', async (req, res) => {
  try {
    const job = jobQueue.getJob(req.params.id);

    if (!job) {
      return res.status(404).json({ error: 'Job not found' });
    }

    const project = requirePermission(job.project_id, (req.user as any).id, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    if (job.status !== 'queued' && job.status !== 'running') {
      return res.status(400).json({ error: 'Job cannot be cancelled' });
    }

    // Use dispatcher to cancel — this kills the sandbox and reverts bead status
    const cancelled = await agentDispatcher.cancelJob(req.params.id);
    if (!cancelled) {
      return res.status(500).json({ error: 'Failed to cancel job' });
    }

    const cancelledJob = jobQueue.getJob(req.params.id);
    projectEvents.emit('change', { type: 'jobs:changed', projectId: job.project_id });
    res.json(cancelledJob ? formatJobTimestamps(cancelledJob) : cancelledJob);
  } catch (error) {
    console.error('Error cancelling job:', error);
    res.status(500).json({ error: 'Failed to cancel job' });
  }
});

/**
 * POST /api/jobs/:id/retry - Retry a failed or cancelled job
 */
router.post('/:id/retry', (req, res) => {
  try {
    const job = jobQueue.getJob(req.params.id);

    if (!job) {
      return res.status(404).json({ error: 'Job not found' });
    }

    const project = requirePermission(job.project_id, (req.user as any).id, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    if (job.status !== 'failed' && job.status !== 'cancelled') {
      return res.status(400).json({ error: 'Only failed or cancelled jobs can be retried' });
    }

    // Accept optional budget overrides from request body
    const { maxTokens, maxTurns } = req.body || {};

    // Create a new job with the same parameters, linking back to the failed job
    const newJob = jobQueue.createJob({
      projectId: job.project_id,
      beadId: job.bead_id,
      prompt: job.prompt,
      workerType: job.worker_type,
      priority: job.priority,
      retryOf: job.id,
      jobType: job.job_type,
      dispatchedBy: (req.user as any).id,
      maxTokens: maxTokens || undefined,
      maxTurns: maxTurns || undefined,
    });

    // Reset bead status so it reflects the retry attempt
    if (job.bead_id) {
      transitionStatus(job.bead_id, 'pending', {
        actorType: 'user',
        projectId: job.project_id,
        userId: (req.user as any).id,
      });
    }

    projectEvents.emit('change', { type: 'jobs:changed', projectId: job.project_id });
    res.status(201).json(newJob);
  } catch (error) {
    if (error instanceof DuplicateJobError) {
      return res.status(409).json({
        error: error.message,
        code: 'DUPLICATE_JOB',
        existingJobId: error.existingJobId,
      });
    }
    console.error('Error retrying job:', error);
    res.status(500).json({ error: 'Failed to retry job' });
  }
});

/**
 * POST /api/jobs/:jobId/analyze-failure - Run deeper analysis on a failed job
 */
router.post('/:jobId/analyze-failure', async (req, res) => {
  try {
    const { jobId } = req.params;
    const job = jobQueue.getJob(jobId);

    if (!job) {
      return res.status(404).json({ error: 'Job not found' });
    }

    const project = requireProjectAccess(job.project_id, (req.user as any).id);
    if (!project) {
      return res.status(404).json({ error: 'Project not found' });
    }

    if (job.status !== 'failed') {
      return res.status(400).json({ error: 'Job must be in failed status' });
    }

    const parsedResult = job.result ? JSON.parse(job.result) : undefined;
    const analysis = parsedResult?.failureArtifacts?.failureAnalysis;
    if (!shouldOfferAnalysis(analysis)) {
      return res.status(400).json({ error: 'This failure type does not support analysis' });
    }

    // For now, return enhanced analysis based on existing data
    // Future: trigger task-analyzer.ts for deeper analysis
    const enhancedAnalysis = {
      ...analysis,
      analyzedAt: new Date().toISOString(),
      recommendation: 'Consider breaking this task into smaller subtasks'
    };

    res.json(enhancedAnalysis);
  } catch (error) {
    console.error('Error analyzing failure:', error);
    res.status(500).json({ error: 'Failed to analyze failure' });
  }
});

/**
 * POST /api/jobs/test-failure - Seed a fake failed job for UI testing (dev only)
 *
 * Body: { projectId, category?, prompt?, beadId?, totalTurns?, totalTokens?,
 *         changedFiles?, hasLoop?, maxTokens? }
 *
 * category: one of 'agent_timeout', 'agent_token_limit', 'compile_error',
 *           'test_failure', 'oom', 'push_auth', 'unknown'
 */
router.post('/test-failure', (req, res) => {
  if (process.env.NODE_ENV === 'production') {
    return res.status(404).json({ error: 'Not found' });
  }
  try {
    const {
      projectId,
      category = 'agent_timeout',
      prompt = 'Test task that will fail',
      beadId,
      totalTurns = 50,
      totalTokens = 499_000,
      changedFiles = [],
      hasLoop = false,
      maxTokens,
    } = req.body;
    const userId = (req.user as any).id;

    if (!projectId) {
      return res.status(400).json({ error: 'projectId is required' });
    }

    // Map category to error string
    const errorMap: Record<string, string> = {
      agent_timeout: 'Agent loop exceeded maximum turns',
      agent_token_limit: 'Agent loop exceeded token limit',
      compile_error: 'Compile check FAILED: 3 TypeScript errors found',
      test_failure: 'Tests failed: 2 of 15 test suites failed',
      oom: 'FATAL ERROR: CALL_AND_RETRY_LAST Allocation failed - JavaScript heap out of memory',
      push_auth: 'remote: Permission to repo denied. Authentication failed for push',
      unknown: 'Agent loop failed unexpectedly',
    };

    const errorMsg = errorMap[category] || errorMap.unknown;

    // Build a realistic output log
    const logLines = [
      `[preflight] Cloning repository...`,
      `[preflight] Pre-flight complete. Starting agent...`,
      ...(hasLoop ? [`[agent] Semantic loop detected — agent stuck in loop`] : []),
      `[agent] Turn ${totalTurns}/${totalTurns}: ${errorMsg}`,
    ];
    const outputLog = logLines.join('\n');

    // Create the job (queued → running → failed)
    const job = jobQueue.createJob({
      projectId,
      beadId: beadId || undefined,
      prompt,
      skipDuplicateCheck: true,
      dispatchedBy: userId,
      maxTokens: maxTokens || undefined,
    });

    // Transition to running, then fail
    jobQueue.startJob(job.id);

    const failureArtifactsData: any = {
      collectedAt: new Date().toISOString(),
      collectorsRan: ['failure-analysis'],
      changedFiles,
      uncommittedDiff: changedFiles.length > 0
        ? `--- a/${changedFiles[0]}\n+++ b/${changedFiles[0]}\n@@ -1,3 +1,5 @@\n+// new code\n import { foo } from './bar';\n`
        : undefined,
    };

    const jobResult = {
      totalTurns,
      totalTokens,
      durationMs: 120_000,
      filesWritten: changedFiles,
      filesRead: hasLoop ? Array.from({ length: 15 }, (_, i) => `src/file${i}.ts`) : ['src/main.ts'],
      failureArtifacts: failureArtifactsData,
    };

    const failedJob = jobQueue.failJob(job.id, errorMsg, outputLog, jobResult);
    projectEvents.emit('change', { type: 'jobs:changed', projectId });

    // Return the job as the GET endpoint would (with failure analysis computed)
    const escalations = countBudgetEscalations(job.id);
    const { depth: testRetryDepth } = countRetryDepth(job.id);
    const fa = analyzeJobFailure(errorMsg, outputLog, jobResult, escalations, testRetryDepth);

    res.status(201).json({
      ...failedJob,
      result: jobResult,
      failureAnalysis: fa,
    });
  } catch (error) {
    console.error('Error creating test failure:', error);
    res.status(500).json({ error: 'Failed to create test failure' });
  }
});

export default router;

