 *   maxAutoSelect: number  — cap for auto-select (default 10)
 *   maxJobs: number        — max total jobs before stopping (default unlimited)
 */
router.post('/:projectId/drain', validate({ body: StartDrainBody }), (req, res) => {
  try {
    const projectId = req.params.projectId as string;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const { beadIds, autoSelect, maxAutoSelect, maxJobs, minAutomability, parentBeadId, strategy } = req.body as StartDrainBody;

    const result = drainManager.start(projectId, userId, {
      beadIds,
      autoSelect,
      maxAutoSelect,
      maxJobs,
      minAutomability,
      parentBeadId,
      strategy: strategy as 'priority' | 'automability' | undefined,
    });

    logActivity({
      projectId,
      actorId: userId,
      actorType: 'user',
      action: 'drain.started',
      targetType: 'drain',
      targetId: result.drainId,
      metadata: { drainId: result.drainId, scopeSize: result.scopeSize, jobsCreated: result.jobsCreated.length },
    });

    res.json({
      success: true,
      active: true,
      ...result,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to start drain';
    console.error('[Drain Route] Start error:', message);
    res.status(500).json({ error: message });
  }
});

