import { Router } from 'express';
import { requireAuth } from '../middleware/auth.js';
import { requirePermission } from '../middleware/project-access.js';
import { validate } from '../middleware/validate.js';
import { StartDrainBody, DrainPreviewQuery, DrainListQuery, UpdateDrainChecklistBody } from '../schemas/index.js';
import { drainManager } from '../services/drain-manager.js';
import { drainOps, agentJobOps, beadOps } from '../db/ops.js';
import { resolveGitHubToken } from '../services/github-app.js';
import { logActivity } from '../services/activity-logger.js';
import { scoreProjectBeads, scoreSpecificBead, scoreAndPersist, scoreBeadWithAI, refreshStaleScores } from '../services/burn-scorer.js';

const router = Router();

router.use(requireAuth);

/**
 * POST /api/projects/:projectId/drain — Start a drain
 *
 * Body options (all optional):
 *   beadIds: string[]      — specific beads to process (+ their children as they unblock)
 *   autoSelect: boolean    — let server pick ready leaf beads
 *   maxAutoSelect: number  — cap for auto-select (default 10)
 *   maxJobs: number        — max total jobs before stopping (default unlimited)
 */
router.post('/:projectId/drain', validate({ body: StartDrainBody }), async (req, res) => {
  try {
    const projectId = req.params.projectId as string;
    const userId = (req.user as any).id;

    const project = await requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const { beadIds, autoSelect, maxAutoSelect, maxJobs, minAutomability, parentBeadId, strategy } = req.body as StartDrainBody;

    const result = await drainManager.start(projectId, userId, {
      beadIds,
      autoSelect,
      maxAutoSelect,
      maxJobs,
      minAutomability,
      parentBeadId,
      strategy: strategy as 'priority' | 'automability' | undefined,
    });

    await logActivity({
      projectId,
      actorId: userId,
      actorType: 'user',
      action: 'drain.started',
      targetType: 'drain',
      targetId: result.drainId,
      metadata: { drainId: result.drainId, scopeSize: result.scopeSize, jobsCreated: result.jobsCreated.length },
    });

    res.json({
      success: true,
      active: true,
      ...result,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to start drain';
    console.error('[Drain Route] Start error:', message);
    res.status(500).json({ error: message });
  }
});

/**
 * GET /api/projects/:projectId/drain — Get drain status
 */
router.get('/:projectId/drain', async (req, res) => {
  try {
    const { projectId } = req.params;
    const userId = (req.user as any).id;

    const project = await requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const status = drainManager.getStatus(projectId);
    res.json(status);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to get drain status';
    res.status(500).json({ error: message });
  }
});

/**
 * DELETE /api/projects/:projectId/drain — Stop a drain
 */
router.delete('/:projectId/drain', async (req, res) => {
  try {
    const { projectId } = req.params;
    const userId = (req.user as any).id;

    const project = await requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const stopped = drainManager.stop(projectId);
    res.json({ success: true, wasDraining: stopped });
