router.patch('/:projectId/drains/:drainId/checklist', validate({ body: UpdateDrainChecklistBody }), (req, res) => {
  try {
    const projectId = req.params.projectId as string;
    const drainId = req.params.drainId as string;
    const userId = (req.user as any).id;

