/**
 * GET /api/projects/:projectId/drains/:drainId/pr-status
 *
 * Fetches live PR status from GitHub for all PRs created by a drain's jobs.
 */
router.get('/:projectId/drains/:drainId/pr-status', async (req, res) => {
  try {
    const { projectId, drainId } = req.params;
    const userId = (req.user as any).id;

    const project = await requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    const drain = await drainOps.findById(drainId) as any;
    if (!drain || drain.projectId !== projectId) {
      return res.status(404).json({ error: 'Drain not found' });
    }

    // Get all jobs for this drain that have PR URLs
    const jobs = await agentJobOps.findByDrainId(drainId) as any[];
    const jobsWithPRs = jobs.filter((j) => {
      if (!j.result) return false;
      try {
        const result = typeof j.result === 'string' ? JSON.parse(j.result) : j.result;
        return !!result.prUrl;
      } catch {
        return false;
      }
    });

    if (jobsWithPRs.length === 0) {
      return res.json({ data: [] });
    }

    // Resolve GitHub token
    const resolved = await resolveGitHubToken((project as any).userId, (project as any).githubRepo);
    if (!resolved) {
      return res.status(400).json({ error: 'No GitHub credentials available' });
    }

    // Fetch PR status for each job
    const prStatuses = await Promise.all(
      jobsWithPRs.map(async (job) => {
        try {
          const result = typeof job.result === 'string' ? JSON.parse(job.result) : job.result;
          const prUrl: string = result.prUrl;

          // Parse owner/repo/number from PR URL
          const match = prUrl.match(/github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/);
          if (!match) return null;

          const [, owner, repo, numberStr] = match;
          const prNumber = parseInt(numberStr, 10);

          // Fetch PR details
          const prResp = await fetch(
            `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
            { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
          );
          if (!prResp.ok) return null;
          const pr: any = await prResp.json();

          // Determine CI status from the head commit
          let ciStatus: 'success' | 'failure' | 'pending' | 'none' = 'none';
          if (pr.head?.sha) {
            const statusResp = await fetch(
              `https://api.github.com/repos/${owner}/${repo}/commits/${pr.head.sha}/status`,
              { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
            );
            if (statusResp.ok) {
              const statusData: any = await statusResp.json();
              ciStatus = statusData.state === 'success' ? 'success'
                : statusData.state === 'failure' ? 'failure'
                : statusData.state === 'pending' ? 'pending'
                : 'none';
            }
          }

          // Determine review status
          let reviewStatus: 'approved' | 'changes_requested' | 'pending' | 'none' = 'none';
          const reviewsResp = await fetch(
            `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}/reviews`,
            { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
          );
          if (reviewsResp.ok) {
            const reviews = await reviewsResp.json();
            if (Array.isArray(reviews) && reviews.length > 0) {
              // Use the latest review per user
              const latest = reviews[reviews.length - 1];
              if (latest.state === 'APPROVED') reviewStatus = 'approved';
              else if (latest.state === 'CHANGES_REQUESTED') reviewStatus = 'changes_requested';
              else reviewStatus = 'pending';
            }
          }

          return {
            jobId: job.id,
            prUrl,
            prNumber,
            state: pr.merged ? 'merged' as const : pr.state as 'open' | 'closed',
            mergeable: pr.mergeable,
            ciStatus,
            reviewStatus,
            title: pr.title,
            mergedAt: pr.merged_at || null,
          };
        } catch (err) {
          console.warn(`[PR Status] Failed to fetch PR status for job ${job.id}:`, err);
          return null;
        }
      })
    );

    res.json({ data: prStatuses.filter(Boolean) });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to fetch PR statuses';
    console.error('[Drain Route] PR status error:', message);
    res.status(500).json({ error: message });
  }
});

/**
 * POST /api/projects/:projectId/pulls/:prNumber/merge
 *
 * Merges a single PR via GitHub API using squash merge.
 */
router.post('/:projectId/pulls/:prNumber/merge', async (req, res) => {
  try {
    const { projectId, prNumber } = req.params;
    const userId = (req.user as any).id;

    const project = requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    if (!(project as any).githubRepo) {
      return res.status(400).json({ error: 'Project has no GitHub repo configured' });
    }

    const resolved = await resolveGitHubToken((project as any).userId, (project as any).githubRepo);
    if (!resolved) {
      return res.status(400).json({ error: 'No GitHub credentials available' });
    }

    const [owner, repo] = (project as any).githubRepo.split('/');

    // Double-check PR is mergeable before merging
    const prResp = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
      { headers: { Authorization: `token ${resolved.token}`, Accept: 'application/vnd.github.v3+json' } }
    );
    if (!prResp.ok) {
      return res.status(404).json({ error: 'PR not found' });
    }
    const pr: any = await prResp.json();
    if (pr.merged) {
      return res.json({ merged: true, alreadyMerged: true });
    }
    if (pr.mergeable === false) {
      return res.status(409).json({ error: 'PR is not mergeable (has conflicts or failing checks)' });
    }

    // Merge with squash
    const mergeResp = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}/merge`,
      {
        method: 'PUT',
        headers: {
          Authorization: `token ${resolved.token}`,
          Accept: 'application/vnd.github.v3+json',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ merge_method: 'squash' }),
      }
    );

    if (!mergeResp.ok) {
      const errData: any = await mergeResp.json().catch(() => ({}));
      return res.status(mergeResp.status).json({
        error: errData.message || `Merge failed with status ${mergeResp.status}`,
      });
    }

    const mergeData: any = await mergeResp.json();
    res.json({ merged: true, sha: mergeData.sha, message: mergeData.message });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to merge PR';
    console.error('[Drain Route] Merge error:', message);
    res.status(500).json({ error: message });
  }
});

