/**
 * GET /api/projects/:projectId/burn/epic/:parentBeadId — Epic burndown view
 *
 * Returns children of a parent bead with burn scores, grouped into phases
 * by dependency ordering. Children without dependencies come first.
 */
router.get('/:projectId/burn/epic/:parentBeadId', async (req, res) => {
  try {
    const { projectId, parentBeadId } = req.params;
    const userId = (req.user as any).id;

    const project = await requirePermission(projectId, userId, 'dispatch_agents');
    if (!project) {
      return res.status(403).json({ error: 'dispatch_agents permission required' });
    }

    // Verify parent bead exists in this project
    const parentBead = await beadOps.findById(parentBeadId) as any;
    if (!parentBead || parentBead.projectId !== projectId) {
      return res.status(404).json({ error: 'Parent bead not found in this project' });
    }

    const children = await beadOps.findChildrenByParent(parentBeadId) as any[];
    const childIds = new Set(children.map((c: any) => c.id));

    // Auto-score unscored children
    const allBeads = await beadOps.findByProjectId(projectId) as any[];
    for (const child of children) {
      if (child.automabilityScore == null && child.preInstructions) {
        try { scoreAndPersist(child, allBeads); } catch { /* non-fatal */ }
      }
    }

    // Re-read children to get updated scores
    const freshChildren = await beadOps.findChildrenByParent(parentBeadId) as any[];

    // Build dependency graph and compute phases (topological layers)
    const phases: any[][] = [];
    const placed = new Set<string>();
    let remaining = [...freshChildren];

    while (remaining.length > 0) {
      const phase: any[] = [];
      const nextRemaining: any[] = [];

      for (const child of remaining) {
        const blockedBy: string[] = child.blockedBy ? JSON.parse(child.blockedBy) : [];
        // Only consider dependencies within this epic's children
        const unresolvedDeps = blockedBy.filter((id: string) => childIds.has(id) && !placed.has(id));
        if (unresolvedDeps.length === 0) {
          phase.push(child);
        } else {
          nextRemaining.push(child);
        }
      }

      if (phase.length === 0) {
        // Cycle detected — dump remaining into final phase
        phases.push(remaining);
        break;
      }

      // Sort phase by automability DESC
      phase.sort((a: any, b: any) => (b.automabilityScore ?? 0) - (a.automabilityScore ?? 0));
      phases.push(phase);
      for (const b of phase) placed.add(b.id);
      remaining = nextRemaining;
    }

    // Stats
    const burnableCount = freshChildren.filter((c: any) => c.status === 'pending' && c.preInstructions).length;
    const completedCount = freshChildren.filter((c: any) => c.status === 'completed').length;
    const avgAutomability = freshChildren.reduce((sum: number, c: any) => sum + (c.automability_score ?? 0), 0) / (freshChildren.length || 1);

    res.json({
      parentBead: { id: parentBead.id, subject: parentBead.subject, status: parentBead.status },
      totalChildren: freshChildren.length,
      burnableCount,
      completedCount,
      avgAutomability: Math.round(avgAutomability),
      phases: phases.map((phase, i) => ({
        phase: i + 1,
        beads: phase.map((b: any) => ({
          id: b.id,
          subject: b.subject,
          status: b.status,
          priority: b.priority,
          hasPreInstructions: !!b.pre_instructions,
          complexityScore: b.complexity_score,
          automabilityScore: b.automability_score,
          automabilityGrade: b.automability_grade,
          blockedBy: b.blocked_by ? JSON.parse(b.blocked_by) : [],
        })),
      })),
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to get epic burn view';
    console.error('[Burn Route] Epic burn error:', message);
    res.status(500).json({ error: message });
  }
});

