import { Router } from 'express';
import { notificationOps } from '../db/ops.js';
import { requireAuth, type AuthUser } from '../middleware/auth.js';
import { utc } from '../utils/timestamps.js';
import { validate } from '../middleware/validate.js';
import { CreateNotificationBody } from '../schemas/index.js';

const router = Router();

// Get all notifications for user
router.get('/', requireAuth, async (req, res) => {
  const user = req.user as AuthUser;
  try {
    const notifications = await notificationOps.findByUserId(user.id);
    const transformed = (notifications as any[]).map(n => ({
      id: n.id,
      userId: n.userId,
      type: n.type,
      title: n.title,
      message: n.message,
      read: Boolean(n.read),
      metadata: n.metadata ? JSON.parse(n.metadata) : null,
      createdAt: utc(n.createdAt),
    }));
    res.json(transformed);
  } catch (error) {
    console.error('Error fetching notifications:', error);
    res.status(500).json({ error: 'Failed to fetch notifications' });
  }
});

// Get unread count
router.get('/unread-count', requireAuth, async (req, res) => {
  const user = req.user as AuthUser;
  try {
    const result = await notificationOps.countUnread(user.id) as { count: number };
    res.json({ count: result.count });
  } catch (error) {
    console.error('Error counting unread notifications:', error);
    res.status(500).json({ error: 'Failed to count unread notifications' });
  }
});

// Mark notification as read
router.patch('/:id/read', requireAuth, async (req, res) => {
  const user = req.user as AuthUser;
  const { id } = req.params;

  try {
    const notification = await notificationOps.findById(id) as any;
    if (!notification) {
      return res.status(404).json({ error: 'Notification not found' });
    }
    if (notification.userId !== user.id) {
      return res.status(403).json({ error: 'Not authorized' });
    }

    await notificationOps.markRead(id);
    res.json({ success: true });
  } catch (error) {
    console.error('Error marking notification as read:', error);
    res.status(500).json({ error: 'Failed to mark notification as read' });
  }
});

// Mark all notifications as read
router.patch('/read-all', requireAuth, async (req, res) => {
  const user = req.user as AuthUser;
  try {
    await notificationOps.markAllRead(user.id);
    res.json({ success: true });
  } catch (error) {
    console.error('Error marking all notifications as read:', error);
    res.status(500).json({ error: 'Failed to mark all notifications as read' });
  }
});

// Create a notification (for internal/testing use)
router.post('/', requireAuth, validate({ body: CreateNotificationBody }), async (req, res) => {
  const user = req.user as AuthUser;
  const { type, title, message, metadata } = req.body as CreateNotificationBody;

  try {
    const id = `notif-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    await notificationOps.create(
      id,
      user.id,
      type,
      title,
      message || null,
      metadata ? JSON.stringify(metadata) : null,
      null, null, null
    );

    const notification = await notificationOps.findById(id) as any;
    res.status(201).json({
      id: notification.id,
      userId: notification.userId,
      type: notification.type,
      title: notification.title,
      message: notification.message,
      read: Boolean(notification.read),
      metadata: notification.metadata ? JSON.parse(notification.metadata) : null,
      createdAt: utc(notification.createdAt),
    });
  } catch (error) {
    console.error('Error creating notification:', error);
    res.status(500).json({ error: 'Failed to create notification' });
  }
});

// Delete a notification
router.delete('/:id', requireAuth, async (req, res) => {
  const user = req.user as AuthUser;
  const { id } = req.params;

  try {
    const notification = await notificationOps.findById(id) as any;
    if (!notification) {
      return res.status(404).json({ error: 'Notification not found' });
    }
    if (notification.userId !== user.id) {
      return res.status(403).json({ error: 'Not authorized' });
    }

    await notificationOps.delete(id);
    res.json({ success: true });
  } catch (error) {
    console.error('Error deleting notification:', error);
    res.status(500).json({ error: 'Failed to delete notification' });
  }
});

export default router;

