      expect(user).toHaveProperty('systemRole');
      // snake_case fields do NOT exist
      expect(user).not.toHaveProperty('display_name');
      expect(user).not.toHaveProperty('avatar_url');
      expect(user).not.toHaveProperty('google_id');
      expect(user).not.toHaveProperty('created_at');
      expect(user).not.toHaveProperty('onboarding_completed');
    });

    it('projectOps.findById returns camelCase fields', async () => {
      const project = await projectOps.findById(projectId);
      expect(project).toBeTruthy();
      expect(project).toHaveProperty('userId');
      expect(project).toHaveProperty('githubRepo');
      expect(project).toHaveProperty('aiProvider');
      expect(project).toHaveProperty('aiModel');
      expect(project).toHaveProperty('mergeStrategy');
      expect(project).toHaveProperty('githubSyncEnabled');
      expect(project).toHaveProperty('autoDispatchReady');
      expect(project).not.toHaveProperty('user_id');
      expect(project).not.toHaveProperty('github_repo');
      expect(project).not.toHaveProperty('ai_provider');
    });

    it('beadOps.findById returns camelCase fields', async () => {
      const bead = await beadOps.findById(beadId);
      expect(bead).toBeTruthy();
      expect(bead).toHaveProperty('projectId');
      expect(bead).toHaveProperty('parentBeadId');
      expect(bead).toHaveProperty('beadType');
      expect(bead).toHaveProperty('preInstructions');
      expect(bead).toHaveProperty('blockedBy');
      expect(bead).toHaveProperty('createdAt');
      expect(bead).not.toHaveProperty('project_id');
      expect(bead).not.toHaveProperty('parent_bead_id');
      expect(bead).not.toHaveProperty('bead_type');
      expect(bead).not.toHaveProperty('pre_instructions');
    });

    it('agentJobOps.findById returns camelCase fields', async () => {
      const job = await agentJobOps.findById(jobId);
      expect(job).toBeTruthy();
      expect(job).toHaveProperty('projectId');
      expect(job).toHaveProperty('beadId');
      expect(job).toHaveProperty('workerType');
      expect(job).toHaveProperty('jobType');
      expect(job).toHaveProperty('createdAt');
      expect(job).not.toHaveProperty('project_id');
      expect(job).not.toHaveProperty('bead_id');
      expect(job).not.toHaveProperty('worker_type');
      expect(job).not.toHaveProperty('job_type');
    });
  });

  // ── Raw SQL queries: verify snake_case field names ──────────────────

  describe('projectOps.findAccessibleByUserId (raw SQL UNION ALL)', () => {
    it('returns rows with snake_case project fields + _role/_permissions', async () => {
      const rows = await projectOps.findAccessibleByUserId(userId, userId) as any;
      const resultRows = rows.rows ?? rows;
      expect(resultRows.length).toBeGreaterThanOrEqual(1);
      const row = resultRows[0];
      // Raw SQL returns snake_case
      expect(row).toHaveProperty('_role');
      // Project fields from SELECT p.* are snake_case
      expect(row).toHaveProperty('id');
      expect(row.user_id !== undefined || row.userId !== undefined).toBe(true);
    });
  });

  describe('beadOps.findOrphanedInProgress (raw SQL subquery)', () => {
    it('returns rows with snake_case bead fields', async () => {
      const rows = await beadOps.findOrphanedInProgress() as any;
      const resultRows = rows.rows ?? rows;
      // Our test bead is in_progress with a queued job, so it should NOT be orphaned
      // But we can still verify the query runs without error
      expect(Array.isArray(resultRows)).toBe(true);
    });
  });

  describe('readinessOutcomeOps (raw SQL aggregation)', () => {
    it('statsByProject returns snake_case fields', async () => {
      const outcomeId = randomUUID();
      await readinessOutcomeOps.insert(outcomeId, projectId, beadId, jobId, 'A', 'low', 'success', null, false);

      const rows = await readinessOutcomeOps.statsByProject(projectId) as any;
      const resultRows = rows.rows ?? rows;
      expect(resultRows.length).toBeGreaterThanOrEqual(1);
      const row = resultRows[0];
      expect(row).toHaveProperty('automability_grade');
      expect(row).toHaveProperty('complexity');
      expect(row).toHaveProperty('total');
      expect(row).toHaveProperty('successes');
      expect(typeof row.total).toBe('number');
      expect(typeof row.successes).toBe('number');
    });

    it('statsByGrade returns snake_case fields', async () => {
      const rows = await readinessOutcomeOps.statsByGrade(projectId) as any;
      const resultRows = rows.rows ?? rows;
      expect(resultRows.length).toBeGreaterThanOrEqual(1);
      const row = resultRows[0];
      expect(row).toHaveProperty('automability_grade');
      expect(row).toHaveProperty('total');
      expect(row).toHaveProperty('successes');
    });
  });

  describe('worktreeRunOps.findActiveByProject (raw SQL subquery)', () => {
    it('executes without error and returns array', async () => {
      const rows = await worktreeRunOps.findActiveByProject(projectId, projectId) as any;
      const resultRows = rows.rows ?? rows;
      expect(Array.isArray(resultRows)).toBe(true);
      // No active worktree runs in test data, so empty is fine
    });
  });

  describe('teamProjectOps.findByUserAndProject (raw SQL JOIN)', () => {
    it('returns access_role field', async () => {
      const result = await teamProjectOps.findByUserAndProject(projectId, userId) as any;
      // Should find the team_projects entry we created
      expect(result).toBeTruthy();
      const row = result.rows?.[0] ?? result;
      expect(row).toHaveProperty('access_role');
      expect(row.access_role).toBe('admin');
    });
  });

  describe('auditLogOps (raw SQL with JOIN)', () => {
    it('findByOrgId returns actor_name and actor_avatar fields', async () => {
      const auditId = randomUUID();
      await auditLogOps.create(auditId, orgId, userId, 'test.action', 'org', orgId, null, '127.0.0.1');

      const rows = await auditLogOps.findByOrgId(orgId, 10) as any;
      const resultRows = rows.rows ?? rows;
      expect(resultRows.length).toBeGreaterThanOrEqual(1);
      const row = resultRows[0];
      // Raw SQL aliases
      expect(row).toHaveProperty('actor_name');
      expect(row).toHaveProperty('actor_avatar');
      // Core fields are snake_case
      expect(row).toHaveProperty('org_id');
      expect(row).toHaveProperty('actor_id');
      expect(row).toHaveProperty('action');
    });
  });

  describe('authEventOps (raw SQL with LEFT JOIN)', () => {
    it('findRecent returns snake_case fields with display_name and avatar_url', async () => {
      const eventId = randomUUID();
      await authEventOps.create(eventId, userId, 'fieldtest@example.com', 'login', 'google', '127.0.0.1', 'test-ua', null);

      const rows = await authEventOps.findRecent(10) as any;
      const resultRows = rows.rows ?? rows;
      expect(resultRows.length).toBeGreaterThanOrEqual(1);
      const row = resultRows[0];
      // Raw SQL fields
      expect(row).toHaveProperty('user_id');
      expect(row).toHaveProperty('event_type');
      expect(row).toHaveProperty('auth_method');
      expect(row).toHaveProperty('ip_address');
      expect(row).toHaveProperty('user_agent');
      expect(row).toHaveProperty('created_at');
      // JOIN fields
      expect(row).toHaveProperty('display_name');
      expect(row).toHaveProperty('avatar_url');
    });

    it('countByType returns event_type and count fields', async () => {
      const rows = await authEventOps.countByType() as any;
      const resultRows = rows.rows ?? rows;
      expect(resultRows.length).toBeGreaterThanOrEqual(1);
      const row = resultRows[0];
      expect(row).toHaveProperty('event_type');
      expect(row).toHaveProperty('count');
      expect(typeof row.count).toBe('number');
    });

    it('countLast7Days returns count as number', async () => {
      const result = await authEventOps.countLast7Days() as any;
      expect(result).toHaveProperty('count');
      expect(typeof result.count).toBe('number');
    });
  });

  // ── Return type assertions ──────────────────────────────────────────

  describe('Return type correctness', () => {
    it('timestamps are Date objects from Drizzle queries', async () => {
      const user = await userOps.findById(userId);
      expect(user!.createdAt).toBeInstanceOf(Date);
      expect(user!.updatedAt).toBeInstanceOf(Date);

      const project = await projectOps.findById(projectId);
      expect(project!.createdAt).toBeInstanceOf(Date);

      const bead = await beadOps.findById(beadId);
      expect(bead!.createdAt).toBeInstanceOf(Date);
      expect(bead!.updatedAt).toBeInstanceOf(Date);
    });

    it('booleans are true/false from Drizzle queries', async () => {
      const user = await userOps.findById(userId);
      expect(typeof user!.onboardingCompleted).toBe('boolean');

      const project = await projectOps.findById(projectId);
      expect(typeof project!.githubSyncEnabled).toBe('boolean');
      expect(typeof project!.autoDispatchReady).toBe('boolean');
    });

    it('counts are numbers', async () => {
      const countAll = await userOps.countAll();
      expect(typeof countAll!.count).toBe('number');

      const countAdmins = await userOps.countAdmins();
      expect(typeof countAdmins!.count).toBe('number');
    });

    it('null fields return null not undefined', async () => {
      const user = await userOps.findById(userId);
      // systemRole should be null (not set), not undefined
      expect(user!.systemRole).toBeNull();

      const bead = await beadOps.findById(beadId);
      expect(bead!.parentBeadId).toBeNull();
    });
  });

  // ── Drizzle JOIN queries: verify field name shape ───────────────────

  describe('Drizzle JOIN queries return expected field names', () => {
    it('projectMemberOps.findByProjectIdWithUsers returns mixed camelCase', async () => {
      await projectMemberOps.add(projectId, userId, 'member', null);
      const members = await projectMemberOps.findByProjectIdWithUsers(projectId);
      expect(members.length).toBeGreaterThanOrEqual(1);
      const m = members[0];
      // Schema-defined fields in select
      expect(m).toHaveProperty('projectId');
      expect(m).toHaveProperty('userId');
      expect(m).toHaveProperty('role');
      expect(m).toHaveProperty('username');
      // These are aliased in the select — check what Drizzle actually returns
      expect(m).toHaveProperty('display_name');
      expect(m).toHaveProperty('avatar_url');
      expect(m).toHaveProperty('email');
    });

    it('orgMemberOps.findByOrgId returns expected shape', async () => {
      const members = await orgMemberOps.findByOrgId(orgId);
      expect(members.length).toBeGreaterThanOrEqual(1);
      const m = members[0];
      expect(m).toHaveProperty('orgId');
      expect(m).toHaveProperty('userId');
      expect(m).toHaveProperty('role');
      expect(m).toHaveProperty('display_name');
      expect(m).toHaveProperty('avatar_url');
      expect(m).toHaveProperty('email');
    });

    it('teamMemberOps.findByTeamId returns expected shape', async () => {
      const members = await teamMemberOps.findByTeamId(teamId);
      expect(members.length).toBeGreaterThanOrEqual(1);
      const m = members[0];
      expect(m).toHaveProperty('teamId');
      expect(m).toHaveProperty('userId');
      expect(m).toHaveProperty('role');
      expect(m).toHaveProperty('display_name');
      expect(m).toHaveProperty('avatar_url');
    });

    it('activityLogOps.findByProjectId returns camelCase', async () => {
      const logId = randomUUID();
      await activityLogOps.create(logId, projectId, userId, 'user', 'test.action', 'bead', beadId, null, null);
      const logs = await activityLogOps.findByProjectId(projectId, 10);
      expect(logs.length).toBeGreaterThanOrEqual(1);
      const log = logs[0];
      expect(log).toHaveProperty('projectId');
      expect(log).toHaveProperty('actorId');
      expect(log).toHaveProperty('actorType');
      expect(log).toHaveProperty('targetType');
      expect(log).toHaveProperty('targetId');
      expect(log).toHaveProperty('createdAt');
      expect(log).not.toHaveProperty('project_id');
    });
  });
});

