/**
 * Edge case and type assertion tests for the Postgres ops layer.
 *
 * Covers: cursor pagination, filtered query combinations, upsert conflict
 * paths, untested ops groups, and return type edge cases.
 *
 * Usage: POSTGRES_URL="postgresql://..." npx vitest run src/db/__tests__/ops-edge.test.ts
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { randomUUID } from 'crypto';

if (!process.env.POSTGRES_URL) {
  throw new Error('POSTGRES_URL env var required');
}

const {
  userOps, projectOps, beadOps, agentJobOps, agentSessionOps,
  credentialOps, settingsOps, notificationOps, drainOps,
  worktreeRunOps, beadSyncStateOps, agentConfigOps, installationOps,
  installationRepoOps, orgOps, orgMemberOps, orgInvitationOps,
  ssoLinkOps, projectMemoryOps, globalMemoryOps, githubSyncOps,
  activityLogOps, beadCommentOps, planOps, planItemOps,
  initializeDatabase,
} = await import('../ops.js');

import { pool } from '../postgres.js';

const userId = randomUUID();
const projectId = randomUUID();

describe('Ops edge cases', () => {
  beforeAll(async () => {
    await pool.query('TRUNCATE TABLE team_projects, team_members, teams, organization_invitations, organization_members, organizations, sso_identity_links, org_audit_log, bead_comments, readiness_outcomes, agent_jobs, beads, activity_log, notifications, settings, project_memory, global_memory, project_members, project_invitations, project_agent_config, bead_sync_state, api_tokens, auth_events, github_installation_repos, github_installations, github_issue_sync, agent_sessions, agents, orchestration_plans, plan_items, drains, worktree_runs, credentials, projects, sessions, users CASCADE');
    await initializeDatabase();
    await userOps.create(userId, 'edgeuser', 'Edge User', null, 'edge@test.com', null, `google-edge-${randomUUID()}`);
    await projectOps.create(projectId, userId, 'Edge Project', '/edge', 'user/edge-repo', null, 'claude', 'claude-sonnet-4-20250514', 'pr', false);
  });

  afterAll(async () => {
    await pool.query('TRUNCATE TABLE team_projects, team_members, teams, organization_invitations, organization_members, organizations, sso_identity_links, org_audit_log, bead_comments, readiness_outcomes, agent_jobs, beads, activity_log, notifications, settings, project_memory, global_memory, project_members, project_invitations, project_agent_config, bead_sync_state, api_tokens, auth_events, github_installation_repos, github_installations, github_issue_sync, agent_sessions, agents, orchestration_plans, plan_items, drains, worktree_runs, credentials, projects, sessions, users CASCADE');
    await pool.end();
  });

  // ── Cursor pagination ──────────────────────────────────────────────

  describe('cursor pagination', () => {
    const beadIds: string[] = [];

    beforeAll(async () => {
      // Create 5 beads with slight time separation
      for (let i = 0; i < 5; i++) {
        const id = randomUUID();
        beadIds.push(id);
        await beadOps.create(id, projectId, `Bead ${i}`, null, 'pending', 2, null, null, null, null, null, null, null, null, 'task', null);
      }
    });

    it('returns first page with limit', async () => {
      const page1 = await beadOps.findByProjectIdPaginated(projectId, 3);
      expect(page1.length).toBe(3);
    });

    it('cursor-based pagination returns subsequent rows', async () => {
      const page1 = await beadOps.findByProjectIdPaginated(projectId, 3);
      expect(page1.length).toBe(3);

      const lastItem = page1[page1.length - 1];
      const cursorDate = lastItem.createdAt instanceof Date
        ? lastItem.createdAt.toISOString()
        : lastItem.createdAt;

      const page2 = await beadOps.findByProjectIdAfterCursor(
        projectId, cursorDate, cursorDate, lastItem.id, 3
      );
      expect(page2.length).toBe(2); // 5 total - 3 first page = 2
    });

    it('cursor on empty result returns empty array', async () => {
      const farFuture = '2099-01-01T00:00:00.000Z';
      const result = await beadOps.findByProjectIdAfterCursor(
        projectId, farFuture, farFuture, 'zzz', 10
      );
      // All beads are before 2099, so cursor should skip all
      // Actually cursor looks for < cursorDate, so far future returns all
      // Let's use a far past date instead
      const farPast = '2000-01-01T00:00:00.000Z';
      const result2 = await beadOps.findByProjectIdAfterCursor(
        projectId, farPast, farPast, '000', 10
      );
      expect(result2.length).toBe(0);
    });

    it('agent jobs cursor pagination works', async () => {
      const jobIds: string[] = [];
      for (let i = 0; i < 4; i++) {
        const id = randomUUID();
        jobIds.push(id);
        await agentJobOps.create(id, projectId, null, `Job ${i}`, 'queued', 'e2b', 2, null, null, null, null, null, null, 'execution');
      }

      const page1 = await agentJobOps.findByProjectIdPaginated(projectId, 2);
      expect(page1.length).toBe(2);

      const last = page1[page1.length - 1];
      const cursorDate = last.createdAt instanceof Date ? last.createdAt.toISOString() : last.createdAt;
      const page2 = await agentJobOps.findByProjectIdAfterCursor(
        projectId, cursorDate, cursorDate, last.id, 10
      );
      expect(page2.length).toBe(2);
    });

    it('activity log cursor pagination works', async () => {
      for (let i = 0; i < 3; i++) {
        await activityLogOps.create(randomUUID(), projectId, userId, 'user', `action.${i}`, null, null, null, null);
      }

      const page1 = await activityLogOps.findByProjectId(projectId, 2);
      expect(page1.length).toBe(2);

      const last = page1[page1.length - 1];
      const cursorDate = last.createdAt instanceof Date ? last.createdAt!.toISOString() : last.createdAt;
      const page2 = await activityLogOps.findByProjectIdAfterCursor(
        projectId, cursorDate!, cursorDate!, last.id, 10
      );
      expect(page2.length).toBe(1);
    });
  });

  // ── Filtered queries ───────────────────────────────────────────────

  describe('bead filtered queries', () => {
    let filteredBeadId: string;

    beforeAll(async () => {
      filteredBeadId = randomUUID();
      await beadOps.create(filteredBeadId, projectId, 'Filterable Bead', 'searchable description', 'ready', 1, null, null, null, null, null, null, null, null, 'bug', null);
    });

    it('filters by status only', async () => {
      const results = await beadOps.findByProjectIdFiltered(
        projectId, 'ready', 'ready', null, null, null, null, null, null, null, null, null, 50
      );
      expect(results.length).toBeGreaterThanOrEqual(1);
      expect(results.every(b => b.status === 'ready')).toBe(true);
    });

    it('filters by beadType only', async () => {
      const results = await beadOps.findByProjectIdFiltered(
        projectId, null, null, 'bug', 'bug', null, null, null, null, null, null, null, 50
      );
      expect(results.length).toBeGreaterThanOrEqual(1);
      expect(results.every(b => b.beadType === 'bug')).toBe(true);
    });

    it('filters by priority only', async () => {
      const results = await beadOps.findByProjectIdFiltered(
        projectId, null, null, null, null, 1, 1, null, null, null, null, null, 50
      );
      expect(results.length).toBeGreaterThanOrEqual(1);
      expect(results.every(b => b.priority === 1)).toBe(true);
    });

    it('filters by search term in subject', async () => {
      const results = await beadOps.findByProjectIdFiltered(
        projectId, null, null, null, null, null, null, 'Filterable', 'Filterable', 'Filterable', null, null, 50
      );
      expect(results.length).toBeGreaterThanOrEqual(1);
    });

    it('filters by search term in description', async () => {
      const results = await beadOps.findByProjectIdFiltered(
        projectId, null, null, null, null, null, null, 'searchable', 'searchable', 'searchable', null, null, 50
      );
      expect(results.length).toBeGreaterThanOrEqual(1);
    });

    it('combined filters narrow results', async () => {
      const results = await beadOps.findByProjectIdFiltered(
        projectId, 'ready', 'ready', 'bug', 'bug', 1, 1, null, null, null, null, null, 50
      );
      expect(results.length).toBeGreaterThanOrEqual(1);
      expect(results[0].id).toBe(filteredBeadId);
    });

    it('no-match filter returns empty', async () => {
      const results = await beadOps.findByProjectIdFiltered(
        projectId, 'archived', 'archived', null, null, null, null, null, null, null, null, null, 50
      );
      expect(results.length).toBe(0);
    });
  });

  // ── Upsert conflict paths ─────────────────────────────────────────

  describe('upsert conflict resolution', () => {
    it('settingsOps.set updates on conflict', async () => {
      await settingsOps.set(userId, 'upsert-test', 'first', 'first');
      const v1 = await settingsOps.get(userId, 'upsert-test');
      expect(v1!.value).toBe('first');

      await settingsOps.set(userId, 'upsert-test', 'second', 'second');
      const v2 = await settingsOps.get(userId, 'upsert-test');
      expect(v2!.value).toBe('second');
    });

    it('credentialOps.upsert updates on conflict', async () => {
      const id = randomUUID();
      await credentialOps.upsert(id, userId, 'test-service', 'oauth', 'encrypted-v1', null, 'oauth', 'encrypted-v1', null);
      const v1 = await credentialOps.findByUserAndService(userId, 'test-service');
      expect(v1).toBeTruthy();
      expect(v1!.encryptedValue).toBe('encrypted-v1');

      const id2 = randomUUID();
      await credentialOps.upsert(id2, userId, 'test-service', 'oauth', 'encrypted-v2', null, 'oauth', 'encrypted-v2', null);
      const v2 = await credentialOps.findByUserAndService(userId, 'test-service');
      expect(v2!.encryptedValue).toBe('encrypted-v2');
    });

    it('beadSyncStateOps.upsert updates on conflict', async () => {
      const now = new Date().toISOString();
      await beadSyncStateOps.upsert(projectId, 'hash1', now, null, 'hash1', now, null);
      const v1 = await beadSyncStateOps.findByProjectId(projectId);
      expect(v1!.localFileHash).toBe('hash1');

      await beadSyncStateOps.upsert(projectId, 'hash2', now, now, 'hash2', now, now);
      const v2 = await beadSyncStateOps.findByProjectId(projectId);
      expect(v2!.localFileHash).toBe('hash2');
      expect(v2!.githubSyncedAt).toBeInstanceOf(Date);
    });

    it('agentConfigOps.upsert updates on conflict', async () => {
      const config1 = JSON.stringify({ model: 'v1' });
      await agentConfigOps.upsert(projectId, config1, config1);
      const v1 = await agentConfigOps.findByProjectId(projectId);
      expect(v1!.config).toBe(config1);

      const config2 = JSON.stringify({ model: 'v2' });
