      expect(v1!.content).toBe('val1');

      await projectMemoryOps.upsert(randomUUID(), projectId, 'edge-key', 'val2', userId, 'val2', userId);
      const v2 = await projectMemoryOps.findByProjectIdAndKey(projectId, 'edge-key');
