      await globalMemoryOps.upsert(randomUUID(), userId, 'edge-pref', 'val2', 'val2');
      const v2 = await globalMemoryOps.findByUserIdAndKey(userId, 'edge-pref');
      expect(v2!.content).toBe('val2');
