  describe('worktreeRunOps', () => {
    it('create and update worktree run', async () => {
      const beadId = randomUUID();
      await beadOps.create(beadId, projectId, 'Worktree parent', null, 'blocked', 2, null, null, null, null, null, null, null, null, 'task', null);

