    });

    it('agentJobOps.findById returns null for missing ID', async () => {
      expect(await agentJobOps.findById('nonexistent')).toBeNull();
    });

    it('settingsOps.get returns null for missing key', async () => {
      expect(await settingsOps.get(userId, 'nonexistent-key')).toBeNull();
    });

    it('credentialOps.findByUserAndService returns null for missing service', async () => {
      expect(await credentialOps.findByUserAndService(userId, 'no-such-service')).toBeNull();
    });
  });
});

