/**
 * API-level integration tests for Organizations and Teams.
 *
 * Tests the response shape from org/team ops to verify field names
 * match what the frontend expects. Since the org routes have complex
 * middleware chains (requireOrgMember, requireOrgAdmin), we test the
 * ops + response formatting directly rather than through HTTP.
 *
 * Usage: POSTGRES_URL="postgresql://..." npx vitest run src/__tests__/api-orgs-teams.test.ts
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { randomUUID } from 'crypto';

if (!process.env.POSTGRES_URL) {
  throw new Error('POSTGRES_URL env var required');
}

const {
  userOps, projectOps, orgOps, orgMemberOps, orgInvitationOps,
  teamOps, teamMemberOps, teamProjectOps, auditLogOps,
  activityLogOps, beadOps, agentJobOps, initializeDatabase,
} = await import('../db/ops.js');

import { pool } from '../db/postgres.js';

const userId = randomUUID();
const projectId = randomUUID();
let orgId: string;
let teamId: string;

describe('Orgs & Teams response field validation', () => {
  beforeAll(async () => {
    await pool.query('TRUNCATE TABLE team_projects, team_members, teams, organization_invitations, organization_members, organizations, sso_identity_links, org_audit_log, bead_comments, readiness_outcomes, agent_jobs, beads, activity_log, notifications, settings, project_memory, global_memory, project_members, project_invitations, project_agent_config, bead_sync_state, api_tokens, auth_events, github_installation_repos, github_installations, github_issue_sync, agent_sessions, agents, orchestration_plans, plan_items, drains, worktree_runs, credentials, projects, sessions, users CASCADE');
    await initializeDatabase();

    await userOps.create(userId, 'orguser', 'Org Test User', 'https://avatar.test/org', 'org@test.com', null, `google-org-${randomUUID()}`);
    await projectOps.create(projectId, userId, 'Org Project', '/org', 'user/org-repo', null, 'claude', 'claude-sonnet-4-20250514', 'pr', false);

    orgId = randomUUID();
    await orgOps.create(orgId, 'API Test Org', 'api-test-org', userId, null, 'member');
    await orgMemberOps.add(orgId, userId, 'owner');

    teamId = randomUUID();
    await teamOps.create(teamId, orgId, 'API Team', 'api-team', 'The API team');
    await teamMemberOps.add(teamId, userId, 'lead');
    await teamProjectOps.add(teamId, projectId, 'admin');
  });

  afterAll(async () => {
    await pool.query('TRUNCATE TABLE team_projects, team_members, teams, organization_invitations, organization_members, organizations, sso_identity_links, org_audit_log, bead_comments, readiness_outcomes, agent_jobs, beads, activity_log, notifications, settings, project_memory, global_memory, project_members, project_invitations, project_agent_config, bead_sync_state, api_tokens, auth_events, github_installation_repos, github_installations, github_issue_sync, agent_sessions, agents, orchestration_plans, plan_items, drains, worktree_runs, credentials, projects, sessions, users CASCADE');
    await pool.end();
  });

  // ── Org operations ─────────────────────────────────────────────────

  describe('orgOps response shapes', () => {
    it('findById returns camelCase org fields', async () => {
      const org = await orgOps.findById(orgId);
      expect(org).toBeTruthy();
      expect(org).toHaveProperty('id', orgId);
      expect(org).toHaveProperty('name', 'API Test Org');
      expect(org).toHaveProperty('slug', 'api-test-org');
      expect(org).toHaveProperty('ownerId', userId);
      expect(org).toHaveProperty('defaultProjectRole', 'member');
      expect(org).toHaveProperty('ssoEnforced');
      expect(org).toHaveProperty('createdAt');
      expect(org!.createdAt).toBeInstanceOf(Date);
      // No snake_case
      expect(org).not.toHaveProperty('owner_id');
      expect(org).not.toHaveProperty('default_project_role');
      expect(org).not.toHaveProperty('sso_enforced');
    });
  });

  // ── Org members JOIN ───────────────────────────────────────────────

  describe('orgMemberOps JOIN queries', () => {
    it('findByOrgId returns members with user details from JOIN', async () => {
      const members = await orgMemberOps.findByOrgId(orgId);
      expect(members.length).toBe(1);
      const m = members[0];

      // Core membership fields (camelCase from Drizzle select)
      expect(m).toHaveProperty('orgId', orgId);
      expect(m).toHaveProperty('userId', userId);
      expect(m).toHaveProperty('role', 'owner');
      expect(m).toHaveProperty('ssoLinked');
      expect(typeof m.ssoLinked).toBe('boolean');

      // Joined user fields — these are aliased in the Drizzle select
      expect(m).toHaveProperty('username', 'orguser');
      expect(m).toHaveProperty('display_name', 'Org Test User');
      expect(m).toHaveProperty('avatar_url', 'https://avatar.test/org');
      expect(m).toHaveProperty('email', 'org@test.com');
    });

    it('findByUserId returns orgs with org details from JOIN', async () => {
      const orgs = await orgMemberOps.findByUserId(userId);
      expect(orgs.length).toBeGreaterThanOrEqual(1);
      const o = orgs.find(x => x.orgId === orgId)!;

      expect(o).toHaveProperty('orgId', orgId);
      expect(o).toHaveProperty('role', 'owner');
      expect(o).toHaveProperty('name', 'API Test Org');
      expect(o).toHaveProperty('slug', 'api-test-org');
      expect(o).toHaveProperty('org_avatar');
    });

    it('findMembership returns single membership', async () => {
      const m = await orgMemberOps.findMembership(orgId, userId);
      expect(m).toBeTruthy();
      expect(m!.role).toBe('owner');
    });

    it('countByOrgId returns number', async () => {
      const result = await orgMemberOps.countByOrgId(orgId);
      expect(result!.count).toBe(1);
      expect(typeof result!.count).toBe('number');
    });
  });

  // ── Team members JOIN ──────────────────────────────────────────────

  describe('teamMemberOps JOIN queries', () => {
    it('findByTeamId returns members with user details', async () => {
      const members = await teamMemberOps.findByTeamId(teamId);
      expect(members.length).toBe(1);
      const m = members[0];

      expect(m).toHaveProperty('teamId', teamId);
      expect(m).toHaveProperty('userId', userId);
      expect(m).toHaveProperty('role', 'lead');
      expect(m).toHaveProperty('display_name', 'Org Test User');
      expect(m).toHaveProperty('avatar_url', 'https://avatar.test/org');
    });

    it('findByUserId returns teams with team details', async () => {
      const teams = await teamMemberOps.findByUserId(userId);
      expect(teams.length).toBeGreaterThanOrEqual(1);
      const t = teams.find(x => x.teamId === teamId)!;

      expect(t).toHaveProperty('teamId', teamId);
      expect(t).toHaveProperty('name', 'API Team');
      expect(t).toHaveProperty('slug', 'api-team');
      expect(t).toHaveProperty('org_id', orgId);
    });
  });

  // ── Team projects JOIN ─────────────────────────────────────────────

  describe('teamProjectOps JOIN queries', () => {
    it('findByTeamId returns projects with project names', async () => {
      const projects = await teamProjectOps.findByTeamId(teamId);
      expect(projects.length).toBe(1);
      const tp = projects[0];

      expect(tp).toHaveProperty('teamId', teamId);
      expect(tp).toHaveProperty('projectId', projectId);
      expect(tp).toHaveProperty('accessRole', 'admin');
      expect(tp).toHaveProperty('project_name', 'Org Project');
      expect(tp).toHaveProperty('github_repo', 'user/org-repo');
    });

    it('findByProjectId returns teams with team names', async () => {
      const teams = await teamProjectOps.findByProjectId(projectId);
      expect(teams.length).toBeGreaterThanOrEqual(1);
      const t = teams.find(x => x.teamId === teamId)!;

      expect(t).toHaveProperty('team_name', 'API Team');
      expect(t).toHaveProperty('slug', 'api-team');
    });
  });

  // ── Audit log JOIN ─────────────────────────────────────────────────

  describe('auditLogOps JOIN queries', () => {
    it('findByOrgId returns entries with actor details', async () => {
      await auditLogOps.create(randomUUID(), orgId, userId, 'member.added', 'user', userId, JSON.stringify({ role: 'owner' }), '127.0.0.1');

      const rows = await auditLogOps.findByOrgId(orgId, 10) as any;
      const entries = rows.rows ?? rows;
      expect(entries.length).toBeGreaterThanOrEqual(1);
      const entry = entries[0];

      // Raw SQL fields
      expect(entry).toHaveProperty('actor_name', 'Org Test User');
      expect(entry).toHaveProperty('actor_avatar', 'https://avatar.test/org');
      expect(entry).toHaveProperty('action', 'member.added');
      expect(entry).toHaveProperty('org_id', orgId);

      // Metadata should be parseable
      const metadata = typeof entry.metadata === 'string' ? JSON.parse(entry.metadata) : entry.metadata;
      expect(metadata).toHaveProperty('role', 'owner');
    });
  });

  // ── Org invitations ────────────────────────────────────────────────

  describe('orgInvitationOps', () => {
    it('create and query invitation', async () => {
      const invId = randomUUID();
      await orgInvitationOps.create(invId, orgId, 'newmember@test.com', userId, 'member', null);

      const byOrg = await orgInvitationOps.findByOrgId(orgId);
      expect(byOrg.length).toBeGreaterThanOrEqual(1);
      const inv = byOrg.find(i => i.email === 'newmember@test.com')!;
      expect(inv).toHaveProperty('orgId', orgId);
      expect(inv).toHaveProperty('invitedBy', userId);
      expect(inv).toHaveProperty('role', 'member');
      expect(inv).toHaveProperty('expiresAt');
      expect(inv.expiresAt).toBeInstanceOf(Date);

      const byEmail = await orgInvitationOps.findByEmail('newmember@test.com');
      expect(byEmail.length).toBeGreaterThanOrEqual(1);
    });
  });
});

