/**
 * API integration tests for Organizations and Teams routes.
 *
 * These routes use raw SQL JOINs that return snake_case field names —
 * highest risk of field naming mismatch in API responses.
 *
 * Usage: POSTGRES_URL="postgresql://..." npx vitest run src/__tests__/api-orgs-teams.test.ts
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import request from 'supertest';

if (!process.env.POSTGRES_URL) {
  throw new Error('POSTGRES_URL env var required');
}

// Must import test-app after POSTGRES_URL is set
import type { TestContext } from './test-app.js';
const { setupTestApp } = await import('./test-app.js');

// Add org/team routes to the test app
import orgRoutes from '../routes/orgs.js';
import teamRoutes from '../routes/teams.js';
import activityRoutes from '../routes/activity.js';

import { Router } from 'express';

let ctx: TestContext;
let orgId: string;
let teamId: string;

describe('Orgs & Teams API', () => {
  beforeAll(async () => {
    ctx = await setupTestApp();
    // Mount routes the same way as production index.ts
    const apiRouter = Router({ mergeParams: true });
    apiRouter.use('/orgs', orgRoutes);
    apiRouter.use('/orgs/:orgId/teams', teamRoutes);
    apiRouter.use('/activity', activityRoutes);
    // Insert before the 404 catch-all
    ctx.app.use('/api', apiRouter);
  });

  afterAll(async () => {
    // Clean up org data before user/project cleanup
    const { pgDb } = await import('../db/postgres.js');
    const { sql } = await import('drizzle-orm');
    if (teamId) {
      await pgDb.execute(sql`DELETE FROM team_projects WHERE team_id = ${teamId}`);
      await pgDb.execute(sql`DELETE FROM team_members WHERE team_id = ${teamId}`);
      await pgDb.execute(sql`DELETE FROM teams WHERE id = ${teamId}`);
    }
    if (orgId) {
      await pgDb.execute(sql`DELETE FROM organization_invitations WHERE org_id = ${orgId}`);
      await pgDb.execute(sql`DELETE FROM organization_members WHERE org_id = ${orgId}`);
      await pgDb.execute(sql`DELETE FROM org_audit_log WHERE org_id = ${orgId}`);
      await pgDb.execute(sql`DELETE FROM organizations WHERE id = ${orgId}`);
    }
    await ctx.cleanup();
  });

  // ── Organizations ──────────────────────────────────────────────────

  describe('POST /api/orgs', () => {
    it('creates an organization', async () => {
      const res = await request(ctx.app)
        .post('/api/orgs')
        .set('Authorization', `Bearer ${ctx.token}`)
        .send({ name: 'Test Org', slug: 'test-org-api' });

      expect(res.status).toBe(201);
      expect(res.body).toHaveProperty('id');
      expect(res.body.name).toBe('Test Org');
      expect(res.body.slug).toBe('test-org-api');
      orgId = res.body.id;
    });
  });

  describe('GET /api/orgs/:orgId', () => {
    it('returns org with camelCase fields', async () => {
      const res = await request(ctx.app)
        .get(`/api/orgs/${orgId}`)
        .set('Authorization', `Bearer ${ctx.token}`);

      expect(res.status).toBe(200);
      expect(res.body).toHaveProperty('id', orgId);
      expect(res.body).toHaveProperty('name', 'Test Org');
      expect(res.body).toHaveProperty('ownerId', ctx.userId);
      expect(res.body).toHaveProperty('createdAt');
      // Should NOT have snake_case
      expect(res.body).not.toHaveProperty('owner_id');
      expect(res.body).not.toHaveProperty('created_at');
    });
  });

  describe('GET /api/orgs/:orgId/members', () => {
    it('returns members with display names from JOIN', async () => {
      const res = await request(ctx.app)
        .get(`/api/orgs/${orgId}/members`)
        .set('Authorization', `Bearer ${ctx.token}`);

      expect(res.status).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBeGreaterThanOrEqual(1);

      const member = res.body[0];
      expect(member).toHaveProperty('userId');
      expect(member).toHaveProperty('role');
      // These come from the JOIN — verify they're present
      expect(member.displayName !== undefined || member.display_name !== undefined).toBe(true);
    });
  });

  describe('POST /api/orgs/:orgId/invite', () => {
    it('creates an invitation', async () => {
      const res = await request(ctx.app)
        .post(`/api/orgs/${orgId}/invite`)
        .set('Authorization', `Bearer ${ctx.token}`)
        .send({ email: 'invite@test.com', role: 'member' });

      expect(res.status).toBe(201);
      expect(res.body).toHaveProperty('id');
      expect(res.body.email).toBe('invite@test.com');
    });
  });

  describe('GET /api/orgs/:orgId/invitations', () => {
    it('returns invitations list', async () => {
      const res = await request(ctx.app)
        .get(`/api/orgs/${orgId}/invitations`)
        .set('Authorization', `Bearer ${ctx.token}`);

      expect(res.status).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBeGreaterThanOrEqual(1);
    });
  });

  // ── Teams ──────────────────────────────────────────────────────────

  describe('POST /api/orgs/:orgId/teams', () => {
    it('creates a team', async () => {
      const res = await request(ctx.app)
        .post(`/api/orgs/${orgId}/teams`)
        .set('Authorization', `Bearer ${ctx.token}`)
        .send({ name: 'Engineering', slug: 'engineering', description: 'The eng team' });

      expect(res.status).toBe(201);
      expect(res.body).toHaveProperty('id');
      expect(res.body.name).toBe('Engineering');
      teamId = res.body.id;
    });
  });

  describe('GET /api/orgs/:orgId/teams', () => {
    it('returns teams list', async () => {
      const res = await request(ctx.app)
        .get(`/api/orgs/${orgId}/teams`)
        .set('Authorization', `Bearer ${ctx.token}`);

      expect(res.status).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBeGreaterThanOrEqual(1);
    });
  });

  describe('POST /api/orgs/:orgId/teams/:teamId/members', () => {
    it('adds a member to the team', async () => {
      const res = await request(ctx.app)
        .post(`/api/orgs/${orgId}/teams/${teamId}/members`)
        .set('Authorization', `Bearer ${ctx.token}`)
        .send({ userId: ctx.userId, role: 'member' });

      expect(res.status).toBe(201);
    });
  });

  describe('GET /api/orgs/:orgId/teams/:teamId/members', () => {
    it('returns team members with display names from JOIN', async () => {
      const res = await request(ctx.app)
        .get(`/api/orgs/${orgId}/teams/${teamId}/members`)
        .set('Authorization', `Bearer ${ctx.token}`);

      expect(res.status).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBeGreaterThanOrEqual(1);

      const member = res.body[0];
      expect(member).toHaveProperty('userId');
      expect(member).toHaveProperty('role');
      // JOIN fields
      expect(member.displayName !== undefined || member.display_name !== undefined).toBe(true);
    });
  });

  describe('POST /api/orgs/:orgId/teams/:teamId/projects', () => {
    it('assigns a project to the team', async () => {
      const res = await request(ctx.app)
        .post(`/api/orgs/${orgId}/teams/${teamId}/projects`)
        .set('Authorization', `Bearer ${ctx.token}`)
        .send({ projectId: ctx.projectId, accessRole: 'admin' });

      expect(res.status).toBe(201);
    });
  });

  describe('GET /api/orgs/:orgId/teams/:teamId/projects', () => {
    it('returns team projects with project names from JOIN', async () => {
      const res = await request(ctx.app)
        .get(`/api/orgs/${orgId}/teams/${teamId}/projects`)
        .set('Authorization', `Bearer ${ctx.token}`);

      expect(res.status).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBeGreaterThanOrEqual(1);

      const tp = res.body[0];
      expect(tp).toHaveProperty('projectId');
      expect(tp).toHaveProperty('accessRole');
    });
  });

  // ── Activity Log ───────────────────────────────────────────────────

  describe('GET /api/activity/:projectId', () => {
    it('returns activity log entries', async () => {
      // Create some activity first
      const { activityLogOps } = await import('../db/ops.js');
      const { randomUUID } = await import('crypto');
      await activityLogOps.create(randomUUID(), ctx.projectId, ctx.userId, 'user', 'bead.created', 'bead', 'test-bead', null, null);

      const res = await request(ctx.app)
        .get(`/api/activity/${ctx.projectId}`)
        .set('Authorization', `Bearer ${ctx.token}`);

      expect(res.status).toBe(200);
      expect(res.body).toHaveProperty('data');
      expect(Array.isArray(res.body.data)).toBe(true);
    });
  });

  // ── Auth: unauthenticated requests ─────────────────────────────────

  describe('unauthenticated access', () => {
    it('returns 401 without token', async () => {
      const res = await request(ctx.app).get(`/api/orgs/${orgId}`);
      expect(res.status).toBe(401);
    });
  });
});

