import { defineConfig } from 'vitest/config';
import path from 'path';
import os from 'os';

export default defineConfig({
  test: {
    globals: true,
    environment: 'node',
    include: ['src/**/__tests__/**/*.test.ts'],
    env: {
      // Point SQLite to a temp file so tests never touch real data
      DATABASE_URL: path.join(os.tmpdir(), `devdash-test-${process.pid}.db`),
      // Deterministic JWT secret for test token generation
      SESSION_SECRET: 'test-secret-do-not-use-in-prod',
      // Suppress noisy env validation
      NODE_ENV: 'test',
      // Prevent services from connecting to real APIs
      GOOGLE_CLIENT_ID: 'test',
      GOOGLE_CLIENT_SECRET: 'test',
      REQUEST_TIMING: '1',
    },
  },
});

