#!/usr/bin/env npx tsx
/**
 * Data migration validation script.
 *
 * Compares SQLite source DB against Postgres target to verify:
 * 1. Row counts match across all 36 tables
 * 2. Foreign key integrity (no orphaned references)
 * 3. Unique constraint validity (no duplicates)
 * 4. Timestamp format correctness
 * 5. Boolean conversion (0/1 → true/false)
 *
 * Usage:
 *   POSTGRES_URL="postgresql://..." SQLITE_PATH="./data/devdash.db" npx tsx scripts/validate-migration.ts
 *
 * Run AFTER the data migration script has copied data from SQLite to Postgres.
 */

import pg from 'pg';

const POSTGRES_URL = process.env.POSTGRES_URL;
const SQLITE_PATH = process.env.SQLITE_PATH || './data/devdash.db';

if (!POSTGRES_URL) {
  console.error('POSTGRES_URL env var required');
  process.exit(1);
}

// Lazy-load better-sqlite3 (may not be installed in prod)
let Database: any;
try {
  Database = (await import('better-sqlite3')).default;
} catch {
  console.error('better-sqlite3 not available — install it or run from a dev environment');
  process.exit(1);
}

const sqlite = new Database(SQLITE_PATH, { readonly: true });
const pool = new pg.Pool({ connectionString: POSTGRES_URL });

const ALL_TABLES = [
  'users', 'sessions', 'projects', 'agents', 'settings',
  'orchestration_plans', 'plan_items', 'project_memory', 'global_memory',
  'github_issue_sync', 'agent_sessions', 'agent_jobs', 'credentials',
  'notifications', 'beads', 'project_members', 'project_invitations',
  'drains', 'worktree_runs', 'bead_sync_state', 'activity_log',
  'bead_comments', 'github_installations', 'github_installation_repos',
  'project_agent_config', 'api_tokens', 'organizations',
  'organization_members', 'organization_invitations', 'teams',
  'team_members', 'team_projects', 'sso_identity_links', 'org_audit_log',
  'auth_events', 'readiness_outcomes',
];

// FK relationships to validate (child_table.child_col → parent_table.parent_col)
const FK_CHECKS = [
  ['sessions', 'user_id', 'users', 'id'],
  ['projects', 'user_id', 'users', 'id'],
  ['beads', 'project_id', 'projects', 'id'],
  ['agent_jobs', 'project_id', 'projects', 'id'],
  ['bead_comments', 'bead_id', 'beads', 'id'],
  ['project_members', 'project_id', 'projects', 'id'],
  ['project_members', 'user_id', 'users', 'id'],
  ['notifications', 'user_id', 'users', 'id'],
  ['activity_log', 'project_id', 'projects', 'id'],
  ['credentials', 'user_id', 'users', 'id'],
  ['organization_members', 'org_id', 'organizations', 'id'],
  ['organization_members', 'user_id', 'users', 'id'],
  ['teams', 'org_id', 'organizations', 'id'],
  ['team_members', 'team_id', 'teams', 'id'],
  ['team_members', 'user_id', 'users', 'id'],
  ['team_projects', 'team_id', 'teams', 'id'],
  ['team_projects', 'project_id', 'projects', 'id'],
];

// Unique constraints to validate
const UNIQUE_CHECKS = [
  ['users', ['google_id']],
  ['settings', ['user_id', 'key']],
  ['project_members', ['project_id', 'user_id']],
  ['project_invitations', ['project_id', 'email']],
  ['credentials', ['user_id', 'service']],
  ['organizations', ['slug']],
  ['organization_members', ['org_id', 'user_id']],
  ['teams', ['org_id', 'slug']],
  ['team_members', ['team_id', 'user_id']],
  ['team_projects', ['team_id', 'project_id']],
] as const;

// Boolean columns that should be true/false in Postgres (were 0/1 in SQLite)
const BOOLEAN_CHECKS = [
  ['users', 'onboarding_completed'],
  ['projects', 'github_sync_enabled'],
  ['projects', 'auto_dispatch_ready'],
  ['notifications', 'read'],
  ['organizations', 'sso_enforced'],
  ['organization_members', 'sso_linked'],
  ['github_installation_repos', 'private'],
  ['worktree_runs', 'analyzed'],
  ['beads', 'escalated'],
  ['readiness_outcomes', 'auto_readied'],
];

let passed = 0;
let failed = 0;
let warnings = 0;

function pass(msg: string) { passed++; console.log(`  ✅ ${msg}`); }
function fail(msg: string) { failed++; console.log(`  ❌ ${msg}`); }
function warn(msg: string) { warnings++; console.log(`  ⚠️  ${msg}`); }

async function main() {
  console.log('=== Data Migration Validation ===\n');
  console.log(`SQLite: ${SQLITE_PATH}`);
  console.log(`Postgres: ${POSTGRES_URL?.replace(/:[^@]+@/, ':***@')}\n`);

  // ── 1. Row count comparison ──────────────────────────────────────

  console.log('1. Row Count Comparison\n');
  let totalSqlite = 0;
  let totalPostgres = 0;

  for (const table of ALL_TABLES) {
    try {
      const sqliteCount = sqlite.prepare(`SELECT COUNT(*) as count FROM ${table}`).get() as any;
      const pgResult = await pool.query(`SELECT COUNT(*)::int as count FROM ${table}`);
      const sqliteN = sqliteCount.count;
      const pgN = pgResult.rows[0].count;
      totalSqlite += sqliteN;
      totalPostgres += pgN;

      if (sqliteN === pgN) {
        pass(`${table}: ${sqliteN} rows`);
      } else {
        fail(`${table}: SQLite=${sqliteN}, Postgres=${pgN} (diff: ${pgN - sqliteN})`);
      }
    } catch (e: any) {
      if (e.message?.includes('no such table')) {
        warn(`${table}: not in SQLite (new table?)`);
      } else {
        fail(`${table}: ${e.message}`);
      }
    }
  }

  console.log(`\n  Total: SQLite=${totalSqlite}, Postgres=${totalPostgres}\n`);

  // ── 2. Foreign key integrity ─────────────────────────────────��───

  console.log('2. Foreign Key Integrity (Postgres)\n');

  for (const [childTable, childCol, parentTable, parentCol] of FK_CHECKS) {
    const result = await pool.query(`
      SELECT COUNT(*) as orphans FROM ${childTable} c
      LEFT JOIN ${parentTable} p ON c.${childCol} = p.${parentCol}
      WHERE p.${parentCol} IS NULL AND c.${childCol} IS NOT NULL
    `);
    const orphans = parseInt(result.rows[0].orphans);
    if (orphans === 0) {
      pass(`${childTable}.${childCol} → ${parentTable}.${parentCol}`);
    } else {
      fail(`${childTable}.${childCol} → ${parentTable}.${parentCol}: ${orphans} orphaned rows`);
    }
  }

  console.log('');

  // ── 3. Unique constraint validation ──────────────────────────���───

  console.log('3. Unique Constraint Validation (Postgres)\n');

  for (const [table, columns] of UNIQUE_CHECKS) {
    const cols = (columns as readonly string[]).join(', ');
    const result = await pool.query(`
      SELECT ${cols}, COUNT(*) as dupes FROM ${table}
      WHERE ${(columns as readonly string[]).map(c => `${c} IS NOT NULL`).join(' AND ')}
      GROUP BY ${cols}
      HAVING COUNT(*) > 1
    `);
    if (result.rows.length === 0) {
      pass(`${table} (${cols}): no duplicates`);
    } else {
      fail(`${table} (${cols}): ${result.rows.length} duplicate groups`);
    }
  }

  console.log('');

  // ── 4. Timestamp spot-check ──────────────────────────────────────

  console.log('4. Timestamp Spot-Check\n');

  const timestampTables = ['users', 'projects', 'beads', 'agent_jobs'];
  for (const table of timestampTables) {
    try {
      const pgResult = await pool.query(`SELECT created_at FROM ${table} LIMIT 5`);
      const allValid = pgResult.rows.every(r => {
        if (!r.created_at) return true;
        const d = new Date(r.created_at);
        return !isNaN(d.getTime()) && d.getFullYear() > 2020;
      });
      if (allValid) {
        pass(`${table}.created_at: valid timestamps (${pgResult.rows.length} sampled)`);
      } else {
        fail(`${table}.created_at: invalid timestamps found`);
      }
    } catch (e: any) {
      warn(`${table}: ${e.message}`);
    }
  }

  console.log('');

  // ── 5. Boolean conversion check ��─────────────────────────────────

  console.log('5. Boolean Conversion Check (Postgres)\n');

  for (const [table, col] of BOOLEAN_CHECKS) {
    try {
      const result = await pool.query(`
        SELECT DISTINCT pg_typeof(${col})::text as dtype FROM ${table} WHERE ${col} IS NOT NULL LIMIT 1
      `);
      if (result.rows.length === 0) {
        pass(`${table}.${col}: no non-null values (skip)`);
      } else if (result.rows[0].dtype === 'boolean') {
        pass(`${table}.${col}: boolean type ✓`);
      } else {
        fail(`${table}.${col}: expected boolean, got ${result.rows[0].dtype}`);
      }
    } catch (e: any) {
      warn(`${table}.${col}: ${e.message}`);
    }
  }

  console.log('');

  // ── Summary ──────────────────────────────────────────────────────

  console.log('=== Summary ===');
  console.log(`  Passed:   ${passed}`);
  console.log(`  Failed:   ${failed}`);
  console.log(`  Warnings: ${warnings}`);
  console.log('');

  if (failed > 0) {
    console.log('❌ Migration validation FAILED — review errors above');
    process.exit(1);
  } else {
    console.log('✅ Migration validation PASSED');
  }

  sqlite.close();
  await pool.end();
}

main().catch(err => {
  console.error('Validation script error:', err);
  process.exit(1);
});

