  console.log(`  Warnings: ${warnings}`);
  console.log('');

  if (failed > 0) {
    console.log('❌ Migration validation FAILED — review errors above');
    process.exit(1);
  } else {
    console.log('✅ Migration validation PASSED');
  }

  sqlite.close();
  await pool.end();
}

main().catch(err => {
  console.error('Validation script error:', err);
  process.exit(1);
});

