import express from 'express';
import cors from 'cors';
import session from 'express-session';
import passport from 'passport';
import cookieParser from 'cookie-parser';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import { MemoryRateLimitStore } from './middleware/memory-rate-limit-store.js';
import { createServer } from 'http';
import { Server as SocketServer } from 'socket.io';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Load environment variables from root .env file
dotenv.config({ path: path.resolve(__dirname, '../../.env') });

// Validate environment configuration (fail fast on missing required secrets)
import { validateEnv, logEnvStatus } from './config/env.js';
try {
  const envConfig = validateEnv();
  logEnvStatus(envConfig);
} catch (err) {
  console.error('Environment validation failed:', err);
  process.exit(1);
}

// Import database and initialize
import { initializeDatabase, agentJobOps, migrateCredentialEncryption } from './db/ops.js';
import { requireProjectAccess } from './middleware/project-access.js';
await initializeDatabase();
await migrateCredentialEncryption();

// Import routes
import authRoutes from './routes/auth.js';
import projectRoutes from './routes/projects.js';
import agentRoutes from './routes/agents.js';
import beadsRoutes from './routes/beads.js';
import reposRoutes from './routes/repos.js';
import memoryRoutes from './routes/memory.js';
import orchestrationRoutes from './routes/orchestration.js';
import syncRoutes from './routes/sync.js';
import jobRoutes from './routes/jobs.js';
import notificationRoutes from './routes/notifications.js';
import worktreeRoutes from './routes/worktree.js';
import settingsRoutes from './routes/settings.js';
import chatRoutes from './routes/chat.js';
import eventsRoutes from './routes/events.js';
import webhookRoutes from './routes/webhooks.js';
import specRoutes from './routes/spec.js';
import drainRoutes from './routes/drain.js';
import activityRoutes from './routes/activity.js';
import beadCommentRoutes from './routes/bead-comments.js';
import emailExtractRoutes from './routes/email-extract.js';
import orgRoutes from './routes/orgs.js';
import teamRoutes from './routes/teams.js';
import ssoRoutes from './routes/sso.js';
import adminRoutes from './routes/admin.js';

// Import services
import { agentRunner } from './services/agent-runner.js';
import { agentDispatcher } from './services/agent-dispatch.js';
import { jobQueue } from './services/job-queue.js';
import { repoAnalyzer } from './services/repo-analyzer.js';
import { syncOutbox } from './services/sync-outbox.js';
import { worktreeExecutor } from './services/worktree-executor.js';
import { backlogHealth } from './services/backlog-health.js';
import { drainManager } from './services/drain-manager.js';
import { verifyToken } from './middleware/auth.js';
import { requestTiming } from './middleware/request-timing.js';

const app = express();
const httpServer = createServer(app);

const clientUrl = process.env.CLIENT_URL || 'http://localhost:5173';
const apiUrl = process.env.API_URL || 'http://localhost:3001';

// Detect cross-origin setup (different domains for frontend and backend)
const clientOrigin = new URL(clientUrl).origin;
const apiOrigin = new URL(apiUrl).origin;
const isCrossOrigin = clientOrigin !== apiOrigin;
const isProduction = process.env.NODE_ENV === 'production' || isCrossOrigin;

console.log(`[Auth Config] CLIENT_URL: ${clientUrl}, API_URL: ${apiUrl}`);
console.log(`[Auth Config] Cross-origin: ${isCrossOrigin}, Production mode: ${isProduction}`);

// Trust proxy in production (Railway runs behind a proxy)
if (isProduction) {
  app.set('trust proxy', 1);
}

// Multi-origin CORS: allow satellite apps (DD Red, Yellow, Violet) via ALLOWED_ORIGINS
// Supports exact URLs and wildcard patterns like *.vercel.app for preview deploys
const allowedOrigins: string[] = [clientUrl];
if (process.env.ALLOWED_ORIGINS) {
  allowedOrigins.push(...process.env.ALLOWED_ORIGINS.split(',').map(s => s.trim()));
}

function isOriginAllowed(origin: string | undefined): boolean {
  if (!origin) return false;
  for (const allowed of allowedOrigins) {
    if (allowed === origin) return true;
    // Wildcard pattern: "*.vercel.app" matches any subdomain
    if (allowed.startsWith('*.')) {
      const suffix = allowed.slice(1); // ".vercel.app"
      if (origin.endsWith(suffix) && origin.includes('://')) return true;
    }
  }
  return false;
}

const corsOriginFn = (origin: string | undefined, callback: (err: Error | null, allow?: boolean) => void) => {
  // No-origin requests (server-to-server, curl, CLI) are allowed through CORS.
  // Cookie-auth CSRF is mitigated by the X-Requested-With header requirement (see CSRF middleware).
  if (!origin || isOriginAllowed(origin)) {
    callback(null, true);
  } else {
    callback(null, false);
  }
};

// Socket.io setup
const io = new SocketServer(httpServer, {
  cors: {
    origin: corsOriginFn,
    credentials: true,
  },
});

// Request timing (opt-in via REQUEST_TIMING=1, always on in test)
app.use(requestTiming);

// Security headers
app.use(helmet({
  contentSecurityPolicy: false, // CSP managed per-route as needed
  crossOriginEmbedderPolicy: false, // Allow cross-origin resource loading
}));

// Rate limiting (in-memory store — no DB writes per request)
// Bearer-token requests (CLI, API integrations) get a higher ceiling than
// anonymous/cookie-based browser requests.  The token is validated later by
// requireAuth — here we only check for its *presence* to pick a tier.
const hasBearerToken = (req: any) =>
  typeof req.headers?.authorization === 'string' &&
  req.headers.authorization.startsWith('Bearer ');

const globalLimiter = rateLimit({
  windowMs: 60_000, // 1 minute
  max: 200,         // 200 requests per minute per IP (browser / anonymous)
  store: new MemoryRateLimitStore('global', 60_000),
  standardHeaders: true,
  legacyHeaders: false,
  skip: hasBearerToken,
  message: { error: 'Too many requests, please try again later' },
});
const apiTokenLimiter = rateLimit({
  windowMs: 60_000,
  max: 1800,        // 1800 requests per minute for authenticated API clients (MCP bursts)
  store: new MemoryRateLimitStore('api-token', 60_000),
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req: any) => !hasBearerToken(req),
  message: { error: 'Too many requests, please try again later' },
});
const authLimiter = rateLimit({
  windowMs: 60_000,
  max: 10, // Stricter for auth endpoints
  store: new MemoryRateLimitStore('auth', 60_000),
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many auth requests, please try again later' },
});
const dispatchLimiter = rateLimit({
  windowMs: 60_000,
  max: 5, // Very strict for agent dispatch
  store: new MemoryRateLimitStore('dispatch', 60_000),
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many dispatch requests, please try again later' },
});
// CORS must run before rate limiting so that:
// 1. OPTIONS preflight requests are handled immediately (never hit rate limiter)
// 2. Rate-limited 429 responses still carry CORS headers (browser won't block them)
app.use(cors({
  origin: corsOriginFn,
  credentials: true,
}));

// Rate limiters apply to both /api/ and /api/v1/
app.use('/api/', globalLimiter);
app.use('/api/', apiTokenLimiter);
app.use('/api/auth/google', authLimiter);
app.use('/api/auth/exchange-code', authLimiter);
app.use('/api/auth/cli-token', authLimiter);
app.use('/api/jobs', dispatchLimiter);
app.use('/api/v1/auth/google', authLimiter);
app.use('/api/v1/auth/exchange-code', authLimiter);
app.use('/api/v1/auth/cli-token', authLimiter);
app.use('/api/v1/jobs', dispatchLimiter);
app.use(express.json({
  verify: (req: any, _res, buf) => {
    // Capture raw body for webhook signature verification
    if (req.url?.startsWith('/api/webhooks/')) {
      req.rawBody = buf;
    }
  },
}));
app.use(cookieParser());

// Per-request cache for repeated DB lookups (project, user)
import { requestCache } from './middleware/request-cache.js';
app.use(requestCache);

// Session configuration (for Passport) — MemoryStore (TODO: migrate to Postgres-backed store)
app.use(session({
  secret: process.env.SESSION_SECRET || 'dev-secret',
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: isProduction,
    httpOnly: true,
    sameSite: isProduction ? 'none' : 'lax', // 'none' required for cross-origin in production
    maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
  },
}));

// Initialize Passport
app.use(passport.initialize());
app.use(passport.session());

// CSRF protection: require X-Requested-With header on mutating requests
// when using cookie auth with sameSite: 'none'. Browsers block custom headers
// on cross-origin requests without a preflight, acting as implicit CSRF protection.
// Skip for: webhook routes (verified by signature), OAuth callbacks, health checks.
if (isProduction) {
  app.use('/api/', (req, res, next) => {
    // Only check mutating methods
    if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
      return next();
    }
    // Skip routes that have their own auth (webhooks, OAuth callbacks)
    if (req.path.startsWith('/api/webhooks/') || req.path.startsWith('/api/auth/google') || req.path.startsWith('/api/auth/github')) {
      return next();
    }
    // If using Bearer token auth, CSRF isn't a concern (token can't be sent automatically)
    if (req.headers.authorization?.startsWith('Bearer ')) {
      return next();
    }
    // Cookie-only auth: require the custom header
    if (req.cookies?.token && !req.headers['x-requested-with']) {
      return res.status(403).json({ error: 'Missing X-Requested-With header' });
    }
    next();
  });
}

// ── API Router ──────────────────────────────────────────────────
// All routes mounted on a sub-router, then exposed at both /api/v1 and /api
import { Router } from 'express';
const apiRouter = Router();

import { resolveProjectId } from './middleware/resolve-project-id.js';
apiRouter.use(resolveProjectId);

apiRouter.use('/auth', authRoutes);
apiRouter.use('/projects', projectRoutes);
apiRouter.use('/agents', agentRoutes);
apiRouter.use('/beads', beadsRoutes);
apiRouter.use('/repos', reposRoutes);
apiRouter.use('/memory', memoryRoutes);
apiRouter.use('/plans', orchestrationRoutes);
apiRouter.use('/sync', syncRoutes);
apiRouter.use('/jobs', jobRoutes);
apiRouter.use('/notifications', notificationRoutes);
apiRouter.use('/worktree', worktreeRoutes);
apiRouter.use('/settings', settingsRoutes);
apiRouter.use('/projects', chatRoutes);
apiRouter.use('/events', eventsRoutes);
apiRouter.use('/webhooks', webhookRoutes);
apiRouter.use('/spec', specRoutes);
apiRouter.use('/projects', drainRoutes);
apiRouter.use('/projects', activityRoutes);
apiRouter.use('/beads', beadCommentRoutes);
apiRouter.use('/orgs', orgRoutes);
apiRouter.use('/orgs/:orgId/teams', teamRoutes);
apiRouter.use('/auth/sso', ssoRoutes);
apiRouter.use('/admin', adminRoutes);
apiRouter.use('/email-extract', emailExtractRoutes);

// Health check
apiRouter.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString(), version: '2.0' });
});

// Catch-all 404 for unmatched API routes
apiRouter.use((_req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Mount at /api/v1 (canonical) and /api (backward-compat alias)
app.use('/api/v1', apiRouter);
app.use('/api', apiRouter);

// Standard OpenAPI discovery paths — serve spec directly
app.use('/openapi.json', specRoutes);
app.use('/.well-known/openapi', specRoutes);

// Legacy admin endpoints removed — migrated to /api/admin/* routes (JWT-auth'd)

// Serve frontend static files (when client/dist exists — single-origin deployment)
const clientDistPath = path.resolve(__dirname, '../../client/dist');
if (fs.existsSync(clientDistPath)) {
  app.use(express.static(clientDistPath));
  // SPA fallback — serve index.html for non-API routes
  app.get('*', (req, res, next) => {
    if (req.path.startsWith('/api') || req.path.startsWith('/socket.io')) {
      return next();
    }
    res.sendFile(path.join(clientDistPath, 'index.html'));
  });
  console.log('[Static] Serving client build from', clientDistPath);
}

// Socket.IO connection handling
io.use(async (socket, next) => {
  try {
    // Get token from cookie or Authorization header
    const cookies = socket.handshake.headers.cookie;
    const authHeader = socket.handshake.headers.authorization;

    let token = null;

    // Try cookie first
    if (cookies) {
      const tokenMatch = cookies.match(/token=([^;]+)/);
      if (tokenMatch) {
        token = tokenMatch[1];
      }
    }

    // Fall back to Authorization header
    if (!token && authHeader?.startsWith('Bearer ')) {
      token = authHeader.substring(7);
    }

    if (!token) {
      return next(new Error('No authentication token'));
    }

    const payload = verifyToken(token);
    if (!payload) {
      return next(new Error('Invalid token'));
    }

    socket.data.userId = payload.userId;
    socket.data.authenticated = true;
    next();
  } catch (error) {
    next(new Error('Authentication failed'));
  }
});

io.on('connection', (socket) => {
  console.log(`Socket connected: ${socket.id} (user: ${socket.data.userId})`);

  // Join user-specific room for notifications
  if (socket.data.userId) {
    socket.join(`user:${socket.data.userId}`);
  }

  // Subscribe to job progress (with project access check)
  socket.on('job:subscribe', async ({ jobId }, callback) => {
    if (!socket.data.authenticated) {
      return callback({ success: false, error: 'Not authenticated' });
    }

    // Verify user has access to the job's project
    const job = await agentJobOps.findById(jobId) as any;
    if (!job) {
      return callback({ success: false, error: 'Job not found' });
    }
    const project = await requireProjectAccess(job.projectId, socket.data.userId);
    if (!project) {
      return callback({ success: false, error: 'Access denied' });
    }

    socket.join(`job:${jobId}`);
    callback({ success: true });
  });

  // Unsubscribe from job progress
  socket.on('job:unsubscribe', ({ jobId }, callback) => {
    socket.leave(`job:${jobId}`);
    callback({ success: true });
  });

  // Start agent (with project access check)
  socket.on('agent:start', async ({ projectId, prompt }, callback) => {
    if (!socket.data.authenticated) {
      return callback({ success: false, error: 'Not authenticated' });
    }

    try {
      // Verify user has access to the project
      const project = await requireProjectAccess(projectId, socket.data.userId) as any;
      if (!project) {
        return callback({ success: false, error: 'Project not found or access denied' });
      }

      // Start agent
      const agentId = await agentRunner.startAgent(
        projectId,
        project.path,
        prompt,
        project.aiProvider,
        project.aiModel
      );

      // Subscribe socket to agent updates
      socket.join(`agent:${agentId}`);

      callback({ success: true, agentId });
    } catch (error) {
      callback({
        success: false,
        error: error instanceof Error ? error.message : 'Failed to start agent',
      });
    }
  });

  // Stop agent (with project access check)
  socket.on('agent:stop', async ({ agentId }, callback) => {
    if (!socket.data.authenticated) {
      return callback({ success: false, error: 'Not authenticated' });
    }

    try {
      // Verify user has access to the agent's project
      const agent = agentRunner.getAgent(agentId);
      if (agent) {
        const project = await requireProjectAccess(agent.projectId, socket.data.userId);
        if (!project) {
          return callback({ success: false, error: 'Access denied' });
        }
      }

      await agentRunner.stopAgent(agentId);
      callback({ success: true });
    } catch (error) {
      callback({
        success: false,
        error: error instanceof Error ? error.message : 'Failed to stop agent',
      });
    }
  });

  socket.on('disconnect', () => {
    console.log(`Socket disconnected: ${socket.id}`);
  });
});

// Forward agent events to Socket.io
agentRunner.on('output', ({ agentId, message }) => {
  io.to(`agent:${agentId}`).emit('agent:output', { agentId, message });
});

agentRunner.on('status', ({ agentId, status }) => {
  io.to(`agent:${agentId}`).emit('agent:status', { agentId, status });
});

// Forward repo analysis events to Socket.io (scoped to the user who triggered it)
repoAnalyzer.on('status', ({ analysisId, status, repoFullName, error, userId }) => {
  if (userId) {
    io.to(`user:${userId}`).emit('analysis:status', { analysisId, status, repoFullName, error });
  }
});

// Forward dispatcher events to Socket.io job rooms
agentDispatcher.subscribeToAll(async (event) => {
  io.to(`job:${event.jobId}`).emit('job:event', event);

  // Worktree executor: cascade dependency resolution on job completion/failure
  if (event.type === 'completed') {
    try { worktreeExecutor.onJobCompleted(event.jobId); } catch (e) {
      console.warn('[WorktreeExecutor] Error on job completed:', e);
    }

    // Drain manager: cascade — queue newly-unblocked beads
    try {
      const job = await jobQueue.getJob(event.jobId);
      if (job?.beadId) {
        drainManager.onBeadCompleted(job.projectId, job.beadId);
      }
    } catch (e) {
      console.warn('[DrainManager] Error on bead completed:', e);
    }
  } else if (event.type === 'failed') {
    try { worktreeExecutor.onJobFailed(event.jobId); } catch (e) {
      console.warn('[WorktreeExecutor] Error on job failed:', e);
    }
  }
});

// Error handling — sanitize error messages in production
app.use((err: any, req: express.Request, res: express.Response, next: express.NextFunction) => {
  console.error('Error:', err);
  const status = err.status || 500;
  // In production, only expose error details for client errors (4xx)
  const message = (isProduction && status >= 500)
    ? 'Internal server error'
    : (err.message || 'Internal server error');
  res.status(status).json({ error: message });
});

// Start server
const PORT = process.env.PORT || 3001;

httpServer.listen(PORT, () => {
  console.log(`
  ╔═══════════════════════════════════════════════╗
  ║                                               ║
  ║   Dev-Dash Server                             ║
  ║   Running on http://localhost:${PORT}            ║
  ║                                               ║
  ╚═══════════════════════════════════════════════╝
  `);

  // Recover any jobs that were running when the server last shut down
  jobQueue.recoverOrphanedJobs();

  // Recover beads stuck in_progress with no active job
  jobQueue.recoverOrphanedBeads();

  // Recover orphaned worktree runs
  worktreeExecutor.recoverOrphanedRuns();

  // Start the agent dispatcher (polls for queued jobs)
  agentDispatcher.start(5000);

  // Start the ready dispatcher (auto-dispatches ready beads for enabled projects)
  import('./services/ready-dispatcher.js').then(({ startReadyDispatcher }) => startReadyDispatcher());

  // Start the sync outbox (flushes bead changes to GitHub Issues)
  syncOutbox.start();

  // Start the backlog health service (auto-analyzes every 4 hours)
  backlogHealth.start();
});

// Graceful shutdown
let isShuttingDown = false;
async function shutdown(signal: string) {
  if (isShuttingDown) return; // Prevent double-shutdown from rapid signals
  isShuttingDown = true;
  console.log(`\n${signal} received. Shutting down gracefully...`);

  // Force exit after 10s if graceful shutdown hangs
  const forceTimer = setTimeout(() => {
    console.error('Graceful shutdown timed out, forcing exit');
    process.exit(1);
  }, 10_000);
  forceTimer.unref(); // Don't let this timer keep the process alive

  // 1. Stop accepting new connections
  io.close();

  // 2. Stop background services (each wrapped so one failure doesn't skip others)
  try { await syncOutbox.stop(); } catch (e) {
    console.error('Error stopping sync outbox:', e);
  }
  try { await agentDispatcher.stop(); } catch (e) {
    console.error('Error stopping agent dispatcher:', e);
  }
  try { const { stopReadyDispatcher } = await import('./services/ready-dispatcher.js'); stopReadyDispatcher(); } catch (e) {
    console.error('Error stopping ready dispatcher:', e);
  }
  try { backlogHealth.stop(); } catch (e) {
    console.error('Error stopping backlog health:', e);
  }
  try { drainManager.stopAll(); } catch (e) {
    console.error('Error stopping drain manager:', e);
  }

  // 3. Close HTTP server (waits for in-flight requests to finish)
  await new Promise<void>((resolve) => {
    httpServer.close(() => resolve());
  });
  console.log('HTTP server closed');

  // 4. Database connection pool closed automatically on process exit

  console.log('Shutdown complete');
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Catch unhandled errors so the process doesn't crash without cleanup
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled promise rejection:', reason);
});
process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
  shutdown('uncaughtException').catch(() => process.exit(1));
});

export { app, httpServer };

