import { Router, Request, Response } from 'express';
import fs from 'fs';
import { requireAuth, requireSystemAdmin } from '../middleware/auth.js';
import { validate } from '../middleware/validate.js';
import { AdminListQuery, UpdateUserRoleBody, AdminAuthEventsQuery } from '../schemas/index.js';
import { db, userOps, beadOps, githubSyncOps, beadSyncStateOps, projectMemoryOps, projectMemberOps, projectInvitationOps, installationOps, installationRepoOps, authEventOps } from '../db/sqlite.js';
import { jobQueue } from '../services/job-queue.js';
import { utc } from '../utils/timestamps.js';

const router = Router();

// All admin routes require auth + system admin
router.use(requireAuth, requireSystemAdmin);

// ─── Users ───────────────────────────────────────────────────────────────────

// GET /api/admin/users?search=&limit=&offset=
router.get('/users', validate({ query: AdminListQuery }), (req: Request, res: Response) => {
  try {
    const { search = '', limit, offset } = req.query as unknown as AdminListQuery;

    let users: any[];
    let total: number;

    if (search) {
      const pattern = `%${search}%`;
      users = userOps.findAllFiltered.all(pattern, pattern, pattern, limit, offset);
      total = (userOps.countFiltered.get(pattern, pattern, pattern) as any).count;
    } else {
      users = db.prepare(
        'SELECT id, username, display_name, avatar_url, email, system_role, onboarding_completed, created_at, updated_at, last_login_at, last_interaction_at FROM users ORDER BY created_at DESC LIMIT ? OFFSET ?'
      ).all(limit, offset);
      total = (userOps.countAll.get() as any).count;
    }

    // Enrich with project counts
    const projectCountStmt = db.prepare('SELECT COUNT(*) as count FROM projects WHERE user_id = ?');
    const enriched = users.map((u: any) => ({
      id: u.id,
      username: u.username,
      displayName: u.display_name,
      avatarUrl: u.avatar_url,
      email: u.email,
      systemRole: u.system_role || null,
      onboardingCompleted: !!u.onboarding_completed,
      projectCount: (projectCountStmt.get(u.id) as any).count,
      createdAt: utc(u.created_at),
      updatedAt: utc(u.updated_at),
      lastLoginAt: utc(u.last_login_at),
      lastInteractionAt: utc(u.last_interaction_at),
    }));

    res.json({ users: enriched, total, limit, offset });
  } catch (error) {
    console.error('[Admin] Error listing users:', error);
    res.status(500).json({ error: 'Failed to list users' });
  }
});

// GET /api/admin/users/:userId
router.get('/users/:userId', (req: Request, res: Response) => {
  try {
    const user = userOps.findById.get(req.params.userId) as any;
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    const projects = db.prepare(
      'SELECT id, name, github_repo, created_at FROM projects WHERE user_id = ? ORDER BY updated_at DESC'
    ).all(user.id);

    const credentialCount = (db.prepare(
      'SELECT COUNT(*) as count FROM credentials WHERE user_id = ?'
    ).get(user.id) as any).count;

    const orgMemberships = db.prepare(
      'SELECT o.id, o.name, o.slug, om.role FROM organizations o JOIN org_members om ON o.id = om.org_id WHERE om.user_id = ?'
    ).all(user.id);

    res.json({
      id: user.id,
      username: user.username,
      displayName: user.display_name,
      avatarUrl: user.avatar_url,
      email: user.email,
      systemRole: user.system_role || null,
      onboardingCompleted: !!user.onboarding_completed,
      createdAt: utc(user.created_at),
      updatedAt: utc(user.updated_at),
      lastLoginAt: utc(user.last_login_at),
      lastInteractionAt: utc(user.last_interaction_at),
      projects,
      credentialCount,
      orgMemberships,
    });
  } catch (error) {
    console.error('[Admin] Error fetching user:', error);
    res.status(500).json({ error: 'Failed to fetch user' });
  }
});

// PATCH /api/admin/users/:userId/role
router.patch('/users/:userId/role', validate({ body: UpdateUserRoleBody }), (req: Request, res: Response) => {
  try {
    const userId = req.params.userId as string;
    const { role } = req.body as UpdateUserRoleBody;

    // Prevent self-demotion
    if (userId === req.user!.id && role !== 'admin') {
      return res.status(400).json({ error: 'Cannot demote yourself' });
    }

    // Prevent last-admin demotion
    if (role !== 'admin') {
      const adminCount = (userOps.countAdmins.get() as any).count;
      const targetUser = userOps.findById.get(userId) as any;
      if (targetUser?.system_role === 'admin' && adminCount <= 1) {
        return res.status(400).json({ error: 'Cannot demote the last admin' });
      }
    }

    const user = userOps.findById.get(userId) as any;
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    userOps.updateSystemRole.run(role, userId);
    console.log(`[Admin] ${req.user!.email} changed role of ${user.email} to ${role || 'none'}`);

    res.json({ success: true, userId, role });
  } catch (error) {
    console.error('[Admin] Error updating user role:', error);
    res.status(500).json({ error: 'Failed to update user role' });
  }
});

// ─── Projects ────────────────────────────────────────────────────────────────

// GET /api/admin/projects?search=&limit=&offset=
router.get('/projects', validate({ query: AdminListQuery }), (req: Request, res: Response) => {
  try {
    const { search = '', limit, offset } = req.query as unknown as AdminListQuery;

    let query = `
      SELECT p.id, p.name, p.github_repo, p.created_at, p.updated_at,
             u.id as owner_id, u.display_name as owner_name, u.email as owner_email
      FROM projects p
      JOIN users u ON p.user_id = u.id
    `;
    let countQuery = 'SELECT COUNT(*) as count FROM projects p JOIN users u ON p.user_id = u.id';
    const params: any[] = [];
    const countParams: any[] = [];

    if (search) {
      const where = ' WHERE p.name LIKE ? OR p.github_repo LIKE ? OR u.display_name LIKE ? OR u.email LIKE ?';
      query += where;
      countQuery += where;
      const pattern = `%${search}%`;
      params.push(pattern, pattern, pattern, pattern);
      countParams.push(pattern, pattern, pattern, pattern);
    }

    query += ' ORDER BY p.updated_at DESC LIMIT ? OFFSET ?';
    params.push(limit, offset);

    const projects = db.prepare(query).all(...params);
    const total = (db.prepare(countQuery).all(...countParams)[0] as any).count;

    // Enrich with counts
    const memberCountStmt = db.prepare('SELECT COUNT(*) as count FROM project_members WHERE project_id = ?');
    const beadCountStmt = db.prepare('SELECT COUNT(*) as count FROM beads WHERE project_id = ?');
    const jobCountStmt = db.prepare('SELECT COUNT(*) as count FROM agent_jobs WHERE project_id = ?');

    const enriched = (projects as any[]).map(p => ({
      id: p.id,
      name: p.name,
      githubRepo: p.github_repo,
      owner: { id: p.owner_id, name: p.owner_name, email: p.owner_email },
      memberCount: (memberCountStmt.get(p.id) as any).count,
      beadCount: (beadCountStmt.get(p.id) as any).count,
      jobCount: (jobCountStmt.get(p.id) as any).count,
      createdAt: utc(p.created_at),
      updatedAt: utc(p.updated_at),
    }));

    res.json({ projects: enriched, total, limit, offset });
  } catch (error) {
    console.error('[Admin] Error listing projects:', error);
    res.status(500).json({ error: 'Failed to list projects' });
  }
});

// GET /api/admin/projects/:projectId
router.get('/projects/:projectId', (req: Request, res: Response) => {
  try {
    const project = db.prepare(`
      SELECT p.*, u.display_name as owner_name, u.email as owner_email
      FROM projects p JOIN users u ON p.user_id = u.id
      WHERE p.id = ?
    `).get(req.params.projectId) as any;

    if (!project) {
      return res.status(404).json({ error: 'Project not found' });
    }

    const members = db.prepare(`
      SELECT pm.user_id, pm.role, pm.permissions, u.display_name, u.email
      FROM project_members pm JOIN users u ON pm.user_id = u.id
      WHERE pm.project_id = ?
    `).all(project.id);

    const recentJobs = db.prepare(`
      SELECT id, status, prompt, created_at, completed_at
      FROM agent_jobs WHERE project_id = ?
      ORDER BY created_at DESC LIMIT 10
    `).all(project.id);

    const beadStats = db.prepare(`
      SELECT status, COUNT(*) as count FROM beads WHERE project_id = ? GROUP BY status
    `).all(project.id);

    res.json({
      id: project.id,
      name: project.name,
      githubRepo: project.github_repo,
      aiProvider: project.ai_provider,
      aiModel: project.ai_model,
      owner: { id: project.user_id, name: project.owner_name, email: project.owner_email },
      members,
      recentJobs,
      beadStats,
      createdAt: utc(project.created_at),
      updatedAt: utc(project.updated_at),
    });
  } catch (error) {
    console.error('[Admin] Error fetching project:', error);
    res.status(500).json({ error: 'Failed to fetch project' });
  }
});

// ─── System ──────────────────────────────────────────────────────────────────

// GET /api/admin/system/health
router.get('/system/health', (req: Request, res: Response) => {
  try {
    const tables = ['users', 'projects', 'beads', 'agent_jobs', 'sessions', 'credentials', 'notifications', 'organizations'];
    const tableCounts: Record<string, number> = {};
    for (const table of tables) {
      try {
        tableCounts[table] = (db.prepare(`SELECT COUNT(*) as count FROM ${table}`).get() as any).count;
      } catch {
        tableCounts[table] = -1; // table doesn't exist
      }
    }

    const jobStats = jobQueue.getStats();
    const uptime = process.uptime();

    // DB file size
    const dbPath = process.env.DATABASE_URL || './data/devdash.db';
    let dbSizeBytes = 0;
    try {
      const stats = fs.statSync(dbPath);
      dbSizeBytes = stats.size;
    } catch {
      // Can't read file size
    }

    res.json({
      tableCounts,
      jobStats,
      uptime: Math.floor(uptime),
      dbSizeBytes,
      nodeVersion: process.version,
      memoryUsage: process.memoryUsage(),
    });
  } catch (error) {
    console.error('[Admin] Error fetching system health:', error);
    res.status(500).json({ error: 'Failed to fetch system health' });
  }
});

// POST /api/admin/system/recover-jobs
router.post('/system/recover-jobs', (req: Request, res: Response) => {
  try {
    const recovered = jobQueue.recoverOrphanedJobs();
    console.log(`[Admin] ${req.user!.email} triggered orphaned job recovery: ${recovered} jobs`);
    res.json({ success: true, recovered });
  } catch (error) {
    console.error('[Admin] Error recovering jobs:', error);
    res.status(500).json({ error: 'Failed to recover jobs' });
  }
});

// ─── Legacy operations (migrated from ADMIN_SECRET endpoints) ────────────────

// DELETE /api/admin/clear-beads/:projectId
router.delete('/clear-beads/:projectId', (req: Request, res: Response) => {
  try {
    const { projectId } = req.params;
    beadOps.deleteByProjectId.run(projectId);
    githubSyncOps.deleteByProjectId.run(projectId);
    beadSyncStateOps.delete.run(projectId);
    console.log(`[Admin] ${req.user!.email} cleared beads for project ${projectId}`);
    res.json({ success: true, message: `Cleared all beads for project ${projectId}` });
  } catch (error) {
    console.error('[Admin] Error clearing beads:', error);
    res.status(500).json({ error: 'Failed to clear beads' });
  }
});

// POST /api/admin/reset-user/:userId
router.post('/reset-user/:userId', (req: Request, res: Response) => {
  try {
    const { userId } = req.params;
    const user = userOps.findById.get(userId) as any;
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    const counts: Record<string, number> = {};
    const projects = (db.prepare('SELECT id FROM projects WHERE user_id = ?').all(userId) as any[]);
    const projectIds = projects.map(p => p.id);

    for (const pid of projectIds) {
      counts.agent_jobs = (counts.agent_jobs || 0) + (db.prepare('DELETE FROM agent_jobs WHERE project_id = ?').run(pid)).changes;
      counts.agent_sessions = (counts.agent_sessions || 0) + (db.prepare('DELETE FROM agent_sessions WHERE project_id = ?').run(pid)).changes;
      counts.agents = (counts.agents || 0) + (db.prepare('DELETE FROM agents WHERE project_id = ?').run(pid)).changes;
      counts.worktree_runs = (counts.worktree_runs || 0) + (db.prepare('DELETE FROM worktree_runs WHERE project_id = ?').run(pid)).changes;
      counts.plan_items = (counts.plan_items || 0) + (db.prepare('DELETE FROM plan_items WHERE project_id = ?').run(pid)).changes;
      counts.beads = (counts.beads || 0) + (beadOps.deleteByProjectId.run(pid)).changes;
      counts.bead_sync_state = (counts.bead_sync_state || 0) + (beadSyncStateOps.delete.run(pid)).changes;
      counts.github_issue_sync = (counts.github_issue_sync || 0) + (githubSyncOps.deleteByProjectId.run(pid)).changes;
      counts.project_memory = (counts.project_memory || 0) + (projectMemoryOps.deleteByProjectId.run(pid)).changes;
      counts.drains = (counts.drains || 0) + (db.prepare('DELETE FROM drains WHERE project_id = ?').run(pid)).changes;
      counts.project_members = (counts.project_members || 0) + (projectMemberOps.removeAllByProject.run(pid)).changes;
      counts.project_invitations = (counts.project_invitations || 0) + (projectInvitationOps.deleteByProjectId.run(pid)).changes;
    }

    counts.projects = (db.prepare('DELETE FROM projects WHERE user_id = ?').run(userId)).changes;
    counts.settings = (db.prepare('DELETE FROM settings WHERE user_id = ?').run(userId)).changes;
    counts.notifications = (db.prepare('DELETE FROM notifications WHERE user_id = ?').run(userId)).changes;
    counts.global_memory = (db.prepare('DELETE FROM global_memory WHERE user_id = ?').run(userId)).changes;
    counts.credentials = (db.prepare('DELETE FROM credentials WHERE user_id = ?').run(userId)).changes;
    counts.api_tokens = (db.prepare('DELETE FROM api_tokens WHERE user_id = ?').run(userId)).changes;

    const installations = (installationOps.findByUserId.all(userId) as any[]);
    for (const inst of installations) {
      counts.github_installation_repos = (counts.github_installation_repos || 0) +
        (installationRepoOps.deleteByInstallation.run(inst.installation_id)).changes;
    }
    counts.github_installations = (db.prepare('DELETE FROM github_installations WHERE user_id = ?').run(userId)).changes;
    counts.sessions = (db.prepare('DELETE FROM sessions WHERE user_id = ?').run(userId)).changes;

    userOps.updateOnboardingCompleted.run(0, userId);

    console.log(`[Admin] ${req.user!.email} reset user ${userId} (${user.email}): ${JSON.stringify(counts)}`);
    res.json({
      success: true,
      user: { id: userId, email: user.email, display_name: user.display_name },
      deleted: counts,
      projectsReset: projectIds.length,
    });
  } catch (error) {
    console.error(`[Admin] Error resetting user:`, error);
    res.status(500).json({ error: 'Failed to reset user' });
  }
});

// ─── Auth Events ──────────────────────────────────────────────────────────────

// GET /api/admin/auth-events?limit=50&cursor=...&email=...&event_type=...
router.get('/auth-events', validate({ query: AdminAuthEventsQuery }), (req: Request, res: Response) => {
  try {
    const { limit, cursor, email, event_type: eventType } = req.query as unknown as AdminAuthEventsQuery;

    // Parse cursor: "created_at|id"
    let cursorCreatedAt: string | undefined;
    let cursorId: string | undefined;
    if (cursor) {
      const parts = cursor.split('|');
      if (parts.length === 2) {
        cursorCreatedAt = parts[0];
        cursorId = parts[1];
      }
    }

    const fetchLimit = limit + 1; // fetch one extra to detect hasMore
    let events: any[];

    if (email && eventType) {
      const pattern = `%${email}%`;
      events = cursorCreatedAt
        ? authEventOps.findFilteredAfterCursor.all(pattern, eventType, cursorCreatedAt, cursorCreatedAt, cursorId, fetchLimit)
        : authEventOps.findFiltered.all(pattern, eventType, fetchLimit);
    } else if (email) {
      const pattern = `%${email}%`;
      events = cursorCreatedAt
        ? authEventOps.findByEmailAfterCursor.all(pattern, cursorCreatedAt, cursorCreatedAt, cursorId, fetchLimit)
        : authEventOps.findByEmail.all(pattern, fetchLimit);
    } else if (eventType) {
      events = cursorCreatedAt
        ? authEventOps.findByEventTypeAfterCursor.all(eventType, cursorCreatedAt, cursorCreatedAt, cursorId, fetchLimit)
        : authEventOps.findByEventType.all(eventType, fetchLimit);
    } else {
      events = cursorCreatedAt
        ? authEventOps.findRecentAfterCursor.all(cursorCreatedAt, cursorCreatedAt, cursorId, fetchLimit)
        : authEventOps.findRecent.all(fetchLimit);
    }

    const hasMore = events.length > limit;
    if (hasMore) events = events.slice(0, limit);

    const nextCursor = hasMore && events.length > 0
      ? `${events[events.length - 1].created_at}|${events[events.length - 1].id}`
      : null;

    // Stats
    const typeCounts = authEventOps.countByType.all() as { event_type: string; count: number }[];
    const stats: Record<string, number> = {};
    for (const row of typeCounts) {
      stats[row.event_type] = row.count;
    }
    stats.last_7_days = (authEventOps.countLast7Days.get() as any).count;

    // Map to camelCase
    const mapped = events.map((e: any) => ({
      id: e.id,
      userId: e.user_id,
      email: e.email,
      eventType: e.event_type,
      authMethod: e.auth_method,
      ipAddress: e.ip_address,
      userAgent: e.user_agent,
      metadata: e.metadata ? JSON.parse(e.metadata) : null,
      createdAt: utc(e.created_at),
      displayName: e.display_name || null,
      avatarUrl: e.avatar_url || null,
    }));

    res.json({ events: mapped, stats, nextCursor, hasMore });
  } catch (error) {
    console.error('[Admin] Error listing auth events:', error);
    res.status(500).json({ error: 'Failed to list auth events' });
  }
});

export default router;

