import React from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '../common/Card';
import { Button } from '../common/Button';
import { useSystemHealth, useRecoverJobs } from '../../hooks/useAdmin';
import { RefreshCw, Database, Server, Clock, HardDrive } from 'lucide-react';

function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${(bytes / Math.pow(k, i)).toFixed(1)} ${sizes[i]}`;
}

function formatUptime(seconds: number): string {
  const days = Math.floor(seconds / 86400);
  const hours = Math.floor((seconds % 86400) / 3600);
  const mins = Math.floor((seconds % 3600) / 60);
  if (days > 0) return `${days}d ${hours}h ${mins}m`;
  if (hours > 0) return `${hours}h ${mins}m`;
  return `${mins}m`;
}

export function AdminSystem() {
  const { data: health, isLoading } = useSystemHealth();
  const recoverJobs = useRecoverJobs();

  if (isLoading) {
    return <div className="text-theme-muted text-center py-8">Loading system health...</div>;
  }

  if (!health) {
    return <div className="text-theme-muted text-center py-8">Failed to load system health</div>;
  }

  return (
    <div className="space-y-4">
      {/* Stats grid */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <StatCard
          icon={<Clock className="w-4 h-4" />}
          label="Uptime"
          value={formatUptime(health.uptime)}
        />
        <StatCard
          icon={<Database className="w-4 h-4" />}
          label="DB Size"
          value={formatBytes(health.dbSizeBytes)}
        />
        <StatCard
          icon={<Server className="w-4 h-4" />}
          label="Heap Used"
          value={formatBytes(health.memoryUsage.heapUsed)}
        />
        <StatCard
          icon={<HardDrive className="w-4 h-4" />}
          label="RSS"
          value={formatBytes(health.memoryUsage.rss)}
        />
      </div>

      {/* Table counts */}
      <Card>
        <CardHeader>
          <CardTitle>Table Row Counts</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {Object.entries(health.tableCounts).map(([table, count]) => (
              <div key={table} className="flex justify-between items-center px-3 py-2 bg-theme-surface rounded-lg">
                <span className="text-sm text-theme-muted">{table}</span>
                <span className="text-sm font-medium text-theme-text">
                  {count >= 0 ? count.toLocaleString() : 'N/A'}
                </span>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Job queue */}
      <Card>
        <CardHeader>
          <CardTitle>Job Queue</CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="grid grid-cols-3 md:grid-cols-6 gap-3">
            {Object.entries(health.jobStats).map(([status, count]) => (
              <div key={status} className="text-center px-3 py-2 bg-theme-surface rounded-lg">
                <div className="text-lg font-bold text-theme-text">{count}</div>
                <div className="text-xs text-theme-muted capitalize">{status.replace('_', ' ')}</div>
              </div>
            ))}
          </div>

          <div className="flex items-center justify-between pt-2 border-t border-theme-border">
            <span className="text-sm text-theme-muted">
              Recover orphaned jobs (stuck in "running" after server restart)
            </span>
            <Button
              variant="secondary"
              onClick={() => recoverJobs.mutate()}
              isLoading={recoverJobs.isPending}
              leftIcon={<RefreshCw className="w-3.5 h-3.5" />}
            >
              Recover
            </Button>
          </div>

          {recoverJobs.isSuccess && recoverJobs.data && (
            <div className="text-sm text-brand-accent">
              Recovered {recoverJobs.data.recovered} orphaned job(s)
            </div>
          )}
        </CardContent>
      </Card>

      {/* Server info */}
      <Card>
        <CardHeader>
          <CardTitle>Server Info</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 gap-3 text-sm">
            <div>
              <span className="text-theme-muted">Node.js:</span>{' '}
              <span className="text-theme-text">{health.nodeVersion}</span>
            </div>
            <div>
              <span className="text-theme-muted">Heap Total:</span>{' '}
