import { pgTable, text, integer, boolean, timestamp, uniqueIndex, index, primaryKey } from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';

// Helper: default timestamp columns
const createdAt = () => timestamp('created_at').defaultNow().notNull();
const updatedAt = () => timestamp('updated_at').defaultNow().notNull();
const optionalCreatedAt = () => timestamp('created_at').defaultNow();
const optionalUpdatedAt = () => timestamp('updated_at').defaultNow();

// =============================================================================
// Users
// =============================================================================
export const users = pgTable('users', {
  id: text('id').primaryKey(),
  username: text('username').notNull(),
  displayName: text('display_name').notNull(),
  avatarUrl: text('avatar_url'),
  email: text('email'),
  accessToken: text('access_token'),
  googleId: text('google_id').unique(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
  lastLoginAt: timestamp('last_login_at'),
  lastInteractionAt: timestamp('last_interaction_at'),
  onboardingCompleted: boolean('onboarding_completed').notNull().default(false),
  systemRole: text('system_role'),
  ssoProvider: text('sso_provider'),
  ssoExternalId: text('sso_external_id'),
  primaryOrgId: text('primary_org_id'),
}, (t) => [
  index('idx_users_email').on(t.email),
]);

// =============================================================================
// Sessions
// =============================================================================
export const sessions = pgTable('sessions', {
  id: text('id').primaryKey(),
  userId: text('user_id').notNull().references(() => users.id),
  expiresAt: timestamp('expires_at').notNull(),
  createdAt: optionalCreatedAt(),
});

// =============================================================================
// Projects
// =============================================================================
export const projects = pgTable('projects', {
  id: text('id').primaryKey(),
  userId: text('user_id').notNull().references(() => users.id),
  name: text('name').notNull(),
  path: text('path').notNull(),
  githubRepo: text('github_repo'),
  description: text('description'),
  aiProvider: text('ai_provider').default('claude'),
  aiModel: text('ai_model').default('claude-sonnet-4-20250514'),
  mergeStrategy: text('merge_strategy').notNull().default('pr'),
  lastAccessedAt: timestamp('last_accessed_at'),
  initStatus: text('init_status'),
  initResult: text('init_result'),
  githubSyncEnabled: boolean('github_sync_enabled').default(false),
  accessLevel: text('access_level').default('full'),
  installationId: integer('installation_id'),
  orgId: text('org_id'),
  autoDispatchReady: boolean('auto_dispatch_ready').default(false),
  autoDispatchMinAutomability: integer('auto_dispatch_min_automability').default(60),
  autoDispatchMaxConcurrent: integer('auto_dispatch_max_concurrent').default(1),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  index('idx_projects_org').on(t.orgId),
]);

// =============================================================================
// Agents (legacy)
// =============================================================================
export const agents = pgTable('agents', {
  id: text('id').primaryKey(),
  projectId: text('project_id').notNull().references(() => projects.id),
  prompt: text('prompt').notNull(),
  status: text('status').default('idle'),
  startedAt: timestamp('started_at'),
  completedAt: timestamp('completed_at'),
  error: text('error'),
  createdAt: optionalCreatedAt(),
});

// =============================================================================
// Settings (per-user key-value, encrypted API keys)
// =============================================================================
export const settings = pgTable('settings', {
  userId: text('user_id').notNull().references(() => users.id),
  key: text('key').notNull(),
  value: text('value').notNull(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  primaryKey({ columns: [t.userId, t.key] }),
]);

// =============================================================================
// Orchestration Plans
// =============================================================================
export const orchestrationPlans = pgTable('orchestration_plans', {
  id: text('id').primaryKey(),
  userId: text('user_id').notNull().references(() => users.id),
  name: text('name').notNull(),
  description: text('description'),
  status: text('status').default('draft'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

// =============================================================================
// Plan Items
// =============================================================================
export const planItems = pgTable('plan_items', {
  id: text('id').primaryKey(),
  planId: text('plan_id').notNull().references(() => orchestrationPlans.id),
  projectId: text('project_id').notNull().references(() => projects.id),
  beadId: text('bead_id'),
  githubIssueNumber: integer('github_issue_number'),
  sequenceOrder: integer('sequence_order'),
  status: text('status').default('pending'),
  notes: text('notes'),
});

// =============================================================================
// Project Memory
// =============================================================================
export const projectMemory = pgTable('project_memory', {
  id: text('id').primaryKey(),
  projectId: text('project_id').notNull().references(() => projects.id),
  key: text('key').notNull(),
  content: text('content').notNull(),
  updatedBy: text('updated_by'),
  updatedAt: optionalUpdatedAt(),
}, (t) => [
  uniqueIndex('uq_project_memory_project_key').on(t.projectId, t.key),
]);

// =============================================================================
// Global Memory
// =============================================================================
export const globalMemory = pgTable('global_memory', {
  id: text('id').primaryKey(),
  userId: text('user_id').notNull().references(() => users.id),
  key: text('key').notNull(),
  content: text('content').notNull(),
  updatedAt: optionalUpdatedAt(),
}, (t) => [
  uniqueIndex('uq_global_memory_user_key').on(t.userId, t.key),
]);

// =============================================================================
// GitHub Issue Sync
// =============================================================================
export const githubIssueSync = pgTable('github_issue_sync', {
  id: text('id').primaryKey(),
  projectId: text('project_id').notNull().references(() => projects.id),
  githubIssueNumber: integer('github_issue_number').notNull(),
  beadId: text('bead_id'),
  syncStatus: text('sync_status').default('synced'),
  lastSyncedAt: timestamp('last_synced_at'),
}, (t) => [
  uniqueIndex('uq_github_sync_project_issue').on(t.projectId, t.githubIssueNumber),
]);

// =============================================================================
// Agent Sessions
// =============================================================================
export const agentSessions = pgTable('agent_sessions', {
  id: text('id').primaryKey(),
  projectId: text('project_id').references(() => projects.id),
  summary: text('summary'),
  contextUsed: text('context_used'),
  createdAt: optionalCreatedAt(),
});

// =============================================================================
// Agent Jobs
// =============================================================================
export const agentJobs = pgTable('agent_jobs', {
  id: text('id').primaryKey(),
  projectId: text('project_id').notNull().references(() => projects.id),
  beadId: text('bead_id'),
  prompt: text('prompt').notNull(),
  status: text('status').default('queued'),
  workerType: text('worker_type').default('docker'),
  workerId: text('worker_id'),
  priority: integer('priority').default(2),
  startedAt: timestamp('started_at'),
  completedAt: timestamp('completed_at'),
  error: text('error'),
  outputLog: text('output_log'),
  result: text('result'),
  retryOf: text('retry_of'),
  drainId: text('drain_id'),
  worktreeRunId: text('worktree_run_id'),
  jobType: text('job_type').default('execution'),
  maxTokens: integer('max_tokens'),
  maxTurns: integer('max_turns'),
  dispatchedBy: text('dispatched_by'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  index('idx_agent_jobs_status').on(t.status),
  index('idx_agent_jobs_project').on(t.projectId),
  index('idx_agent_jobs_project_created').on(t.projectId, t.createdAt, t.id),
  index('idx_agent_jobs_drain').on(t.drainId),
  index('idx_agent_jobs_worktree').on(t.worktreeRunId),
]);

// =============================================================================
// Credentials (encrypted service tokens)
// =============================================================================
export const credentials = pgTable('credentials', {
  id: text('id').primaryKey(),
  userId: text('user_id').notNull().references(() => users.id),
  service: text('service').notNull(),
  credentialType: text('credential_type').notNull(),
  encryptedValue: text('encrypted_value').notNull(),
  createdAt: createdAt(),
  expiresAt: timestamp('expires_at'),
}, (t) => [
  uniqueIndex('uq_credentials_user_service').on(t.userId, t.service),
]);

// =============================================================================
// Notifications
// =============================================================================
export const notifications = pgTable('notifications', {
  id: text('id').primaryKey(),
  userId: text('user_id').notNull().references(() => users.id),
  type: text('type').notNull(),
  title: text('title').notNull(),
  message: text('message'),
  read: boolean('read').default(false),
  metadata: text('metadata'),
  orgId: text('org_id'),
  projectId: text('project_id'),
  mentionType: text('mention_type'),
  createdAt: optionalCreatedAt(),
}, (t) => [
  index('idx_notifications_user').on(t.userId, t.read),
]);

// =============================================================================
// Beads (dashboard-managed project tasks)
// =============================================================================
export const beads = pgTable('beads', {
  id: text('id').primaryKey(),
  projectId: text('project_id').notNull().references(() => projects.id),
  subject: text('subject').notNull(),
  description: text('description'),
  status: text('status').default('pending'),
  priority: integer('priority').default(2),
  owner: text('owner'),
  blockedBy: text('blocked_by'),
  blocks: text('blocks'),
  githubIssueNumber: integer('github_issue_number'),
  githubIssueUrl: text('github_issue_url'),
  githubIssueId: integer('github_issue_id'),
  localBeadId: text('local_bead_id'),
  localSyncedAt: timestamp('local_synced_at'),
  parentBeadId: text('parent_bead_id'),
  beadType: text('bead_type').default('task'),
  preInstructions: text('pre_instructions'),
  analysisResult: text('analysis_result'),
  assignedTo: text('assigned_to'),
  completionResult: text('completion_result'),
  decomposedAt: timestamp('decomposed_at'),
  complexityScore: integer('complexity_score'),
  automabilityScore: integer('automability_score'),
  automabilityGrade: text('automability_grade'),
  burnScores: text('burn_scores'),
  burnScoredAt: timestamp('burn_scored_at'),
  escalated: boolean('escalated').default(false),
