#!/usr/bin/env npx tsx
/**
 * Extract delta rows from a fresh prod SQLite DB compared to a previously
 * migrated snapshot. Outputs a new SQLite DB containing only new/modified rows.
 *
 * Run the output through: migrate-sqlite-to-postgres.ts --upsert
 *
 * Usage:
 *   npx tsx scripts/extract-delta.ts \
 *     --fresh ~/downloads/devdash-fresh.db \
 *     --snapshot ~/playground/artifact_dump/devdash.db \
 *     --output /tmp/devdash-delta.db
 *
 * Logic per table:
 *   - Tables with updated_at: rows where updated_at > max(updated_at) in snapshot
 *   - Tables with only created_at: rows where created_at > max(created_at) in snapshot
 *   - Tables with neither: full diff by primary key (rows in fresh but not snapshot, or different)
 */

import Database from 'better-sqlite3';
import fs from 'fs';

function getArg(name: string): string | undefined {
  const idx = process.argv.indexOf(`--${name}`);
  return idx >= 0 ? process.argv[idx + 1] : undefined;
}

const freshPath = getArg('fresh');
const snapshotPath = getArg('snapshot');
const outputPath = getArg('output') || '/tmp/devdash-delta.db';

if (!freshPath || !snapshotPath) {
  console.error('Usage: npx tsx scripts/extract-delta.ts --fresh <path> --snapshot <path> [--output <path>]');
  process.exit(1);
}

const fresh = new Database(freshPath, { readonly: true });
const snapshot = new Database(snapshotPath, { readonly: true });

// Remove existing output
if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath);
const output = new Database(outputPath);

// Tables and their timestamp columns for delta detection
// 'updated_at' preferred over 'created_at' (catches modifications)
const TABLE_CONFIG: Record<string, { timestampCol?: string; pkCols: string[] }> = {
  users: { timestampCol: 'updated_at', pkCols: ['id'] },
  sessions: { timestampCol: 'created_at', pkCols: ['id'] },
  projects: { timestampCol: 'updated_at', pkCols: ['id'] },
  agents: { timestampCol: 'created_at', pkCols: ['id'] },
  settings: { timestampCol: 'updated_at', pkCols: ['user_id', 'key'] },
  orchestration_plans: { timestampCol: 'updated_at', pkCols: ['id'] },
  plan_items: { pkCols: ['id'] },  // no timestamp
  project_memory: { timestampCol: 'updated_at', pkCols: ['id'] },
  global_memory: { timestampCol: 'updated_at', pkCols: ['id'] },
  github_issue_sync: { timestampCol: 'last_synced_at', pkCols: ['id'] },
  agent_sessions: { timestampCol: 'created_at', pkCols: ['id'] },
  agent_jobs: { timestampCol: 'updated_at', pkCols: ['id'] },
  credentials: { timestampCol: 'created_at', pkCols: ['id'] },
  notifications: { timestampCol: 'created_at', pkCols: ['id'] },
  beads: { timestampCol: 'updated_at', pkCols: ['id'] },
  bead_comments: { timestampCol: 'updated_at', pkCols: ['id'] },
  project_members: { timestampCol: 'added_at', pkCols: ['project_id', 'user_id'] },
  project_invitations: { timestampCol: 'created_at', pkCols: ['id'] },
  bead_sync_state: { pkCols: ['project_id'] },  // no timestamp
  activity_log: { timestampCol: 'created_at', pkCols: ['id'] },
  drains: { timestampCol: 'started_at', pkCols: ['id'] },
  worktree_runs: { timestampCol: 'created_at', pkCols: ['id'] },
  github_installations: { timestampCol: 'updated_at', pkCols: ['installation_id'] },
  github_installation_repos: { pkCols: ['installation_id', 'repo_id'] },  // no timestamp
  project_agent_config: { timestampCol: 'updated_at', pkCols: ['project_id'] },
  api_tokens: { timestampCol: 'created_at', pkCols: ['id'] },
  organizations: { timestampCol: 'updated_at', pkCols: ['id'] },
  organization_members: { timestampCol: 'joined_at', pkCols: ['org_id', 'user_id'] },
  organization_invitations: { timestampCol: 'created_at', pkCols: ['id'] },
  teams: { timestampCol: 'created_at', pkCols: ['id'] },
  team_members: { timestampCol: 'added_at', pkCols: ['team_id', 'user_id'] },
  team_projects: { timestampCol: 'added_at', pkCols: ['team_id', 'project_id'] },
  sso_identity_links: { timestampCol: 'linked_at', pkCols: ['id'] },
  org_audit_log: { timestampCol: 'created_at', pkCols: ['id'] },
  auth_events: { timestampCol: 'created_at', pkCols: ['id'] },
  readiness_outcomes: { timestampCol: 'created_at', pkCols: ['id'] },
};

let totalDelta = 0;

console.log('=== Delta Extraction ===\n');
console.log(`Fresh:    ${freshPath}`);
console.log(`Snapshot: ${snapshotPath}`);
console.log(`Output:   ${outputPath}\n`);

for (const [table, config] of Object.entries(TABLE_CONFIG)) {
  try {
    // Check table exists in fresh
    const freshCount = fresh.prepare(`SELECT COUNT(*) as c FROM ${table}`).get() as any;
    if (freshCount.c === 0) {
      console.log(`  ⏭️  ${table}: empty`);
      continue;
    }

    // Copy table schema to output
    const createSQL = fresh.prepare(
      `SELECT sql FROM sqlite_master WHERE type='table' AND name=?`
    ).get(table) as any;
    if (!createSQL?.sql) {
      console.log(`  ⏭️  ${table}: no schema found`);
      continue;
    }
    output.exec(createSQL.sql.replace('CREATE TABLE', 'CREATE TABLE IF NOT EXISTS'));

    let deltaRows: any[];

    if (config.timestampCol) {
      // Get max timestamp from snapshot
      let maxTs: string | null = null;
      try {
        const result = snapshot.prepare(
          `SELECT MAX(${config.timestampCol}) as max_ts FROM ${table}`
        ).get() as any;
        maxTs = result?.max_ts || null;
      } catch {
        // Table might not exist in snapshot
      }

      if (maxTs) {
        // Get rows newer than the snapshot's max timestamp
        deltaRows = fresh.prepare(
          `SELECT * FROM ${table} WHERE ${config.timestampCol} > ?`
        ).all(maxTs);
      } else {
        // No snapshot data — take everything
        deltaRows = fresh.prepare(`SELECT * FROM ${table}`).all();
      }
    } else {
      // No timestamp column — diff by primary key
      // Get all PKs from snapshot
      const pkWhere = config.pkCols.map(c => `f.${c} = s.${c}`).join(' AND ');
      try {
        // Rows in fresh that don't exist in snapshot
        const snapshotPKs = new Set(
          snapshot.prepare(`SELECT ${config.pkCols.join(' || "|||" || ')} as pk FROM ${table}`).all()
            .map((r: any) => r.pk)
        );
        deltaRows = fresh.prepare(`SELECT * FROM ${table}`).all()
          .filter((row: any) => {
            const pk = config.pkCols.map(c => row[c]).join('|||');
            return !snapshotPKs.has(pk);
          });
      } catch {
        // Snapshot table doesn't exist — take everything
        deltaRows = fresh.prepare(`SELECT * FROM ${table}`).all();
      }
    }

    if (deltaRows.length === 0) {
      console.log(`  ✅ ${table}: 0 delta rows`);
      continue;
    }

    // Insert delta rows into output
    const columns = Object.keys(deltaRows[0]);
    const placeholders = columns.map(() => '?').join(', ');
    const insertStmt = output.prepare(
      `INSERT OR REPLACE INTO ${table} (${columns.join(', ')}) VALUES (${placeholders})`
    );

    for (const row of deltaRows) {
      insertStmt.run(...columns.map(c => row[c]));
    }

    totalDelta += deltaRows.length;
    console.log(`  📦 ${table}: ${deltaRows.length} delta rows`);
  } catch (e: any) {
    console.error(`  ❌ ${table}: ${e.message}`);
  }
}

console.log(`\n=== Total: ${totalDelta} delta rows → ${outputPath} ===`);
console.log(`\nNext: POSTGRES_URL="..." SQLITE_PATH="${outputPath}" npx tsx scripts/migrate-sqlite-to-postgres.ts --upsert`);

fresh.close();
snapshot.close();
output.close();

