        // Rows in fresh that don't exist in snapshot
        const snapshotPKs = new Set(
          snapshot.prepare(`SELECT ${config.pkCols.join(' || "|||" || ')} as pk FROM ${table}`).all()
            .map((r: any) => r.pk)
        );
        deltaRows = fresh.prepare(`SELECT * FROM ${table}`).all()
          .filter((row: any) => {
            const pk = config.pkCols.map(c => row[c]).join('|||');
            return !snapshotPKs.has(pk);
          });
      } catch {
        // Snapshot table doesn't exist — take everything
        deltaRows = fresh.prepare(`SELECT * FROM ${table}`).all();
      }
    }

    if (deltaRows.length === 0) {
      console.log(`  ✅ ${table}: 0 delta rows`);
      continue;
    }

    // Insert delta rows into output
    const columns = Object.keys(deltaRows[0]);
    const placeholders = columns.map(() => '?').join(', ');
    const insertStmt = output.prepare(
      `INSERT OR REPLACE INTO ${table} (${columns.join(', ')}) VALUES (${placeholders})`
    );

    for (const row of deltaRows) {
      insertStmt.run(...columns.map(c => row[c]));
    }

    totalDelta += deltaRows.length;
    console.log(`  📦 ${table}: ${deltaRows.length} delta rows`);
  } catch (e: any) {
    console.error(`  ❌ ${table}: ${e.message}`);
  }
}

console.log(`\n=== Total: ${totalDelta} delta rows → ${outputPath} ===`);
console.log(`\nNext: POSTGRES_URL="..." SQLITE_PATH="${outputPath}" npx tsx scripts/migrate-sqlite-to-postgres.ts --upsert`);

fresh.close();
snapshot.close();
output.close();

