import React, { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react';
import type { User } from '../types';
import { api, setAuthToken, clearAuthToken, getAuthToken } from '../services/api';

interface AuthContextType {
  user: User | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  isSystemAdmin: boolean;
  onboardingCompleted: boolean;
  login: () => void;
  logout: () => Promise<void>;
  checkAuth: () => Promise<void>;
  completeOnboarding: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const tokenExchangePromise = useRef<Promise<void> | null>(null);

  // Check for auth_code in URL (exchanged for token after OAuth redirect)
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const authCode = params.get('auth_code');
    if (authCode) {
      console.log('[Auth] Found auth_code in URL, exchanging for token');
      // Clean URL immediately to prevent code reuse
      window.history.replaceState({}, '', window.location.pathname);
      // Exchange the code for a token — store the promise so checkAuth can await it
      tokenExchangePromise.current = api.post<{ token: string }>('/auth/exchange-code', { code: authCode })
        .then((response) => {
          if (response.success && response.data?.token) {
            setAuthToken(response.data.token);
            console.log('[Auth] Token exchanged successfully');
          } else {
            console.warn('[Auth] Auth code exchange failed:', response.error);
          }
        })
        .catch((err) => {
          console.warn('[Auth] Auth code exchange error:', err);
        });
    }

    // Legacy: handle old auth_token param (for in-flight sessions during deploy)
    const authToken = params.get('auth_token');
    if (authToken) {
      console.log('[Auth] Found legacy auth_token in URL, storing for fallback');
      setAuthToken(authToken);
      window.history.replaceState({}, '', window.location.pathname);
    }
  }, []);

  const checkAuth = useCallback(async () => {
    // Wait for any in-flight token exchange to complete before checking auth
    if (tokenExchangePromise.current) {
      await tokenExchangePromise.current;
      tokenExchangePromise.current = null;
    }
    try {
      const response = await api.get<User>('/auth/me');
      if (response.success && response.data) {
        setUser(response.data);
      } else {
        setUser(null);
        clearAuthToken(); // Clear stale token if auth failed
      }
    } catch {
      setUser(null);
      clearAuthToken();
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    // Small delay to let the auth_code useEffect set up the exchange promise
    const timer = setTimeout(checkAuth, 50);
    return () => clearTimeout(timer);
  }, [checkAuth]);

  const login = () => {
    const apiUrl = import.meta.env.VITE_API_URL;
    if (!apiUrl) {
      console.error('[Auth] VITE_API_URL is not set! Login will fail.');
      console.error('[Auth] Set VITE_API_URL in your environment to the backend URL');
      // In production without VITE_API_URL, we can't login
      alert('Configuration error: API URL not set. Please contact support.');
      return;
    }
    console.log('[Auth] Redirecting to:', `${apiUrl}/api/auth/google`);
    window.location.href = `${apiUrl}/api/auth/google`;
  };

  const logout = async () => {
    try {
      await api.post('/auth/logout');
    } catch (error) {
      console.error('Logout error:', error);
    } finally {
      // Always clear local state and token, even if API call fails
      setUser(null);
      clearAuthToken();
      console.log('[Auth] Logged out');
    }
  };

  const completeOnboarding = async () => {
    await api.post('/auth/onboarding-complete');
    await checkAuth();
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        isLoading,
        isAuthenticated: !!user,
        isSystemAdmin: user?.systemRole === 'admin',
        onboardingCompleted: !!user?.onboardingCompleted,
        login,
        logout,
        checkAuth,
        completeOnboarding,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

