// Staleness threshold in minutes — beads in_progress with no activity beyond this are "stale"
const STALE_THRESHOLD_MINUTES = 30;

/**
 * Compute staleness info for an in_progress bead.
 * Returns { staleSince, staleMinutes } if stale, or { staleSince: null, staleMinutes: null }.
 */
async function computeStaleness(beadId: string, beadUpdatedAt: string): Promise<{ staleSince: string | null; staleMinutes: number | null }> {
  const candidates = [beadUpdatedAt];

  const [jobRow] = await pgDb.select({ latest: sql<string>`MAX(updated_at)` }).from(s.agentJobs).where(eq(s.agentJobs.beadId, beadId));
  if (jobRow?.latest) candidates.push(String(jobRow.latest));

  const [commentRow] = await pgDb.select({ latest: sql<string>`MAX(created_at)` }).from(s.beadComments).where(eq(s.beadComments.beadId, beadId));
  if (commentRow?.latest) candidates.push(String(commentRow.latest));

  const latestActivity = candidates.reduce((a, b) => (a > b ? a : b));
  const latestMs = new Date(latestActivity + 'Z').getTime();
  const elapsedMinutes = (Date.now() - latestMs) / 60000;

