import { Router, Request, Response } from 'express';
import { requireAuth, requireSystemAdmin } from '../middleware/auth.js';
import { validate } from '../middleware/validate.js';
import { AdminListQuery, UpdateUserRoleBody, AdminAuthEventsQuery } from '../schemas/index.js';
import { userOps, beadOps, githubSyncOps, beadSyncStateOps, projectMemoryOps, projectMemberOps, projectInvitationOps, installationOps, installationRepoOps, authEventOps } from '../db/ops.js';
import { pgDb } from '../db/postgres.js';
import { sql, eq, like, desc, count } from 'drizzle-orm';
import * as s from '../db/schema.js';
import { jobQueue } from '../services/job-queue.js';
import { utc } from '../utils/timestamps.js';

const router = Router();

// All admin routes require auth + system admin
router.use(requireAuth, requireSystemAdmin);

// ─── Users ───────────────────────────────────────────────────────────────────

// GET /api/admin/users?search=&limit=&offset=
router.get('/users', validate({ query: AdminListQuery }), async (req: Request, res: Response) => {
  try {
    const { search = '', limit, offset } = req.query as unknown as AdminListQuery;

    let users: any[];
    let total: number;

    if (search) {
      const pattern = `%${search}%`;
      users = await userOps.findAllFiltered(pattern, pattern, pattern, limit, offset);
      total = (await userOps.countFiltered(pattern, pattern, pattern) as any).count;
    } else {
      users = await pgDb.select({
        id: s.users.id, username: s.users.username, displayName: s.users.displayName,
        avatarUrl: s.users.avatarUrl, email: s.users.email, systemRole: s.users.systemRole,
        onboardingCompleted: s.users.onboardingCompleted, createdAt: s.users.createdAt, updatedAt: s.users.updatedAt,
        lastLoginAt: s.users.lastLoginAt, lastInteractionAt: s.users.lastInteractionAt,
      }).from(s.users).orderBy(desc(s.users.createdAt)).limit(limit).offset(offset);
      total = (await userOps.countAll() as any).count;
    }

    // Enrich with project counts
    const enriched = [];
    for (const u of users) {
      const [{ projectCount }] = await pgDb.select({ projectCount: count() }).from(s.projects).where(eq(s.projects.userId, u.id));
      enriched.push({
        id: u.id,
        username: u.username,
        displayName: u.displayName,
        avatarUrl: u.avatarUrl,
        email: u.email,
        systemRole: u.systemRole || null,
        onboardingCompleted: !!u.onboardingCompleted,
        projectCount,
        createdAt: utc(u.createdAt),
        updatedAt: utc(u.updatedAt),
        lastLoginAt: utc(u.lastLoginAt),
        lastInteractionAt: utc(u.lastInteractionAt),
      });
    }

    res.json({ users: enriched, total, limit, offset });
  } catch (error) {
    console.error('[Admin] Error listing users:', error);
    res.status(500).json({ error: 'Failed to list users' });
  }
});

// GET /api/admin/users/:userId
router.get('/users/:userId', async (req: Request, res: Response) => {
  try {
    const user = await userOps.findById(req.params.userId as string) as any;
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
