// PATCH /api/admin/users/:userId/role
router.patch('/users/:userId/role', validate({ body: UpdateUserRoleBody }), async (req: Request, res: Response) => {
  try {
    const userId = req.params.userId as string;
    const { role } = req.body as UpdateUserRoleBody;

    // Prevent self-demotion
    if (userId === req.user!.id && role !== 'admin') {
      return res.status(400).json({ error: 'Cannot demote yourself' });
    }

    // Prevent last-admin demotion
    if (role !== 'admin') {
      const adminCount = (await userOps.countAdmins() as any).count;
      const targetUser = await userOps.findById(userId) as any;
      if (targetUser?.systemRole === 'admin' && adminCount <= 1) {
        return res.status(400).json({ error: 'Cannot demote the last admin' });
      }
    }

    const user = await userOps.findById(userId) as any;
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    await userOps.updateSystemRole(role, userId);
    console.log(`[Admin] ${req.user!.email} changed role of ${user.email} to ${role || 'none'}`);

    res.json({ success: true, userId, role });
  } catch (error) {
    console.error('[Admin] Error updating user role:', error);
    res.status(500).json({ error: 'Failed to update user role' });
  }
});

