// =============================================================================
// Credential encryption migration helper
// =============================================================================
export async function migrateCredentialEncryption(): Promise<void> {
  try {
    const rows = await pgDb.select().from(s.credentials);
    let migrated = 0;
    for (const row of rows) {
      if (!row.encryptedValue) continue;
      if (isEncrypted(row.encryptedValue)) continue;
      const encrypted = encryptValue(row.encryptedValue);
      await pgDb.update(s.credentials).set({ encryptedValue: encrypted }).where(eq(s.credentials.id, row.id));
      migrated++;
    }
    if (migrated > 0) {
      console.log(`[DB] Migrated ${migrated} credential(s) to encrypted storage`);
    }
  } catch (err) {
    console.warn('[DB] Credential encryption migration skipped:', (err as Error).message);
  }
}

// =============================================================================
// Database initialization (push schema + run startup tasks)
// =============================================================================
export async function initializeDatabase(): Promise<void> {
  // Reset stale 'running' init status on server startup (handles crashes)
  await pgDb.execute(sql`UPDATE projects SET init_status = 'pending' WHERE init_status = 'running'`);

  // Bootstrap admin users from env var
  const bootstrapEmails = process.env.ADMIN_BOOTSTRAP_EMAILS;
  if (bootstrapEmails) {
    const emails = bootstrapEmails.split(',').map(e => e.trim()).filter(Boolean);
    for (const email of emails) {
      const result = await pgDb.execute(
        sql`UPDATE users SET system_role = 'admin' WHERE email = ${email} AND (system_role IS NULL OR system_role != 'admin')`
      );
      if ((result as any).rowCount > 0) {
        console.log(`[Admin Bootstrap] Promoted ${email} to admin`);
      }
    }
  }

  console.log('Database initialized (Postgres)');
}

