/**
 * Ensure a SQLite datetime string is a valid ISO 8601 UTC timestamp.
 * SQLite's datetime('now') returns "YYYY-MM-DD HH:MM:SS" without a timezone
 * indicator. JavaScript's `new Date()` treats such strings as local time,
 * causing the frontend to display the wrong time. Appending 'Z' marks them
 * as UTC so they parse correctly in any timezone.
 */
export function utc(ts: string): string;
export function utc(ts: string | null | undefined): string | null;
export function utc(ts: string | null | undefined): string | null {
  if (!ts) return null;
  return ts.endsWith('Z') ? ts : ts + 'Z';
}

