/**
 * Ensure a timestamp is a valid ISO 8601 UTC string.
 *
 * Handles both:
 * - SQLite datetime strings ("YYYY-MM-DD HH:MM:SS") — appends 'Z'
 * - Postgres Date objects from Drizzle — calls toISOString()
 */
export function utc(ts: string | Date): string;
export function utc(ts: string | Date | null | undefined): string | null;
export function utc(ts: string | Date | null | undefined): string | null {
  if (!ts) return null;
  if (ts instanceof Date) return ts.toISOString();
  return ts.endsWith('Z') ? ts : ts + 'Z';
}

