import { v4 as uuidv4 } from 'uuid';
import { agentJobOps, beadOps, notificationOps, projectOps } from '../db/ops.js';
import { pgDb } from '../db/postgres.js';
import { sql } from 'drizzle-orm';
import { projectEvents } from './project-events.js';
import { transitionStatus } from './bead-lifecycle.js';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed' | 'cancelled';
export type WorkerType = 'docker' | 'e2b' | 'railway';

export type JobType = 'execution' | 'analysis' | 'audit';

export interface AgentJob {
  id: string;
  projectId: string;
  beadId?: string | null;
  prompt: string;
  status: JobStatus;
  workerType: WorkerType;
  workerId?: string | null;
  priority: number;
  retryOf?: string | null;
  worktreeRunId?: string | null;
  dispatchedBy?: string | null;
  jobType: JobType;
  maxTokens?: number | null;
  maxTurns?: number | null;
  startedAt?: Date | null;
  completedAt?: Date | null;
  error?: string | null;
  outputLog?: string | null;
  result?: string | null;
  createdAt: Date;
  updatedAt: Date;
}

export interface CreateJobInput {
  projectId: string;
  beadId?: string;
  prompt: string;
  workerType?: WorkerType;
  priority?: number;
  retryOf?: string;
  worktreeRunId?: string;
  drainId?: string;
  dispatchedBy?: string;
  status?: JobStatus;
  jobType?: JobType;
  maxTokens?: number;
  maxTurns?: number;
  /** Skip the active-job duplicate check (e.g. for tracking/analysis jobs) */
  skipDuplicateCheck?: boolean;
}

export class DuplicateJobError extends Error {
  existingJobId: string;
  constructor(beadId: string, existingJobId: string) {
    super(`Bead ${beadId} already has an active job (${existingJobId})`);
    this.name = 'DuplicateJobError';
    this.existingJobId = existingJobId;
  }
}

export interface FailureArtifacts {
  uncommittedDiff?: string;
  uncommittedDiffBytes?: number;
  diffTruncated?: boolean;
  rescueBranch?: string;
  rescueCommitSha?: string;
  changedFiles?: string[];
  failureAnalysis?: import('./failure-analysis.js').FailureAnalysis;
  collectedAt?: string;
  collectorsRan?: string[];
  collectorErrors?: Record<string, string>;
}

export interface JobResult {
  prUrl?: string;
  commitSha?: string;
  branchName?: string;
  mergeStrategy?: 'pr' | 'direct';
  summary?: string;
  testResults?: {
    ran: boolean;
    passed: boolean;
    summary: string;
  };
  filesChanged?: number;
  integrationTestSuggested?: boolean;
  integrationTestReason?: string;
  totalTurns: number;
  totalTokens: number;
  durationMs: number;
  rescueBranch?: string;
  failureArtifacts?: FailureArtifacts;
  /** Paths the agent wrote to (structured, no log scraping needed) */
  filesWritten?: string[];
  /** Paths the agent read (structured, no log scraping needed) */
  filesRead?: string[];
}

// Configuration
const MAX_CONCURRENT_JOBS = parseInt(process.env.MAX_CONCURRENT_JOBS || '3', 10);

class JobQueue {
  private runningJobs: Map<string, AgentJob> = new Map();

  /**
   * Create a new job and add it to the queue
   */
  async createJob(input: CreateJobInput): Promise<AgentJob> {
    // Guard: prevent duplicate active jobs for the same bead
    if (input.beadId && !input.skipDuplicateCheck) {
      const existingJobs = await agentJobOps.findByBeadId(input.beadId) as AgentJob[];
      const activeJob = existingJobs.find(
        (j) => j.status === 'queued' || j.status === 'running'
      );
      if (activeJob) {
        throw new DuplicateJobError(input.beadId, activeJob.id);
      }
    }

    const id = uuidv4();
    const status: JobStatus = input.status || 'queued';
    const workerType = input.workerType || (process.env.E2B_API_KEY ? 'e2b' : 'docker');
    const priority = input.priority ?? 2; // Default priority (0 = highest, 4 = lowest)

    await agentJobOps.create(
      id,
      input.projectId,
      input.beadId || null,
      input.prompt,
      status,
      workerType,
      priority,
      input.retryOf || null,
      input.worktreeRunId || null,
      input.drainId || null,
      input.dispatchedBy || null,
      input.maxTokens || null,
      input.maxTurns || null,
      input.jobType || 'execution'
    );

    const createdJob = await agentJobOps.findById(id) as AgentJob;
    projectEvents.emit('change', { type: 'jobs:changed', projectId: input.projectId });
    return createdJob;
  }

  /**
   * Get a job by ID
   */
  async getJob(id: string): Promise<AgentJob | undefined> {
    return await agentJobOps.findById(id) as AgentJob | undefined;
  }

  /**
   * Get all jobs for a project
   */
  async getJobsByProject(projectId: string): Promise<AgentJob[]> {
    return await agentJobOps.findByProjectId(projectId) as AgentJob[];
  }

  /**
   * Get jobs by status
   */
  async getJobsByStatus(status: JobStatus): Promise<AgentJob[]> {
    return await agentJobOps.findByStatus(status) as AgentJob[];
  }

  /**
   * Get the next job from the queue (respects priority and concurrency)
   */
  async getNextJob(): Promise<AgentJob | undefined> {
    // Check concurrency limit
    const runningJobs = await this.getJobsByStatus('running');
    if (runningJobs.length >= MAX_CONCURRENT_JOBS) {
      return undefined;
    }

    // Get the highest priority queued job
    const queuedJobs = await agentJobOps.findQueued('queued', 1) as AgentJob[];
    return queuedJobs[0];
  }

  /**
   * Start a job (transition from queued to running)
   */
  async startJob(id: string, workerId?: string): Promise<AgentJob | undefined> {
    const job = await this.getJob(id);
    if (!job || job.status !== 'queued') {
      return undefined;
    }

    const now = new Date().toISOString();
    await agentJobOps.updateStatus('running', now, null, null, id);

    if (workerId) {
      await agentJobOps.updateWorker(workerId, id);
    }

    const updatedJob = (await this.getJob(id))!;
    this.runningJobs.set(id, updatedJob);
    projectEvents.emit('change', { type: 'jobs:changed', projectId: updatedJob.projectId });
    return updatedJob;
  }

  /**
   * Complete a job successfully
   */
  async completeJob(id: string, result?: JobResult, outputLog?: string): Promise<AgentJob | undefined> {
    const job = await this.getJob(id);
    if (!job || job.status !== 'running') {
      return undefined;
    }

    const now = new Date().toISOString();
    await agentJobOps.updateStatus('completed', job.startedAt?.toISOString() ?? null, now, null, id);

    if (result || outputLog) {
      await agentJobOps.updateResult(
        result ? JSON.stringify(result) : null,
        outputLog || null,
        id
      );
    }

    this.runningJobs.delete(id);
    const completedJob = await this.getJob(id);
    if (completedJob) {
      projectEvents.emit('change', { type: 'jobs:changed', projectId: completedJob.projectId });
    }

    // Record readiness outcome for calibration (execution jobs only)
    if (job.jobType === 'execution' && job.beadId) {
      try {
        import('./readiness-evaluator.js').then(({ recordReadinessOutcome }) =>
          recordReadinessOutcome(id, job.projectId, job.beadId ?? undefined, 'success')
        );
      } catch { /* non-fatal */ }
    }

    return completedJob;
  }

  /**
   * Mark a job as failed
   */
  async failJob(id: string, error: string, outputLog?: string, result?: JobResult): Promise<AgentJob | undefined> {
    const job = await this.getJob(id);
    if (!job || job.status !== 'running') {
      return undefined;
    }

    const now = new Date().toISOString();
    await agentJobOps.updateStatus('failed', job.startedAt?.toISOString() ?? null, now, error, id);

    if (result || outputLog) {
      await agentJobOps.updateResult(
        result ? JSON.stringify(result) : null,
        outputLog || null,
        id
      );
    }

    this.runningJobs.delete(id);
    const failedJob = await this.getJob(id);
    if (failedJob) {
      projectEvents.emit('change', { type: 'jobs:changed', projectId: failedJob.projectId });
    }

    // Record readiness outcome for calibration (execution jobs only)
    if (job.jobType === 'execution' && job.beadId) {
      try {
        // Extract failure category from result if available
        const failureCategory = result?.failureArtifacts?.failureAnalysis?.category;
        import('./readiness-evaluator.js').then(({ recordReadinessOutcome }) =>
          recordReadinessOutcome(id, job.projectId, job.beadId ?? undefined, 'failure', failureCategory)
        );
      } catch { /* non-fatal */ }
    }

    return failedJob;
  }

  /**
   * Cancel a job (can cancel queued or running jobs)
   */
  async cancelJob(id: string): Promise<AgentJob | undefined> {
    const job = await this.getJob(id);
    if (!job || (job.status !== 'queued' && job.status !== 'running')) {
      return undefined;
    }

    const now = new Date().toISOString();
    await agentJobOps.updateStatus('cancelled', job.startedAt?.toISOString() ?? null, now, 'Cancelled by user', id);

    this.runningJobs.delete(id);
    return await this.getJob(id);
  }

  /**
   * Get queue statistics
   */
  async getStats(): Promise<{
    queued: number;
    running: number;
    completed: number;
    failed: number;
    cancelled: number;
  }> {
    return {
      queued: (await this.getJobsByStatus('queued')).length,
      running: (await this.getJobsByStatus('running')).length,
      completed: (await this.getJobsByStatus('completed')).length,
      failed: (await this.getJobsByStatus('failed')).length,
      cancelled: (await this.getJobsByStatus('cancelled')).length,
    };
  }

  /**
   * Get queue statistics scoped to a set of project IDs
   */
  async getStatsByProjects(projectIds: string[]): Promise<{
    queued: number;
    running: number;
    completed: number;
    failed: number;
    cancelled: number;
  }> {
    if (projectIds.length === 0) {
      return { queued: 0, running: 0, completed: 0, failed: 0, cancelled: 0 };
    }
    const result = await pgDb.execute(sql`
      SELECT status, COUNT(*)::int as count FROM agent_jobs WHERE project_id = ANY(${projectIds}) GROUP BY status
    `) as any;
    const rows = result.rows as { status: string; count: number }[];

    const counts: Record<string, number> = {};
    for (const row of rows) {
      counts[row.status] = row.count;
    }
    return {
      queued: counts['queued'] || 0,
      running: counts['running'] || 0,
      completed: counts['completed'] || 0,
      failed: counts['failed'] || 0,
      cancelled: counts['cancelled'] || 0,
    };
  }

  /**
   * Get concurrency info scoped to a set of project IDs
   */
  async getConcurrencyInfoByProjects(projectIds: string[]): Promise<{ running: number; max: number; available: number }> {
    if (projectIds.length === 0) {
      return { running: 0, max: MAX_CONCURRENT_JOBS, available: MAX_CONCURRENT_JOBS };
    }
    const result = await pgDb.execute(sql`
      SELECT COUNT(*)::int as count FROM agent_jobs WHERE status = 'running' AND project_id = ANY(${projectIds})
    `) as any;
    const row = result.rows[0] as { count: number };
    const running = row.count;
    return {
      running,
      max: MAX_CONCURRENT_JOBS,
      available: MAX_CONCURRENT_JOBS - running,
    };
  }

  /**
   * Check if we can accept more jobs
   */
  async canAcceptJob(): Promise<boolean> {
    const runningJobs = await this.getJobsByStatus('running');
    return runningJobs.length < MAX_CONCURRENT_JOBS;
  }

  /**
   * Update the output log for a running job (periodic flush)
   */
  async updateOutputLog(id: string, log: string): Promise<void> {
    await agentJobOps.updateOutputLog(log, id);
  }

  /**
   * Recover orphaned jobs on startup.
   * After a server restart, any jobs marked "running" in the DB have no
   * corresponding sandbox or in-memory state — fail them cleanly.
   */
  async recoverOrphanedJobs(): Promise<number> {
    const orphaned = await this.getJobsByStatus('running');
    for (const job of orphaned) {
      const now = new Date().toISOString();
      const errorMsg = 'Job interrupted by server restart';
      await agentJobOps.updateStatus('failed', job.startedAt?.toISOString() ?? null, now, errorMsg, job.id);

      const project = await projectOps.findById(job.projectId) as any;

      // Create failure notification
      try {
        if (project) {
          const id = `notif-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
          await notificationOps.create(
            id,
            project.userId,
            'agent_failed',
            'Agent failed: interrupted by server restart',
            `Job ${job.id} was running when the server restarted. The E2B sandbox was lost. You can retry this job from the dashboard.`,
            JSON.stringify({ jobId: job.id, projectId: job.projectId, ...(job.beadId ? { beadId: job.beadId } : {}) }),
            null, null, null
          );
        }
      } catch (e) {
        console.warn('[JobQueue] Failed to create recovery notification:', e);
      }

      // Mark associated bead as failed (the job DID run before server crashed)
      if (job.beadId) {
        try {
          const bead = await beadOps.findById(job.beadId) as any;
          if (bead && bead.status === 'in_progress') {
            await transitionStatus(job.beadId, 'failed', {
              silent: true,
              projectId: job.projectId,
              userId: project?.userId,
            });
            console.log(`[JobQueue] Marked bead ${job.beadId} as failed (orphaned job)`);
          }
        } catch (e) {
          console.warn(`[JobQueue] Failed to mark bead ${job.beadId} as failed:`, e);
        }
      }

      console.log(`[JobQueue] Recovered orphaned job ${job.id} (was running)`);
    }
    if (orphaned.length > 0) {
      console.log(`[JobQueue] Recovered ${orphaned.length} orphaned job(s)`);
    }
    return orphaned.length;
  }

  /**
   * Recover orphaned beads on startup.
   * Beads stuck in 'in_progress' with no active job (manual claim, crashed sessions, etc.)
   */
  async recoverOrphanedBeads(): Promise<number> {
    const orphanedResult = await beadOps.findOrphanedInProgress() as any;
    const orphaned = orphanedResult.rows as any[];
    for (const bead of orphaned) {
      // Check if this bead has a past failed/cancelled job
      const pastJobs = await agentJobOps.findByBeadId(bead.id) as any[];
      const hadFailedJob = pastJobs.some(
        (j: any) => j.status === 'failed' || j.status === 'cancelled'
      );

      const newStatus = hadFailedJob ? 'failed' : 'pending';
      await transitionStatus(bead.id, newStatus, {
        silent: true,
        projectId: bead.projectId,
      });
      console.log(`[JobQueue] Recovered orphaned bead ${bead.id} → ${newStatus}`);
    }
    if (orphaned.length > 0) {
      console.log(`[JobQueue] Recovered ${orphaned.length} orphaned bead(s)`);
    }
    return orphaned.length;
  }

  /**
   * Get concurrency info
   */
  async getConcurrencyInfo(): Promise<{ running: number; max: number; available: number }> {
    const running = (await this.getJobsByStatus('running')).length;
    return {
      running,
      max: MAX_CONCURRENT_JOBS,
      available: MAX_CONCURRENT_JOBS - running,
    };
  }
}

// Export singleton instance
export const jobQueue = new JobQueue();

