/**
 * Bead Lifecycle — centralized status transitions with parent-child enforcement.
 *
 * All completion and deletion paths should go through this module so that:
 *  - A parent cannot complete while it has open children
 *  - Completing a bead cascades: unblocks dependents, auto-completes parent when all siblings done
 *  - Deleting a bead with open children is rejected (409)
 */

import { beadOps, beadCommentOps, projectOps } from '../db/ops.js';
import { pgDb } from '../db/postgres.js';
import { sql } from 'drizzle-orm';
import { syncOutbox } from './sync-outbox.js';
import { logActivity, type ActorType } from './activity-logger.js';

export interface StatusChangeResult {
  ok: boolean;
  error?: string;
  /** IDs of all beads whose status changed (including cascaded) */
  changed: string[];
}

export interface DeleteResult {
  ok: boolean;
  error?: string;
}

interface TransitionOpts {
  source?: string;
  /** Skip open-children guard (for external sync sources) */
  force?: boolean;
  projectId?: string;
  userId?: string;
  /** Suppress activity logging (for recovery/fallback paths) */
  silent?: boolean;
  /** Attribution for the activity log entry */
  actorType?: ActorType;
}

/**
 * Transition a bead's status. The moves to 'completed' and 'archived' have special rules:
 *  1. Guard: reject if bead has open children (unless force)
 *  2. For 'completed': cascade blocked_by removal + parent auto-complete
 *  3. For 'archived': guard only (no cascading to dependents)
 */
export async function transitionStatus(
  beadId: string,
  newStatus: string,
  opts: TransitionOpts = {}
): Promise<StatusChangeResult> {
  const bead = await beadOps.findById(beadId) as any;
  if (!bead) return { ok: false, error: 'Bead not found', changed: [] };

  const fromStatus = bead.status;

  // Helper: log a status change activity event
  function logStatusChange(id: string, from: string, to: string, subject: string, actor?: ActorType) {
    if (opts.silent || !opts.projectId) return;
    logActivity({
      projectId: opts.projectId!,
      actorId: opts.userId || undefined,
      actorType: actor || opts.actorType || (opts.userId ? 'user' : 'system'),
      action: 'bead.status_changed',
      targetType: 'bead',
      targetId: id,
      metadata: { fromStatus: from, toStatus: to, subject },
    });
  }

  // Non-completion and non-archived transitions are simple — just update
  if (newStatus !== 'completed' && newStatus !== 'archived') {
    await beadOps.updateStatus(newStatus, beadId);

    const changed: string[] = [beadId];

    // Enqueue sync event for simple transitions too
    let userId: string | undefined;
    if (opts.projectId) {
      userId = opts.userId || (await projectOps.findById(opts.projectId) as any)?.userId;
      if (userId) {
        syncOutbox.enqueue({
          type: 'bead:status_changed',
          beadId,
          projectId: opts.projectId,
          userId,
          enqueuedAt: Date.now(),
        });
      }
    }

    // Propagate in_progress to parent: if this child just became in_progress,
    // and the parent is in a pre-progress state, move parent to in_progress too
    if (newStatus === 'in_progress' && bead.parentBeadId) {
      const parent = await beadOps.findById(bead.parentBeadId) as any;
      if (parent && (parent.status === 'pending' || parent.status === 'ready')) {
        await beadOps.updateStatus('in_progress', parent.id);
        changed.push(parent.id);
        logStatusChange(parent.id, parent.status, 'in_progress', parent.subject, 'system');
        if (opts.projectId) {
          const parentProjectId = parent.projectId || opts.projectId;
          const pUserId: string | undefined = parentProjectId !== opts.projectId
            ? (await projectOps.findById(parentProjectId) as any)?.userId || userId
            : userId;
          if (pUserId) {
            syncOutbox.enqueue({
              type: 'bead:status_changed',
              beadId: parent.id,
              projectId: parentProjectId,
              userId: pUserId,
              enqueuedAt: Date.now(),
            });
          }
        }
      }
    }

    logStatusChange(beadId, fromStatus, newStatus, bead.subject);
    return { ok: true, changed };
  }

  // --- Completion path ---
  const changed: string[] = [];

  // 1. Guard: reject if open children exist
  if (!opts.force) {
    const children = await beadOps.findChildrenByParent(beadId) as any[];
    const openChildren = children.filter((c: any) => c.status !== 'completed' && c.status !== 'archived');
    if (openChildren.length > 0) {
      return {
        ok: false,
        error: `Cannot complete: ${openChildren.length} open child task(s)`,
        changed: [],
      };
    }
  }

  // 2. Complete this bead
  await beadOps.updateStatus('completed', beadId);
  changed.push(beadId);
  logStatusChange(beadId, fromStatus, 'completed', bead.subject);

  // 3. Cascade: unblock dependents via `blocks` array (batch fetch to avoid N+1)
  const blocksIds: string[] = bead.blocks ? JSON.parse(bead.blocks) : [];
  if (blocksIds.length > 0) {
    const deps = await pgDb.execute(sql`SELECT * FROM beads WHERE id IN (${sql.join(blocksIds.map(id => sql`${id}`), sql`, `)})`) as any;
    const depsRows = deps.rows as any[];

    for (const dep of depsRows) {
      if (dep.status !== 'blocked' && dep.status !== 'pending') continue;

      const depBlockedBy: string[] = dep.blockedBy ? JSON.parse(dep.blockedBy) : [];
      const remaining = depBlockedBy.filter((id: string) => id !== beadId);

      // Update blocked_by array
      await beadOps.updateBlockedBy(JSON.stringify(remaining), dep.id);

      // If no more blockers, transition blocked → pending
      if (remaining.length === 0 && dep.status === 'blocked') {
        await beadOps.updateStatus('pending', dep.id);
        changed.push(dep.id);
        logStatusChange(dep.id, 'blocked', 'pending', dep.subject, 'system');
      }
    }
  }

  // 4. Parent auto-complete: if all siblings are completed, complete the parent
  if (bead.parentBeadId) {
    const siblings = await beadOps.findChildrenByParent(bead.parentBeadId) as any[];
    const allDone = siblings.every((s: any) => s.id === beadId || s.status === 'completed' || s.status === 'archived');
