  // 2. Cascade delete children if requested
  if (opts.cascade && children.length > 0) {
    for (const child of children) {
      await deleteBead(child.id, { ...opts, cascade: true });
    }
  } else {
    // 3. Clear parent_bead_id on completed children (non-cascade)
    for (const child of children) {
      await beadOps.clearParentBeadId(child.id);
    }
  }

  // 4. Remove this ID from blocked_by arrays of beads it blocks (batch fetch)
  const delBlocksIds: string[] = bead.blocks ? JSON.parse(bead.blocks) : [];
  if (delBlocksIds.length > 0) {
    const depsResult = await pgDb.execute(sql`SELECT * FROM beads WHERE id IN (${sql.join(delBlocksIds.map(id => sql`${id}`), sql`, `)})`) as any;
    const deps = depsResult.rows as any[];
    for (const dep of deps) {
      const depBlockedBy: string[] = dep.blockedBy ? JSON.parse(dep.blockedBy) : [];
      const remaining = depBlockedBy.filter((id: string) => id !== beadId);
      await beadOps.updateBlockedBy(JSON.stringify(remaining), dep.id);
      if (remaining.length === 0 && dep.status === 'blocked') {
        await beadOps.updateStatus('pending', dep.id);
      }
    }
  }

  // 5. Remove this ID from blocks arrays of beads that block it (batch fetch)
  const blockedByIds: string[] = bead.blockedBy ? JSON.parse(bead.blockedBy) : [];
  if (blockedByIds.length > 0) {
    const blockersResult = await pgDb.execute(sql`SELECT * FROM beads WHERE id = ANY(${blockedByIds})`) as any;
    const blockers = blockersResult.rows as any[];
    for (const blocker of blockers) {
      const blockerBlocks: string[] = blocker.blocks ? JSON.parse(blocker.blocks) : [];
      const remaining = blockerBlocks.filter((id: string) => id !== beadId);
      await beadOps.updateBlocks(JSON.stringify(remaining), blocker.id);
    }
  }

  // 6. Clean up parent's blockedBy if this is a child bead
  if (bead.parentBeadId) {
    const parent = await beadOps.findById(bead.parentBeadId) as any;
    if (parent) {
      const parentBlockedBy: string[] = parent.blockedBy ? JSON.parse(parent.blockedBy) : [];
      const remaining = parentBlockedBy.filter((id: string) => id !== beadId);
      await beadOps.updateBlockedBy(JSON.stringify(remaining), parent.id);
      // If parent was blocked only by children and all children are now gone, unblock it
      if (remaining.length === 0 && parent.status === 'blocked') {
        await beadOps.updateStatus('pending', parent.id);
      }
    }
  }

  // 7. Delete related rows that have FK constraints
  await beadCommentOps.deleteByBeadId(beadId);

  // 8. Delete the bead
  await beadOps.delete(beadId);

  return { ok: true };
}

