import { v4 as uuidv4 } from 'uuid';
import { beadOps, worktreeRunOps, agentJobOps, projectOps } from '../db/ops.js';
import { pgDb } from '../db/postgres.js';
import { sql } from 'drizzle-orm';
import { jobQueue, type CreateJobInput } from './job-queue.js';
import { transitionStatus } from './bead-lifecycle.js';
import { resolveGitHubToken } from './github-app.js';

/**
 * Batch-fetch all agent jobs for a set of bead IDs in a single query.
 * Returns a Map keyed by bead_id for O(1) lookups.
 */
async function batchFetchJobsByBeadIds(beadIds: string[]): Promise<Map<string, any[]>> {
  const jobsByBead = new Map<string, any[]>();
  if (beadIds.length === 0) return jobsByBead;

  const result = await pgDb.execute(
    sql`SELECT * FROM agent_jobs WHERE bead_id = ANY(${beadIds}) ORDER BY created_at DESC`
  ) as any;
  const allJobs = result.rows as any[];

  for (const job of allJobs) {
    const list = jobsByBead.get(job.beadId);
    if (list) {
      list.push(job);
    } else {
      jobsByBead.set(job.beadId, [job]);
    }
  }
  return jobsByBead;
}

export type WorktreeRunStatus = 'running' | 'completed' | 'failed' | 'cancelled';

export interface WorktreeRun {
  id: string;
  projectId: string;
  parentBeadId: string;
  status: WorktreeRunStatus;
  workerType: string;
  priority: number;
  totalBeads: number;
  completedBeads: number;
  failedBeads: number;
  createdAt: Date;
  completedAt: Date | null;
  worktreeBranch?: string | null;
  prUrl?: string | null;
}

/**
 * Worktree Executor Service
 * Orchestrates auto-queuing of child beads in dependency order.
 * When a parent bead is decomposed into children with dependencies,
 * this service queues ready children and cascades as each completes.
 */
class WorktreeExecutor {
  /**
   * Start a worktree run: queue all ready children of a parent bead.
   */
  async startRun(
    projectId: string,
    parentBeadId: string,
    workerType?: string,
    priority?: number
  ): Promise<{ run: WorktreeRun; queuedJobIds: string[] }> {
    // Check for existing active run on this parent
    const existing = await worktreeRunOps.findByParentBead(parentBeadId) as WorktreeRun[];
    const active = existing.find((r) => r.status === 'running');
    if (active) {
      throw new DuplicateRunError(parentBeadId, active.id);
    }

    // Find children
    const children = await beadOps.findChildrenByParent(parentBeadId) as any[];
    if (children.length === 0) {
      throw new NoChildrenError(parentBeadId);
    }

    const wt = workerType || (process.env.E2B_API_KEY ? 'e2b' : 'docker');
    const prio = priority ?? 2;

    // Create run record with worktree branch name
    const runId = uuidv4();
    const worktreeBranch = `worktree/${parentBeadId.substring(0, 8)}`;
    await worktreeRunOps.create(runId, projectId, parentBeadId, 'running', wt, prio, children.length);
    await worktreeRunOps.updateBranch(worktreeBranch, runId);

    // Find ready children (pending + all blockers completed)
    const completedIds = new Set(
      children.filter((c: any) => c.status === 'completed').map((c: any) => c.id)
    );
    const readyChildren = children.filter((c: any) => {
      if (c.status !== 'pending') return false;
      const blockedBy: string[] = c.blockedBy ? JSON.parse(c.blockedBy) : [];
      return blockedBy.length === 0 || blockedBy.every((id: string) => completedIds.has(id));
    });

    // Batch-fetch all jobs for ready children in one query (avoids N+1)
    const jobsByBead = await batchFetchJobsByBeadIds(readyChildren.map((c: any) => c.id));

    // Queue jobs for ready children
    const queuedJobIds: string[] = [];
    for (const child of readyChildren) {
      try {
        const jobId = await this.queueChildJob(child, projectId, runId, wt, prio, jobsByBead.get(child.id) || []);
        queuedJobIds.push(jobId);
      } catch (err) {
        console.warn(`[WorktreeExecutor] Skipped duplicate job for child ${child.id}:`, (err as Error).message);
      }
    }

    // If nothing was queued (e.g. all children already completed), resolve immediately
    if (queuedJobIds.length === 0) {
      await this.checkRunCompletion(runId);
    }

    const run = await worktreeRunOps.findById(runId) as WorktreeRun;
    return { run, queuedJobIds };
  }

  /**
   * Called when a job completes successfully.
   * Resolves dependencies and queues newly unblocked children.
   */
  async onJobCompleted(jobId: string): Promise<void> {
    const job = await agentJobOps.findById(jobId) as any;
    if (!job?.worktreeRunId) return;

    const run = await worktreeRunOps.findById(job.worktreeRunId) as WorktreeRun | undefined;
    if (!run || run.status !== 'running') return;

    // Update completed counter
    const newCompleted = run.completedBeads + 1;
    await worktreeRunOps.updateCounters(newCompleted, run.failedBeads, run.id);

    // Delegate completion cascade to bead-lifecycle (unblocks dependents, auto-completes parent)
    if (job.beadId) {
      const project = await projectOps.findById(run.projectId) as any;
      transitionStatus(job.beadId, 'completed', {
        source: 'worktree-executor',
        projectId: run.projectId,
        userId: project?.userId,
      });
    }

    // After lifecycle cascade, check if any blocked siblings are now pending and queue them
    const children = await beadOps.findChildrenByParent(run.parentBeadId) as any[];
    const pendingChildren = children.filter((c: any) => c.status === 'pending');

    if (pendingChildren.length > 0) {
      // Batch-fetch all jobs for pending children in one query (avoids N+1)
      const jobsByBead = await batchFetchJobsByBeadIds(pendingChildren.map((c: any) => c.id));

      for (const child of pendingChildren) {
        const existingJobs = jobsByBead.get(child.id) || [];
        const alreadyQueued = existingJobs.some(
          (j: any) => j.worktreeRunId === run.id && (j.status === 'queued' || j.status === 'running')
        );
        if (!alreadyQueued) {
          try {
            await this.queueChildJob(child, run.projectId, run.id, run.workerType, run.priority, existingJobs);
          } catch (err) {
            console.warn(`[WorktreeExecutor] Skipped duplicate job for child ${child.id}:`, (err as Error).message);
          }
        }
      }
    }

    // Check if all children are done (completed or failed)
    await this.checkRunCompletion(run.id);
  }

  /**
   * Called when a job fails.
   * Increments failed counter for the failed bead AND all transitively
   * blocked dependents (they can never run since their blocker failed).
   */
  async onJobFailed(jobId: string): Promise<void> {
    const job = await agentJobOps.findById(jobId) as any;
    if (!job?.worktreeRunId) return;

    const run = await worktreeRunOps.findById(job.worktreeRunId) as WorktreeRun | undefined;
    if (!run || run.status !== 'running') return;

    // Mark the bead as failed so it doesn't appear as "ready" for re-dispatch
    if (job.beadId) {
      const project = await projectOps.findById(run.projectId) as any;
      transitionStatus(job.beadId, 'failed', {
        source: 'worktree-executor',
        projectId: run.projectId,
        userId: project?.userId,
      });
    }

    // Count transitively blocked dependents that will never run
    const skippedCount = job.beadId
      ? await this.countSkippedDependents(job.beadId, run.parentBeadId)
      : 0;

    const newFailed = run.failedBeads + 1 + skippedCount;
    await worktreeRunOps.updateCounters(run.completedBeads, newFailed, run.id);

    // Check if all processable work is done
    await this.checkRunCompletion(run.id);
  }

  /**
   * BFS from a failed bead to find all transitively blocked dependents.
   * A bead is skipped if any of its blockers (direct or transitive) failed.
   */
  private async countSkippedDependents(failedBeadId: string, parentBeadId: string): Promise<number> {
    const children = await beadOps.findChildrenByParent(parentBeadId) as any[];
    const skipped = new Set<string>();
    const queue = [failedBeadId];

    while (queue.length > 0) {
      const currentId = queue.shift()!;
      for (const child of children) {
        if (skipped.has(child.id) || child.id === failedBeadId) continue;
        const blockedBy: string[] = child.blockedBy ? JSON.parse(child.blockedBy) : [];
        if (blockedBy.includes(currentId)) {
          skipped.add(child.id);
          queue.push(child.id);
        }
      }
    }

    return skipped.size;
  }

  /**
   * Cancel an entire worktree run.
   * Cancels all queued/running jobs, reverts bead statuses.
   */
  async cancelRun(runId: string): Promise<boolean> {
    const run = await worktreeRunOps.findById(runId) as WorktreeRun | undefined;
    if (!run || run.status !== 'running') return false;

    // Find all jobs in this run
    const runJobs = await agentJobOps.findByWorktreeRun(runId) as any[];

    // Cancel each queued/running job
    for (const job of runJobs) {
      if (job.status === 'queued' || job.status === 'running') {
        // Use job-queue cancel (updates DB status)
        jobQueue.cancelJob(job.id);

        // Revert bead status
        if (job.beadId) {
          transitionStatus(job.beadId, 'pending', { silent: true, projectId: run.projectId });
        }
      }
    }

    // Mark run as cancelled
    await worktreeRunOps.updateStatus('cancelled', new Date().toISOString(), runId);
    return true;
  }

  /**
   * Retry a failed or cancelled worktree run.
   * Resets failed children to pending, cancels the old run, and starts a new one.
   */
  async retryRun(runId: string): Promise<{ run: WorktreeRun; queuedJobIds: string[] }> {
    const oldRun = await worktreeRunOps.findById(runId) as WorktreeRun | undefined;
    if (!oldRun) {
      throw new Error('Run not found');
    }
    if (oldRun.status !== 'failed' && oldRun.status !== 'cancelled') {
      throw new Error('Only failed or cancelled runs can be retried');
    }

    // Check if all children are already completed — no need to create a new run
    const children = await beadOps.findChildrenByParent(oldRun.parentBeadId) as any[];
    const allCompleted = children.every((c: any) => c.status === 'completed');
    if (allCompleted) {
      await worktreeRunOps.updateCounters(children.length, 0, runId);
      await worktreeRunOps.updateStatus('completed', new Date().toISOString(), runId);
      const run = await worktreeRunOps.findById(runId) as WorktreeRun;
      return { run, queuedJobIds: [] };
    }

    // Reset all failed children back to pending
    for (const child of children) {
      if (child.status === 'failed') {
        transitionStatus(child.id, 'pending', { silent: true, projectId: oldRun.projectId });
      }
    }

    // Mark the old run as cancelled so it no longer blocks startRun()
    if (oldRun.status !== 'cancelled') {
      await worktreeRunOps.updateStatus('cancelled', new Date().toISOString(), runId);
    }

    // Start a fresh run with the same parameters
    return this.startRun(oldRun.projectId, oldRun.parentBeadId, oldRun.workerType, oldRun.priority);
  }

  /**
   * Recover orphaned and stale runs on startup.
   * - 'running' runs with no active jobs get re-evaluated
   * - 'failed' runs whose children are all completed get corrected
   */
  async recoverOrphanedRuns(): Promise<number> {
    let recovered = 0;

    // 1. Orphaned running runs (no active jobs)
    const orphanedResult = await pgDb.execute(sql`SELECT * FROM worktree_runs WHERE status = 'running'`) as any;
    const orphaned = (orphanedResult.rows || []) as WorktreeRun[];
    for (const run of orphaned) {
      const runJobs = await agentJobOps.findByWorktreeRun(run.id) as any[];
      const activeJobs = runJobs.filter((j: any) => j.status === 'queued' || j.status === 'running');

      if (activeJobs.length === 0) {
        // Reset child beads stuck in_progress with no active job back to pending
        // so they can be re-queued on retry
        const children = await beadOps.findChildrenByParent(run.parentBeadId) as any[];
        const inProgressChildren = children.filter((c: any) => c.status === 'in_progress');

        if (inProgressChildren.length > 0) {
          // Batch-fetch all jobs for in-progress children in one query (avoids N+1)
          const jobsByBead = await batchFetchJobsByBeadIds(inProgressChildren.map((c: any) => c.id));

          for (const child of inProgressChildren) {
            const childJobs = jobsByBead.get(child.id) || [];
            const hasActiveJob = childJobs.some(
              (j: any) => j.status === 'queued' || j.status === 'running'
            );
            if (!hasActiveJob) {
              transitionStatus(child.id, 'pending', { silent: true, projectId: run.projectId });
              console.log(`[WorktreeExecutor] Reset orphaned child bead ${child.id} → pending`);
            }
          }
        }

        await this.checkRunCompletion(run.id);
      }
      recovered++;
    }

    // 2. Stale failed/cancelled runs whose children are actually all completed
    //    (caused by sticky counter bug or retry marking old run cancelled)
    const staleResult = await pgDb.execute(sql`SELECT * FROM worktree_runs WHERE status IN ('failed', 'cancelled')`) as any;
    const stale = (staleResult.rows || []) as WorktreeRun[];
    for (const run of stale) {
      const children = await beadOps.findChildrenByParent(run.parentBeadId) as any[];
      if (children.length === 0) continue;

      const allCompleted = children.every((c: any) => c.status === 'completed');
      if (allCompleted) {
        await worktreeRunOps.updateCounters(children.length, 0, run.id);
        await worktreeRunOps.updateStatus('completed', new Date().toISOString(), run.id);
        console.log(`[WorktreeExecutor] Fixed stale ${run.status} run ${run.id} — all children completed`);
        recovered++;
      }
    }

    if (recovered > 0) {
      console.log(`[WorktreeExecutor] Recovered ${recovered} worktree run(s)`);
    }
    return recovered;
  }

  /**
   * Get detailed run status with per-child states.
   */
  async getRunDetails(runId: string): Promise<{
    run: WorktreeRun;
    children: { id: string; subject: string; status: string; jobStatus?: string }[];
  } | null> {
    const run = await worktreeRunOps.findById(runId) as WorktreeRun | undefined;
    if (!run) return null;

    const children = await beadOps.findChildrenByParent(run.parentBeadId) as any[];
    const runJobs = await agentJobOps.findByWorktreeRun(runId) as any[];
    const jobByBead = new Map<string, any>();
    for (const j of runJobs) {
      if (j.beadId) jobByBead.set(j.beadId, j);
    }

    return {
      run,
      children: children.map((c: any) => ({
        id: c.id,
        subject: c.subject,
        status: c.status,
        jobStatus: jobByBead.get(c.id)?.status,
      })),
    };
  }

  /**
   * Queue a single child bead as an agent job.
   */
  private async queueChildJob(
    child: any,
    projectId: string,
    runId: string,
    workerType: string,
    priority: number,
    previousJobs?: any[]
  ): Promise<string> {
    // Keep prompt minimal — buildAgentContext will enrich from bead fields
    // (subject, description, pre_instructions) to avoid duplication
    const prompt = child.subject;

    // Link to the most recent failed job for this bead so retry context
    // (previous error, diff, rescue branch) gets injected by buildAgentContext
    // Use pre-fetched jobs if provided (batch query), otherwise fall back to individual query
    const jobs = previousJobs ?? await agentJobOps.findByBeadId(child.id) as any[];
    const lastFailed = jobs.find((j: any) => j.status === 'failed');

    const input: CreateJobInput = {
      projectId,
      beadId: child.id,
      prompt,
      workerType: workerType as any,
      priority,
      worktreeRunId: runId,
      retryOf: lastFailed?.id,
    };

    const job = await jobQueue.createJob(input);
    return job.id;
  }

  /**
   * Check if a worktree run is complete.
   * A run is complete when no queued/running jobs remain.
   */
  private async checkRunCompletion(runId: string): Promise<void> {
    const run = await worktreeRunOps.findById(runId) as WorktreeRun | undefined;
    if (!run || run.status !== 'running') return;

    const runJobs = await agentJobOps.findByWorktreeRun(runId) as any[];
    const activeJobs = runJobs.filter(
      (j: any) => j.status === 'queued' || j.status === 'running'
    );

    if (activeJobs.length > 0) return; // Still work in progress

    // Derive actual state from children's bead statuses (not sticky counters).
    // A bead that failed then succeeded on retry should count as completed.
    const children = await beadOps.findChildrenByParent(run.parentBeadId) as any[];
    const completedCount = children.filter((c: any) => c.status === 'completed').length;
    const failedCount = children.filter((c: any) => c.status === 'failed').length;

    // Sync counters to reflect reality
    await worktreeRunOps.updateCounters(completedCount, failedCount, runId);

    // Determine final status from actual bead states
    const allCompleted = completedCount >= children.length;
    const hasFailures = failedCount > 0;

    const finalStatus: WorktreeRunStatus = allCompleted ? 'completed' : hasFailures ? 'failed' : 'completed';
    await worktreeRunOps.updateStatus(finalStatus, new Date().toISOString(), runId);

    // Create consolidated PR on successful completion
    if (finalStatus === 'completed' && run.worktreeBranch) {
      this.createConsolidatedPR(run).catch((err) => {
        console.error(`[WorktreeExecutor] Failed to create consolidated PR for run ${runId}:`, err);
        // Still record the branch so the work isn't invisible from the bead
        beadOps.updateCompletionResult(
          JSON.stringify({ worktree_branch: run.worktreeBranch, pr_error: String(err) }),
          run.parentBeadId
        );
      });
    }

    // Parent auto-completion is handled by bead-lifecycle in onJobCompleted
  }

  /**
   * Create a single consolidated PR for a completed worktree run.
   * Uses the project owner's GitHub credentials.
   */
  private async createConsolidatedPR(run: WorktreeRun): Promise<void> {
    const project = await projectOps.findById(run.projectId) as any;
    if (!project?.githubRepo || !project?.userId) return;

    const resolved = await resolveGitHubToken(project.userId, project.githubRepo);
    if (!resolved) return;

    const parentBead = await beadOps.findById(run.parentBeadId) as any;
    const title = parentBead
      ? `[Worktree] ${parentBead.subject}`
      : `Worktree run ${run.id.substring(0, 8)}`;

    const children = await beadOps.findChildrenByParent(run.parentBeadId) as any[];

    // Build Closes #N lines for auto-close on merge
    const closesLines: string[] = [];
    if (parentBead?.githubIssueNumber) {
      closesLines.push(`Closes #${parentBead.githubIssueNumber}`);
    }
    for (const c of children) {
      if (c.githubIssueNumber) {
        closesLines.push(`Closes #${c.githubIssueNumber}`);
      }
    }

    const body = [
      ...closesLines,
      ...(closesLines.length > 0 ? [''] : []),
      `Consolidated PR for worktree run.`,
      '',
      `**Parent:** ${parentBead?.subject || run.parentBeadId}`,
      `**Children completed:** ${run.completedBeads}/${run.totalBeads}`,
      '',
      '## Changes',
      ...children.map((c: any) => `- ${c.subject} (${c.status})`),
      '',
      'Created by Dev-Dash Worktree Executor',
    ].join('\n');

    const [owner, repoName] = project.githubRepo.split('/');
    const response = await fetch(`https://api.github.com/repos/${owner}/${repoName}/pulls`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${resolved.token}`,
        Accept: 'application/vnd.github.v3+json',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        title,
        body,
        head: run.worktreeBranch,
        base: 'main',
      }),
    });

    if (!response.ok) {
      const err = await response.text();
      throw new Error(`GitHub API error ${response.status}: ${err}`);
    }

    const pr = await response.json() as { html_url: string };
    await worktreeRunOps.updatePrUrl(pr.html_url, run.id);
    await beadOps.updateCompletionResult(JSON.stringify({ pr_url: pr.html_url, worktree_branch: run.worktreeBranch }), run.parentBeadId);
    console.log(`[WorktreeExecutor] Consolidated PR created: ${pr.html_url}`);
  }
}

// Custom error types
export class DuplicateRunError extends Error {
  constructor(
    public parentBeadId: string,
    public existingRunId: string
  ) {
    super(`Active worktree run already exists for parent bead ${parentBeadId}`);
    this.name = 'DuplicateRunError';
  }
}

export class NoChildrenError extends Error {
  constructor(public parentBeadId: string) {
    super('Analyze and decompose this bead first.');
    this.name = 'NoChildrenError';
  }
}

// Export singleton instance
export const worktreeExecutor = new WorktreeExecutor();

