async function formatProject(p: any, role?: 'owner' | 'member' | 'viewer' | 'custom', permissions?: ProjectPermission[]) {
  // Attach repo analysis if available
  let analysis = null;
  const githubRepo = p.githubRepo;
  if (githubRepo) {
    const a = await repoAnalyzer.getAnalysisByRepo(githubRepo);
    if (a) {
      analysis = {
        summary: a.summary,
        techStack: a.techStack,
        projectType: a.projectType,
        complexity: a.complexity,
      };
    }
  }

  return {
    id: p.id,
    name: p.name,
    path: p.path,
    githubRepo: githubRepo,
    description: p.description,
    aiProvider: p.aiProvider,
    aiModel: p.aiModel,
    mergeStrategy: p.mergeStrategy ?? 'pr',
    initStatus: p.initStatus ?? null,
    initResult: p.initResult ? JSON.parse(p.initResult) : null,
    githubSyncEnabled: !!p.githubSyncEnabled,
    accessLevel: p.accessLevel ?? 'full',
    role: role || 'owner',
    permissions: permissions || [],
    autoDispatchReady: !!p.autoDispatchReady,
    autoDispatchMinAutomability: p.autoDispatchMinAutomability ?? 60,
    autoDispatchMaxConcurrent: p.autoDispatchMaxConcurrent ?? 1,
    analysis,
    createdAt: utc(p.createdAt),
    updatedAt: utc(p.updatedAt),
    lastAccessedAt: utc(p.lastAccessedAt),
  };
}

