import { Router } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { projectOps, beadOps, agentJobOps, githubSyncOps, beadSyncStateOps, projectMemberOps, projectInvitationOps, projectMemoryOps, userOps, agentConfigOps } from '../db/ops.js';
import { pgDb } from '../db/postgres.js';
import { sql } from 'drizzle-orm';
import * as s from '../db/schema.js';
import { requireAuth } from '../middleware/auth.js';
import { agentDispatcher } from '../services/agent-dispatch.js';
import { requireProjectAccess, requireProjectOwner, getProjectRole, getMemberPermissions, type ProjectPermission } from '../middleware/project-access.js';
import { logActivity } from '../services/activity-logger.js';
import { repoAnalyzer } from '../services/repo-analyzer.js';
import { AGENT_CATALOG, BUCKET_DEFAULTS, PROVIDER_BUCKET_DEFAULTS } from '../services/agent-catalog.js';
import { resolveModel } from '../services/model-resolver.js';
import { utc } from '../utils/timestamps.js';
import { githubService } from '../services/github.js';
import { TtlCache } from '../utils/ttl-cache.js';
import { validate } from '../middleware/validate.js';
import { CreateProjectBody, UpdateProjectBody, InviteMemberBody, UpdateMemberBody, UpdateAgentConfigBody } from '../schemas/index.js';

const router = Router();

// Short-lived cache for project lists (per-user, 5s TTL)
const projectListCache = new TtlCache<any[]>(5_000);

// All routes require authentication
router.use(requireAuth);

async function formatProject(p: any, role?: 'owner' | 'member' | 'viewer' | 'custom', permissions?: ProjectPermission[]) {
  // p may come from Drizzle (camelCase) or raw SQL via pgDb.execute (snake_case)
  // Use ?? fallbacks to handle both
  let analysis = null;
  const githubRepo = p.githubRepo ?? p.github_repo;
  if (githubRepo) {
    const a = await repoAnalyzer.getAnalysisByRepo(githubRepo);
    if (a) {
      analysis = {
        summary: a.summary,
        techStack: a.techStack,
        projectType: a.projectType,
        complexity: a.complexity,
      };
    }
  }

  const initResult = p.initResult ?? p.init_result;
  return {
    id: p.id,
    name: p.name,
    path: p.path,
    githubRepo,
    description: p.description,
    aiProvider: p.aiProvider ?? p.ai_provider,
    aiModel: p.aiModel ?? p.ai_model,
    mergeStrategy: p.mergeStrategy ?? p.merge_strategy ?? 'pr',
    initStatus: p.initStatus ?? p.init_status ?? null,
    initResult: initResult ? JSON.parse(initResult) : null,
    githubSyncEnabled: !!(p.githubSyncEnabled ?? p.github_sync_enabled),
    accessLevel: p.accessLevel ?? p.access_level ?? 'full',
    role: role || 'owner',
    permissions: permissions || [],
    autoDispatchReady: !!(p.autoDispatchReady ?? p.auto_dispatch_ready),
    autoDispatchMinAutomability: p.autoDispatchMinAutomability ?? p.auto_dispatch_min_automability ?? 60,
    autoDispatchMaxConcurrent: p.autoDispatchMaxConcurrent ?? p.auto_dispatch_max_concurrent ?? 1,
    analysis,
    createdAt: utc(p.createdAt ?? p.created_at),
    updatedAt: utc(p.updatedAt ?? p.updated_at),
    lastAccessedAt: utc(p.lastAccessedAt ?? p.last_accessed_at),
  };
}

// List all projects for user (owned + member) — single JOIN query, cached 5s
router.get('/', async (req, res) => {
  const userId = req.user!.id;

  const cached = projectListCache.get(userId);
  if (cached) return res.json(cached);

  const allPerms: ProjectPermission[] = ['manage_tasks', 'dispatch_agents', 'manage_memory'];
  const rawResult = await projectOps.findAccessibleByUserId(userId, userId) as any;
  const rows: any[] = rawResult.rows ?? rawResult;

  const result = await Promise.all(rows.map(async (row: any) => {
    const role = row._role;
    let perms: ProjectPermission[];
    if (role === 'owner') {
      // Owners always get all permissions
      perms = allPerms;
    } else if (row._permissions) {
      // Explicit custom permissions stored on the membership row take priority
      // (covers both role=custom and role=member with a restricted override)
      try { perms = JSON.parse(row._permissions); } catch { perms = []; }
    } else if (role === 'member') {
      // Standard member with no custom override → full set
      perms = allPerms;
    } else {
      // viewer or unknown role with no stored permissions
      perms = [];
    }
    return formatProject(row, role as any, perms);
  }));

  // Sort by lastAccessedAt descending (most recently viewed first)
  result.sort((a: any, b: any) => new Date(b.lastAccessedAt || 0).getTime() - new Date(a.lastAccessedAt || 0).getTime());

  projectListCache.set(userId, result);
  res.json(result);
});

// Get single project
router.get('/:id', async (req, res) => {
  const project = await requireProjectAccess(req.params.id, req.user!.id);
  if (!project) {
    return res.status(404).json({ error: 'Project not found' });
  }

  // Update last accessed timestamp
  await projectOps.updateLastAccessed(req.params.id);

  const role = await getProjectRole(req.params.id, req.user!.id);
  const permissions = await getMemberPermissions(req.params.id, req.user!.id);
  res.json(formatProject(project, role!, permissions));
});

// Create project
router.post('/', validate({ body: CreateProjectBody }), async (req, res) => {
  const { name, githubRepo, description, aiProvider, aiModel = 'claude-sonnet-4-20250514', mergeStrategy, githubSyncEnabled } = req.body as CreateProjectBody;
  const path = req.body.path || (githubRepo ? `https://github.com/${githubRepo}` : '');

  const id = uuidv4();

  try {
    await projectOps.create(
      id,
      req.user!.id,
      name,
      path,
      githubRepo || null,
      description || null,
      aiProvider,
      aiModel,
      mergeStrategy,
      githubSyncEnabled ? 1 : 0
    );

    await projectOps.updateLastAccessed(id);
    projectListCache.invalidate(req.user!.id);
    const project = await projectOps.findById(id) as any;
    res.status(201).json(formatProject(project));
  } catch (error) {
    console.error('Failed to create project:', error);
    res.status(500).json({ error: 'Failed to create project' });
  }
});

// Initialize project (import tasks + AI analysis)
router.post('/:id/initialize', async (req, res) => {
  const project = await requireProjectAccess(req.params.id, req.user!.id);
  if (!project) {
    return res.status(404).json({ error: 'Project not found' });
  }

  const skipReconcile = req.query.skipReconcile === 'true' || req.body?.skipReconcile === true;

  // Dynamic import (lazy load, same pattern as e2b in agent-dispatch)
  const { projectInitializer } = await import('../services/project-initializer.js');

  // Fire and forget
  projectInitializer.initialize(req.user!.id, req.params.id, { skipReconcile }).catch((err) => {
    console.error(`[initialize] Background init failed for ${req.params.id}:`, err);
  });

  res.json({ status: 'started' });
});

// Generate AI suggestions on-demand (works even when beads exist)
router.post('/:id/generate-suggestions', async (req, res) => {
  const project = await requireProjectAccess(req.params.id, req.user!.id);
  if (!project) {
    return res.status(404).json({ error: 'Project not found' });
  }

  if (!(project as any).githubRepo) {
    return res.status(400).json({ error: 'Project has no GitHub repository linked' });
  }

  try {
    const { projectInitializer } = await import('../services/project-initializer.js');
    const result = await projectInitializer.generateSuggestions(req.user!.id, req.params.id);
    res.json(result);
  } catch (error: any) {
    console.error('Failed to generate suggestions:', error);
    res.status(500).json({ error: error.message || 'Failed to generate suggestions' });
  }
});

// Update project (owner only)
router.patch('/:id', validate({ body: UpdateProjectBody }), async (req, res) => {
  const project = await requireProjectOwner(req.params.id as string, req.user!.id);
  if (!project) {
    return res.status(404).json({ error: 'Project not found' });
  }

  const { name, path, githubRepo, description, aiProvider, aiModel, mergeStrategy, githubSyncEnabled,
    autoDispatchReady, autoDispatchMinAutomability, autoDispatchMaxConcurrent } = req.body as UpdateProjectBody;

  try {
    await projectOps.update(
      name ?? project.name,
      path ?? project.path,
      githubRepo ?? project.githubRepo,
      description ?? project.description,
      aiProvider ?? project.aiProvider,
      aiModel ?? project.aiModel,
      mergeStrategy ?? project.mergeStrategy ?? 'pr',
      githubSyncEnabled !== undefined ? (githubSyncEnabled ? 1 : 0) : (project.githubSyncEnabled ?? 0),
      req.params.id as string
    );

    // Update auto-dispatch settings if provided
    if (autoDispatchReady !== undefined || autoDispatchMinAutomability !== undefined || autoDispatchMaxConcurrent !== undefined) {
      const sets: Record<string, any> = { updatedAt: new Date() };
      if (autoDispatchReady !== undefined) {
        sets.autoDispatchReady = !!autoDispatchReady;
      }
      if (autoDispatchMinAutomability !== undefined) {
        sets.autoDispatchMinAutomability = autoDispatchMinAutomability;
      }
      if (autoDispatchMaxConcurrent !== undefined) {
        sets.autoDispatchMaxConcurrent = autoDispatchMaxConcurrent;
      }
      await pgDb.update(s.projects).set(sets).where(sql`id = ${req.params.id}`);
    }

    projectListCache.invalidate(req.user!.id);
    const updated = await projectOps.findById(req.params.id as string) as any;
    res.json(formatProject(updated));
  } catch (error) {
    console.error('Failed to update project:', error);
    res.status(500).json({ error: 'Failed to update project' });
  }
});

// Check repo access status for a project
router.get('/:id/repo-status', async (req, res) => {
  const project = await requireProjectAccess(req.params.id, req.user!.id);
  if (!project) {
    return res.status(404).json({ error: 'Project not found' });
  }

  const githubRepo = (project as any).githubRepo;
  if (!githubRepo) {
    return res.json({ linked: false, message: 'No GitHub repository linked.' });
  }

  const [owner, repo] = githubRepo.split('/');
  if (!owner || !repo) {
    return res.json({ linked: true, accessible: false, reason: 'invalid_format', message: `Invalid repo format: ${githubRepo}` });
  }

  try {
    const result = await githubService.verifyRepoAccess(req.user!.id, owner, repo);
    res.json({ linked: true, ...result });
  } catch (error) {
    console.error('Error checking repo access:', error);
    res.json({ linked: true, accessible: false, reason: 'api_error', message: 'Failed to check repository access.' });
  }
});

// Delete project (owner only)
router.delete('/:id', async (req, res) => {
  const project = await requireProjectOwner(req.params.id, req.user!.id);
  if (!project) {
    return res.status(404).json({ error: 'Project not found' });
  }

  try {
    const pid = req.params.id;

    // Cancel any active jobs (kills sandboxes) before deleting records
    const allJobs = await agentJobOps.findByProjectId(pid) as any[];
    const activeJobs = allJobs.filter(j => j.status === 'queued' || j.status === 'running');
    let activeJobsCancelled = 0;
    for (const job of activeJobs) {
      try {
        await agentDispatcher.cancelJob(job.id);
        activeJobsCancelled++;
      } catch (e) {
        console.warn(`Failed to cancel job ${job.id} during project deletion:`, e);
      }
    }

    // Cascade delete all dependent records before removing the project
    await agentConfigOps.delete(pid);
    await beadSyncStateOps.delete(pid);
    await pgDb.execute(sql`DELETE FROM plan_items WHERE project_id = ${pid}`);
    await projectMemoryOps.deleteByProjectId(pid);
    await githubSyncOps.deleteByProjectId(pid);
    await pgDb.execute(sql`DELETE FROM drains WHERE project_id = ${pid}`);
    await pgDb.execute(sql`DELETE FROM worktree_runs WHERE project_id = ${pid}`);
    await pgDb.execute(sql`DELETE FROM agents WHERE project_id = ${pid}`);
    await pgDb.execute(sql`DELETE FROM agent_sessions WHERE project_id = ${pid}`);
    await pgDb.execute(sql`DELETE FROM agent_jobs WHERE project_id = ${pid}`);
    await pgDb.execute(sql`DELETE FROM bead_comments WHERE project_id = ${pid}`);
    await pgDb.execute(sql`DELETE FROM activity_log WHERE project_id = ${pid}`);
    await beadOps.deleteByProjectId(pid);
    await projectMemberOps.removeAllByProject(pid);
    await projectInvitationOps.deleteByProjectId(pid);
    await projectOps.delete(pid);
    projectListCache.invalidate(req.user!.id);
    res.json({ success: true, activeJobsCancelled });
  } catch (error) {
    console.error('Failed to delete project:', error);
    res.status(500).json({ error: 'Failed to delete project' });
  }
});

// Clear all beads and sync records for a project (owner only)
router.delete('/:id/beads', async (req, res) => {
  const project = await requireProjectOwner(req.params.id, req.user!.id);
  if (!project) {
    return res.status(404).json({ error: 'Project not found' });
  }

  try {
    await beadOps.deleteByProjectId(req.params.id);
    await githubSyncOps.deleteByProjectId(req.params.id);
    await beadSyncStateOps.delete(req.params.id);

    res.json({
      success: true,
      deleted: {
        beads: 0,
        syncRecords: 0,
      },
    });
  } catch (error) {
    console.error('Failed to clear beads:', error);
    res.status(500).json({ error: 'Failed to clear beads' });
  }
});

// ── Member management endpoints ────────────────────────────────

// List members + owner + pending invitations
router.get('/:id/members', async (req, res) => {
  const project = await requireProjectAccess(req.params.id, req.user!.id);
  if (!project) {
    return res.status(404).json({ error: 'Project not found' });
  }

  try {
    // Get owner info
    const owner = await userOps.findById(project.userId) as any;
    const members: any[] = [];

    if (owner) {
      members.push({
        userId: owner.id,
        username: owner.username,
        displayName: owner.displayName,
        avatarUrl: owner.avatarUrl,
        email: owner.email,
        role: 'owner',
        addedAt: utc(project.createdAt),
      });
    }

    // Get members with user details in single JOIN query
    const memberRows = await projectMemberOps.findByProjectIdWithUsers(req.params.id) as any[];
    for (const m of memberRows) {
      let perms: ProjectPermission[];
      const role = m.role || 'member';
      if (m.permissions) {
        // Explicit custom permissions stored on the membership row take priority
        // (covers both role=custom and role=member with a restricted override)
        try { perms = JSON.parse(m.permissions); } catch { perms = []; }
      } else if (role === 'member') {
        // Standard member with no custom override → full set
        perms = ['manage_tasks', 'dispatch_agents', 'manage_memory'];
      } else {
        // viewer or unknown role with no stored permissions
        perms = [];
      }
      members.push({
        userId: m.userId,
        username: m.username,
        displayName: m.displayName,
        avatarUrl: m.avatarUrl,
        email: m.email,
        role,
        permissions: perms,
        addedAt: utc(m.addedAt),
      });
    }

    // Get pending invitations
    const invitations = (await projectInvitationOps.findByProjectId(req.params.id) as any[]).map(inv => ({
      id: inv.id,
      email: inv.email,
      role: inv.role || 'member',
      invitedBy: inv.invitedBy,
      createdAt: utc(inv.createdAt),
    }));

    // Compact format for agent consumption
    if (req.query.format === 'compact') {
      const roster = members.map(m => ({
        id: m.userId,
        name: m.displayName,
        username: m.username,
        email: m.email,
        role: m.role,
      }));
      const pending = invitations.map(inv => inv.email);
      return res.json({ roster, pending });
    }

    res.json({ members, invitations });
  } catch (error) {
    console.error('Failed to list members:', error);
    res.status(500).json({ error: 'Failed to list members' });
  }
});

// Add member by email (owner only)
router.post('/:id/members', validate({ body: InviteMemberBody }), async (req, res) => {
  const projectId = req.params.id as string;
  const project = await requireProjectOwner(projectId, req.user!.id);
  if (!project) {
    return res.status(404).json({ error: 'Project not found' });
  }

  const { email, role: requestedRole, permissions: requestedPermissions } = req.body as InviteMemberBody;

  // Determine role and permissions
  let role: string = requestedRole;
  let permissions: string | null = null;

  if (requestedPermissions && requestedPermissions.length > 0) {
    permissions = JSON.stringify(requestedPermissions);
    role = 'custom';
  }

  try {
    // Check if user exists by email
    const existingUser = await userOps.findByEmail(email) as any;

    if (existingUser) {
      // Don't add the owner as a member
      if (existingUser.id === project.userId) {
        return res.status(400).json({ error: 'Cannot add the project owner as a member' });
      }
      // Add directly to project_members
      await projectMemberOps.add(projectId, existingUser.id, role, permissions);
      const perms = await getMemberPermissions(projectId, existingUser.id);

      logActivity({
        projectId,
        actorId: req.user!.id,
        actorType: 'user',
        action: 'member.added',
        targetType: 'member',
        targetId: existingUser.id,
        metadata: { email, role, displayName: existingUser.displayName },
      });

      res.status(201).json({
        type: 'member',
        userId: existingUser.id,
        username: existingUser.username,
        displayName: existingUser.displayName,
        email: existingUser.email,
        role,
        permissions: perms,
      });
    } else {
      // Create invitation
      const invId = uuidv4();
      await projectInvitationOps.create(invId, projectId, email, req.user!.id, role, permissions);
      res.status(201).json({
        type: 'invitation',
        id: invId,
        email,
        role,
      });
    }
  } catch (error) {
    console.error('Failed to add member:', error);
    res.status(500).json({ error: 'Failed to add member' });
  }
});

