const childrenByParent = new Map<string, Bead[]>();
for (const bead of deferredBeads) {
  if (bead.parentBeadId && parentIds.has(bead.parentBeadId)) {
    const list = childrenByParent.get(bead.parentBeadId) || [];
    list.push(bead);
    childrenByParent.set(bead.parentBeadId, list);
  }
}

// Build unified list: every bead that isn't a child becomes a top-level item
const items: TopLevelItem[] = [];
for (const bead of deferredBeads) {
  if (childIds.has(bead.id)) continue;
  const isParent = parentIds.has(bead.id);
  const children = isParent ? flattenDescendants(bead.id, childrenByParent) : [];
  const completedCount = children.filter((c) => c.bead.status === 'completed').length;

  // Derive effective parent status from children for immediate visual feedback
  let effectiveBead = bead;
  if (isParent && (bead.status === 'pending' || bead.status === 'ready')) {
    const anyChildInProgress = children.some((c) => c.bead.status === 'in_progress');
    if (anyChildInProgress) {
      effectiveBead = { ...bead, status: 'in_progress' as const };
    }
  }

  items.push({ bead: effectiveBead, isParent, children, completedCount });
}

