if (item.isParent) {
  const isExpanded = expandedParents.has(item.bead.id);
  const prio = priorityColors[item.bead.priority] || priorityColors[2];
  const typeStyle = typeColors[item.bead.beadType || ''] || 'text-theme-muted bg-theme-border';
  const hasRunningWorktree = activeRunByParent.has(item.bead.id);
  const allDone = item.completedCount === item.children.length && item.children.length > 0;
  const hasReadyChildren = item.children.some(child => {
    const blockedBy = child.bead.blockedBy || [];
    const allBlockersResolved = blockedBy.every(blockerId => {
      const blocker = beads.find(b => b.id === blockerId);
      return blocker?.status === 'completed';
    });
    return child.bead.status === 'pending' && allBlockersResolved;
  });
  const pct = item.children.length > 0
    ? Math.round((item.completedCount / item.children.length) * 100)
    : 0;

  return (
    <div
      key={item.bead.id}
      className={clsx(
        'rounded-lg border',
        hasRunningWorktree
          ? 'border-brand-primary/40 bg-brand-primary/5'
          : 'border-theme-border bg-theme-surface'
      )}
    >
      {/* Parent header */}
      <button
        onClick={() => toggleParent(item.bead.id)}
        className="w-full flex items-center gap-2 px-3 py-2.5 text-left"
      >
        {isExpanded
          ? <ChevronDown className="w-4 h-4 text-theme-muted flex-shrink-0" />
          : <ChevronRight className="w-4 h-4 text-theme-muted flex-shrink-0" />
        }
        {item.bead.beadType === 'thought' ? (
          <ThoughtBubble className="w-4 h-4 text-amber-400 flex-shrink-0" />
        ) : (
          <PrioritySelector
            priority={item.bead.priority}
            onPriorityChange={(p) => updateBead.mutate({ beadId: item.bead.id, projectId, priority: p })}
          />
        )}
        <GitBranch className="w-3.5 h-3.5 text-purple-400 flex-shrink-0" />
        {item.bead.beadType && item.bead.beadType !== 'thought' && (
          <span className={clsx('text-xs px-1.5 py-0.5 rounded', typeStyle)}>
            {item.bead.beadType}
          </span>
        )}
        <span
          className={clsx(
            'flex-1 text-sm font-medium truncate hover:text-brand-primary transition-colors',
            item.bead.status === 'completed' || allDone ? 'line-through text-theme-muted' : 'text-theme-text'
          )}
          onClick={(e) => { if (onTaskClick) { e.stopPropagation(); onTaskClick(item.bead); } }}
        >
          {item.bead.subject}
        </span>
        <span className="text-xs text-theme-muted flex-shrink-0">
          {item.completedCount}/{item.children.length}
        </span>
        <div className="w-16 bg-theme-border rounded-full h-1.5 overflow-hidden flex-shrink-0">
          <div
            className={clsx(
              'h-full rounded-full transition-all',
              allDone ? 'bg-green-500' : 'bg-brand-primary'
            )}
            style={{ width: `${pct}%` }}

