import { Router, Request, Response } from 'express';
import fs from 'fs';
import { requireAuth, requireSystemAdmin } from '../middleware/auth.js';
import { validate } from '../middleware/validate.js';
import { AdminListQuery, UpdateUserRoleBody, AdminAuthEventsQuery } from '../schemas/index.js';
import { userOps, beadOps, githubSyncOps, beadSyncStateOps, projectMemoryOps, projectMemberOps, projectInvitationOps, installationOps, installationRepoOps, authEventOps } from '../db/ops.js';
import { pgDb } from '../db/postgres.js';
import { sql, eq, like, desc, count } from 'drizzle-orm';
import * as s from '../db/schema.js';
import { jobQueue } from '../services/job-queue.js';
import { utc } from '../utils/timestamps.js';

const router = Router();

// All admin routes require auth + system admin
router.use(requireAuth, requireSystemAdmin);

// ─── Users ───────────────────────────────────────────────────────────────────

// GET /api/admin/users?search=&limit=&offset=
router.get('/users', validate({ query: AdminListQuery }), async (req: Request, res: Response) => {
  try {
    const { search = '', limit, offset } = req.query as unknown as AdminListQuery;

    let users: any[];
    let total: number;

    if (search) {
      const pattern = `%${search}%`;
      users = await userOps.findAllFiltered(pattern, pattern, pattern, limit, offset);
      total = (await userOps.countFiltered(pattern, pattern, pattern) as any).count;
    } else {
      users = await pgDb.select({
        id: s.users.id, username: s.users.username, displayName: s.users.displayName,
        avatarUrl: s.users.avatarUrl, email: s.users.email, systemRole: s.users.systemRole,
        onboardingCompleted: s.users.onboardingCompleted, createdAt: s.users.createdAt, updatedAt: s.users.updatedAt,
        lastLoginAt: s.users.lastLoginAt, lastInteractionAt: s.users.lastInteractionAt,
      }).from(s.users).orderBy(desc(s.users.createdAt)).limit(limit).offset(offset);
      total = (await userOps.countAll() as any).count;
    }

    // Enrich with project counts
    const enriched = [];
    for (const u of users) {
      const [{ projectCount }] = await pgDb.select({ projectCount: count() }).from(s.projects).where(eq(s.projects.userId, u.id));
      enriched.push({
        id: u.id,
        username: u.username,
        displayName: u.displayName,
        avatarUrl: u.avatarUrl,
        email: u.email,
        systemRole: u.systemRole || null,
        onboardingCompleted: !!u.onboardingCompleted,
        projectCount,
        createdAt: utc(u.createdAt),
        updatedAt: utc(u.updatedAt),
        lastLoginAt: utc(u.lastLoginAt),
        lastInteractionAt: utc(u.lastInteractionAt),
      });
    }

    res.json({ users: enriched, total, limit, offset });
  } catch (error) {
    console.error('[Admin] Error listing users:', error);
    res.status(500).json({ error: 'Failed to list users' });
  }
});

// GET /api/admin/users/:userId
router.get('/users/:userId', async (req: Request, res: Response) => {
  try {
    const user = await userOps.findById(req.params.userId as string) as any;
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    const projects = await pgDb.select({
      id: s.projects.id, name: s.projects.name, githubRepo: s.projects.githubRepo, createdAt: s.projects.createdAt,
    }).from(s.projects).where(eq(s.projects.userId, user.id)).orderBy(desc(s.projects.updatedAt));

    const [{ credentialCount }] = await pgDb.select({ credentialCount: count() }).from(s.credentials).where(eq(s.credentials.userId, user.id));

    const orgMemberships = await pgDb.select({
      id: s.organizations.id, name: s.organizations.name, slug: s.organizations.slug, role: s.organizationMembers.role,
    }).from(s.organizations)
      .innerJoin(s.organizationMembers, eq(s.organizations.id, s.organizationMembers.orgId))
      .where(eq(s.organizationMembers.userId, user.id));

    res.json({
      id: user.id,
      username: user.username,
      displayName: user.displayName,
      avatarUrl: user.avatarUrl,
      email: user.email,
      systemRole: user.systemRole || null,
      onboardingCompleted: !!user.onboardingCompleted,
      createdAt: utc(user.createdAt),
      updatedAt: utc(user.updatedAt),
      lastLoginAt: utc(user.lastLoginAt),
      lastInteractionAt: utc(user.lastInteractionAt),
      projects,
      credentialCount,
      orgMemberships,
    });
  } catch (error) {
    console.error('[Admin] Error fetching user:', error);
    res.status(500).json({ error: 'Failed to fetch user' });
  }
});

// PATCH /api/admin/users/:userId/role
router.patch('/users/:userId/role', validate({ body: UpdateUserRoleBody }), async (req: Request, res: Response) => {
  try {
    const userId = req.params.userId as string;
    const { role } = req.body as UpdateUserRoleBody;

    // Prevent self-demotion
    if (userId === req.user!.id && role !== 'admin') {
      return res.status(400).json({ error: 'Cannot demote yourself' });
    }

    // Prevent last-admin demotion
    if (role !== 'admin') {
      const adminCount = (await userOps.countAdmins() as any).count;
      const targetUser = await userOps.findById(userId) as any;
      if (targetUser?.systemRole === 'admin' && adminCount <= 1) {
        return res.status(400).json({ error: 'Cannot demote the last admin' });
      }
    }

    const user = await userOps.findById(userId) as any;
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    await userOps.updateSystemRole(role, userId);
    console.log(`[Admin] ${req.user!.email} changed role of ${user.email} to ${role || 'none'}`);

    res.json({ success: true, userId, role });
  } catch (error) {
    console.error('[Admin] Error updating user role:', error);
    res.status(500).json({ error: 'Failed to update user role' });
  }
});

// ─── Projects ────────────────────────────────────────────────────────────────

// GET /api/admin/projects?search=&limit=&offset=
router.get('/projects', validate({ query: AdminListQuery }), async (req: Request, res: Response) => {
  try {
    const { search = '', limit, offset } = req.query as unknown as AdminListQuery;

    let whereClause = undefined as any;
    if (search) {
      const pattern = `%${search}%`;
      whereClause = sql`${s.projects.name} ILIKE ${pattern} OR ${s.projects.githubRepo} ILIKE ${pattern} OR ${s.users.displayName} ILIKE ${pattern} OR ${s.users.email} ILIKE ${pattern}`;
    }

    const projectsQuery = pgDb.select({
      id: s.projects.id, name: s.projects.name, githubRepo: s.projects.githubRepo,
      createdAt: s.projects.createdAt, updatedAt: s.projects.updatedAt,
      ownerId: s.users.id, ownerName: s.users.displayName, ownerEmail: s.users.email,
    }).from(s.projects)
      .innerJoin(s.users, eq(s.projects.userId, s.users.id));

    const countQuery = pgDb.select({ total: count() }).from(s.projects)
      .innerJoin(s.users, eq(s.projects.userId, s.users.id));

    const projects = whereClause
      ? await projectsQuery.where(whereClause).orderBy(desc(s.projects.updatedAt)).limit(limit).offset(offset)
      : await projectsQuery.orderBy(desc(s.projects.updatedAt)).limit(limit).offset(offset);

    const [{ total }] = whereClause
      ? await countQuery.where(whereClause)
      : await countQuery;

    // Enrich with counts
    const enriched = [];
    for (const p of projects) {
      const [{ memberCount }] = await pgDb.select({ memberCount: count() }).from(s.projectMembers).where(eq(s.projectMembers.projectId, p.id));
      const [{ beadCount }] = await pgDb.select({ beadCount: count() }).from(s.beads).where(eq(s.beads.projectId, p.id));
      const [{ jobCount }] = await pgDb.select({ jobCount: count() }).from(s.agentJobs).where(eq(s.agentJobs.projectId, p.id));

      enriched.push({
        id: p.id,
        name: p.name,
        githubRepo: p.githubRepo,
        owner: { id: p.ownerId, name: p.ownerName, email: p.ownerEmail },
        memberCount,
        beadCount,
        jobCount,
        createdAt: utc(p.createdAt as any),
        updatedAt: utc(p.updatedAt as any),
      });
    }

    res.json({ projects: enriched, total, limit, offset });
  } catch (error) {
    console.error('[Admin] Error listing projects:', error);
    res.status(500).json({ error: 'Failed to list projects' });
  }
});

// GET /api/admin/projects/:projectId
router.get('/projects/:projectId', async (req: Request, res: Response) => {
  try {
    const rows = await pgDb.select({
      id: s.projects.id, name: s.projects.name, githubRepo: s.projects.githubRepo,
      aiProvider: s.projects.aiProvider, aiModel: s.projects.aiModel,
      userId: s.projects.userId, createdAt: s.projects.createdAt, updatedAt: s.projects.updatedAt,
      ownerName: s.users.displayName, ownerEmail: s.users.email,
    }).from(s.projects)
      .innerJoin(s.users, eq(s.projects.userId, s.users.id))
      .where(eq(s.projects.id, req.params.projectId as string));

    const project = rows[0];
    if (!project) {
      return res.status(404).json({ error: 'Project not found' });
    }

    const members = await pgDb.select({
      userId: s.projectMembers.userId, role: s.projectMembers.role, permissions: s.projectMembers.permissions,
      displayName: s.users.displayName, email: s.users.email,
    }).from(s.projectMembers)
      .innerJoin(s.users, eq(s.projectMembers.userId, s.users.id))
      .where(eq(s.projectMembers.projectId, project.id));

    const recentJobs = await pgDb.select({
      id: s.agentJobs.id, status: s.agentJobs.status, prompt: s.agentJobs.prompt,
      createdAt: s.agentJobs.createdAt, completedAt: s.agentJobs.completedAt,
    }).from(s.agentJobs)
      .where(eq(s.agentJobs.projectId, project.id))
      .orderBy(desc(s.agentJobs.createdAt)).limit(10);

    const beadStats = await pgDb.select({
      status: s.beads.status, count: count(),
    }).from(s.beads)
      .where(eq(s.beads.projectId, project.id))
      .groupBy(s.beads.status);

    res.json({
      id: project.id,
      name: project.name,
      githubRepo: project.githubRepo,
      aiProvider: project.aiProvider,
      aiModel: project.aiModel,
      owner: { id: project.userId, name: project.ownerName, email: project.ownerEmail },
      members,
      recentJobs,
      beadStats,
      createdAt: utc(project.createdAt as any),
      updatedAt: utc(project.updatedAt as any),
    });
  } catch (error) {
    console.error('[Admin] Error fetching project:', error);
    res.status(500).json({ error: 'Failed to fetch project' });
  }
});

// ─── System ──────────────────────────────────────────────────────────────────

// GET /api/admin/system/health
router.get('/system/health', async (req: Request, res: Response) => {
  try {
    const tables = ['users', 'projects', 'beads', 'agent_jobs', 'sessions', 'credentials', 'notifications', 'organizations'];
    const tableCounts: Record<string, number> = {};
    for (const table of tables) {
      try {
        const result = await pgDb.execute(sql.raw(`SELECT COUNT(*) as count FROM ${table}`));
        tableCounts[table] = Number((result as any).rows?.[0]?.count ?? (result as any)[0]?.count ?? 0);
      } catch {
        tableCounts[table] = -1; // table doesn't exist
      }
    }

    const jobStats = jobQueue.getStats();
    const uptime = process.uptime();

    res.json({
      tableCounts,
      jobStats,
      uptime: Math.floor(uptime),
      dbSizeBytes: 0, // Not applicable to Postgres
      nodeVersion: process.version,
      memoryUsage: process.memoryUsage(),
    });
  } catch (error) {
    console.error('[Admin] Error fetching system health:', error);
    res.status(500).json({ error: 'Failed to fetch system health' });
  }
});

// POST /api/admin/system/recover-jobs
router.post('/system/recover-jobs', (req: Request, res: Response) => {
  try {
    const recovered = jobQueue.recoverOrphanedJobs();
    console.log(`[Admin] ${req.user!.email} triggered orphaned job recovery: ${recovered} jobs`);
    res.json({ success: true, recovered });
  } catch (error) {
    console.error('[Admin] Error recovering jobs:', error);
    res.status(500).json({ error: 'Failed to recover jobs' });
  }
});

// ─── Legacy operations (migrated from ADMIN_SECRET endpoints) ────────────────

// DELETE /api/admin/clear-beads/:projectId
router.delete('/clear-beads/:projectId', async (req: Request, res: Response) => {
  try {
    const projectId = req.params.projectId as string;
    await beadOps.deleteByProjectId(projectId);
    await githubSyncOps.deleteByProjectId(projectId);
    await beadSyncStateOps.delete(projectId);
    console.log(`[Admin] ${req.user!.email} cleared beads for project ${projectId}`);
    res.json({ success: true, message: `Cleared all beads for project ${projectId}` });
  } catch (error) {
    console.error('[Admin] Error clearing beads:', error);
    res.status(500).json({ error: 'Failed to clear beads' });
  }
});

// POST /api/admin/reset-user/:userId
router.post('/reset-user/:userId', async (req: Request, res: Response) => {
  try {
    const userId = req.params.userId as string;
    const user = await userOps.findById(userId) as any;
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    const projects = await pgDb.select({ id: s.projects.id }).from(s.projects).where(eq(s.projects.userId, userId));
    const projectIds = projects.map(p => p.id);

    for (const pid of projectIds) {
      await pgDb.delete(s.agentJobs).where(eq(s.agentJobs.projectId, pid));
      await pgDb.delete(s.agentSessions).where(eq(s.agentSessions.projectId, pid));
      await pgDb.delete(s.agents).where(eq(s.agents.projectId, pid));
      await pgDb.delete(s.worktreeRuns).where(eq(s.worktreeRuns.projectId, pid));
      await pgDb.delete(s.planItems).where(eq(s.planItems.projectId, pid));
      await beadOps.deleteByProjectId(pid);
      await beadSyncStateOps.delete(pid);
      await githubSyncOps.deleteByProjectId(pid);
      await projectMemoryOps.deleteByProjectId(pid);
      await pgDb.delete(s.drains).where(eq(s.drains.projectId, pid));
      await projectMemberOps.removeAllByProject(pid);
      await projectInvitationOps.deleteByProjectId(pid);
    }

    await pgDb.delete(s.projects).where(eq(s.projects.userId, userId));
    await pgDb.delete(s.settings).where(eq(s.settings.userId, userId));
    await pgDb.delete(s.notifications).where(eq(s.notifications.userId, userId));
    await pgDb.delete(s.globalMemory).where(eq(s.globalMemory.userId, userId));
    await pgDb.delete(s.credentials).where(eq(s.credentials.userId, userId));
    await pgDb.delete(s.apiTokens).where(eq(s.apiTokens.userId, userId));

    const installations = await installationOps.findByUserId(userId) as any[];
    for (const inst of installations) {
      await installationRepoOps.deleteByInstallation(inst.installationId);
    }
    await pgDb.delete(s.githubInstallations).where(eq(s.githubInstallations.userId, userId));
    await pgDb.delete(s.sessions).where(eq(s.sessions.userId, userId));

    await userOps.updateOnboardingCompleted(false, userId);

    console.log(`[Admin] ${req.user!.email} reset user ${userId} (${user.email})`);
    res.json({
      success: true,
      user: { id: userId, email: user.email, displayName: user.displayName },
      projectsReset: projectIds.length,
    });
  } catch (error) {
    console.error(`[Admin] Error resetting user:`, error);
    res.status(500).json({ error: 'Failed to reset user' });
  }
});

// ─── Auth Events ──────────────────────────────────────────────────────────────

// GET /api/admin/auth-events?limit=50&cursor=...&email=...&event_type=...
router.get('/auth-events', validate({ query: AdminAuthEventsQuery }), async (req: Request, res: Response) => {
  try {
    const { limit, cursor, email, event_type: eventType } = req.query as unknown as AdminAuthEventsQuery;

    // Parse cursor: "created_at|id"
    let cursorCreatedAt: string | undefined;
    let cursorId: string | undefined;
    if (cursor) {
      const parts = cursor.split('|');
      if (parts.length === 2) {
        cursorCreatedAt = parts[0];
        cursorId = parts[1];
      }
    }

    const fetchLimit = limit + 1; // fetch one extra to detect hasMore
    let events: any[];

    // authEventOps use pgDb.execute(sql`...`) which returns QueryResult with .rows
    const unwrapRows = (result: any): any[] => result.rows ?? result ?? [];

    if (email && eventType) {
      const pattern = `%${email}%`;
      events = cursorCreatedAt
        ? unwrapRows(await authEventOps.findFilteredAfterCursor(pattern, eventType, cursorCreatedAt, cursorCreatedAt, cursorId!, fetchLimit))
        : unwrapRows(await authEventOps.findFiltered(pattern, eventType, fetchLimit));
    } else if (email) {
      const pattern = `%${email}%`;
      events = cursorCreatedAt
        ? unwrapRows(await authEventOps.findByEmailAfterCursor(pattern, cursorCreatedAt, cursorCreatedAt, cursorId!, fetchLimit))
        : unwrapRows(await authEventOps.findByEmail(pattern, fetchLimit));
    } else if (eventType) {
      events = cursorCreatedAt
        ? unwrapRows(await authEventOps.findByEventTypeAfterCursor(eventType, cursorCreatedAt, cursorCreatedAt, cursorId!, fetchLimit))
        : unwrapRows(await authEventOps.findByEventType(eventType, fetchLimit));
    } else {
      events = cursorCreatedAt
        ? unwrapRows(await authEventOps.findRecentAfterCursor(cursorCreatedAt, cursorCreatedAt, cursorId!, fetchLimit))
        : unwrapRows(await authEventOps.findRecent(fetchLimit));
    }

    const hasMore = events.length > limit;
    if (hasMore) events = events.slice(0, limit);

    const nextCursor = hasMore && events.length > 0
      ? `${events[events.length - 1].created_at}|${events[events.length - 1].id}`
      : null;

    // Stats — raw SQL returns snake_case
    const typeCountRows = unwrapRows(await authEventOps.countByType());
    const stats: Record<string, number> = {};
    for (const row of typeCountRows) {
      stats[row.event_type] = Number(row.count);
    }
    stats.last_7_days = (await authEventOps.countLast7Days() as any).count;

    // Map snake_case from raw SQL to camelCase
    const mapped = events.map((e: any) => ({
      id: e.id,
      userId: e.user_id,
      email: e.email,
      eventType: e.event_type,
      authMethod: e.auth_method,
      ipAddress: e.ip_address,
      userAgent: e.user_agent,
      metadata: e.metadata ? JSON.parse(e.metadata) : null,
      createdAt: utc(e.created_at),
      displayName: e.display_name || null,
      avatarUrl: e.avatar_url || null,
    }));

    res.json({ events: mapped, stats, nextCursor, hasMore });
  } catch (error) {
    console.error('[Admin] Error listing auth events:', error);
    res.status(500).json({ error: 'Failed to list auth events' });
  }
});

// ─── TEMPORARY: DB Export (remove after Postgres migration) ─────────────────

// GET /api/admin/db-export — Stream the SQLite database file for migration
router.get('/db-export', (req: Request, res: Response) => {
  const dbPath = process.env.DATABASE_URL || './data/devdash.db';
  if (!fs.existsSync(dbPath)) {
    return res.status(404).json({ error: 'Database file not found', path: dbPath });
  }
  const stat = fs.statSync(dbPath);
  res.setHeader('Content-Type', 'application/octet-stream');
  res.setHeader('Content-Disposition', 'attachment; filename="devdash.db"');
  res.setHeader('Content-Length', stat.size);
  fs.createReadStream(dbPath).pipe(res);
});

