// GET /api/admin/projects?search=&limit=&offset=
router.get('/projects', validate({ query: AdminListQuery }), async (req: Request, res: Response) => {
  try {
    const { search = '', limit, offset } = req.query as unknown as AdminListQuery;

    let whereClause = undefined as any;
    if (search) {
      const pattern = `%${search}%`;
      whereClause = sql`${s.projects.name} ILIKE ${pattern} OR ${s.projects.githubRepo} ILIKE ${pattern} OR ${s.users.displayName} ILIKE ${pattern} OR ${s.users.email} ILIKE ${pattern}`;
    }

    const projectsQuery = pgDb.select({
      id: s.projects.id, name: s.projects.name, githubRepo: s.projects.githubRepo,
      createdAt: s.projects.createdAt, updatedAt: s.projects.updatedAt,
      ownerId: s.users.id, ownerName: s.users.displayName, ownerEmail: s.users.email,
    }).from(s.projects)
      .innerJoin(s.users, eq(s.projects.userId, s.users.id));

    const countQuery = pgDb.select({ total: count() }).from(s.projects)
      .innerJoin(s.users, eq(s.projects.userId, s.users.id));

    const projects = whereClause
      ? await projectsQuery.where(whereClause).orderBy(desc(s.projects.updatedAt)).limit(limit).offset(offset)
      : await projectsQuery.orderBy(desc(s.projects.updatedAt)).limit(limit).offset(offset);

    const [{ total }] = whereClause
      ? await countQuery.where(whereClause)
      : await countQuery;

    // Enrich with counts
    const enriched = [];
    for (const p of projects) {
      const [{ memberCount }] = await pgDb.select({ memberCount: count() }).from(s.projectMembers).where(eq(s.projectMembers.projectId, p.id));
      const [{ beadCount }] = await pgDb.select({ beadCount: count() }).from(s.beads).where(eq(s.beads.projectId, p.id));
      const [{ jobCount }] = await pgDb.select({ jobCount: count() }).from(s.agentJobs).where(eq(s.agentJobs.projectId, p.id));

      enriched.push({
        id: p.id,
        name: p.name,
        githubRepo: p.githubRepo,
        owner: { id: p.ownerId, name: p.ownerName, email: p.ownerEmail },
        memberCount,
        beadCount,
        jobCount,
        createdAt: utc(p.createdAt as any),
        updatedAt: utc(p.updatedAt as any),
      });
    }

    res.json({ projects: enriched, total, limit, offset });
  } catch (error) {
    console.error('[Admin] Error listing projects:', error);
    res.status(500).json({ error: 'Failed to list projects' });
  }
});

// GET /api/admin/projects/:projectId
router.get('/projects/:projectId', async (req: Request, res: Response) => {
  try {
    const rows = await pgDb.select({
      id: s.projects.id, name: s.projects.name, githubRepo: s.projects.githubRepo,
      aiProvider: s.projects.aiProvider, aiModel: s.projects.aiModel,
      userId: s.projects.userId, createdAt: s.projects.createdAt, updatedAt: s.projects.updatedAt,
      ownerName: s.users.displayName, ownerEmail: s.users.email,
    }).from(s.projects)
      .innerJoin(s.users, eq(s.projects.userId, s.users.id))
      .where(eq(s.projects.id, req.params.projectId as string));

    const project = rows[0];
    if (!project) {
      return res.status(404).json({ error: 'Project not found' });
    }

    const members = await pgDb.select({
      userId: s.projectMembers.userId, role: s.projectMembers.role, permissions: s.projectMembers.permissions,
      displayName: s.users.displayName, email: s.users.email,
    }).from(s.projectMembers)
      .innerJoin(s.users, eq(s.projectMembers.userId, s.users.id))
      .where(eq(s.projectMembers.projectId, project.id));

    const recentJobs = await pgDb.select({
      id: s.agentJobs.id, status: s.agentJobs.status, prompt: s.agentJobs.prompt,
      createdAt: s.agentJobs.createdAt, completedAt: s.agentJobs.completedAt,
    }).from(s.agentJobs)
      .where(eq(s.agentJobs.projectId, project.id))
      .orderBy(desc(s.agentJobs.createdAt)).limit(10);

    const beadStats = await pgDb.select({
      status: s.beads.status, count: count(),
    }).from(s.beads)
      .where(eq(s.beads.projectId, project.id))
      .groupBy(s.beads.status);

    res.json({
      id: project.id,
      name: project.name,
      githubRepo: project.githubRepo,
      aiProvider: project.aiProvider,
      aiModel: project.aiModel,
      owner: { id: project.userId, name: project.ownerName, email: project.ownerEmail },
      members,
      recentJobs,
      beadStats,
      createdAt: utc(project.createdAt as any),
      updatedAt: utc(project.updatedAt as any),
    });
  } catch (error) {
    console.error('[Admin] Error fetching project:', error);
    res.status(500).json({ error: 'Failed to fetch project' });
  }
});

// ─── System ──────────────────────────────────────────────────────────────────

// GET /api/admin/system/health
router.get('/system/health', async (req: Request, res: Response) => {
  try {
    const tables = ['users', 'projects', 'beads', 'agent_jobs', 'sessions', 'credentials', 'notifications', 'organizations'];
    const tableCounts: Record<string, number> = {};
    for (const table of tables) {
      try {
        const result = await pgDb.execute(sql.raw(`SELECT COUNT(*) as count FROM ${table}`));
        tableCounts[table] = Number((result as any).rows?.[0]?.count ?? (result as any)[0]?.count ?? 0);
      } catch {
        tableCounts[table] = -1; // table doesn't exist
      }
    }

    const jobStats = jobQueue.getStats();
    const uptime = process.uptime();

    res.json({
      tableCounts,
      jobStats,
      uptime: Math.floor(uptime),
      dbSizeBytes: 0, // Not applicable to Postgres
      nodeVersion: process.version,
      memoryUsage: process.memoryUsage(),
    });
  } catch (error) {
    console.error('[Admin] Error fetching system health:', error);
    res.status(500).json({ error: 'Failed to fetch system health' });
  }
});

// POST /api/admin/system/recover-jobs
router.post('/system/recover-jobs', (req: Request, res: Response) => {
  try {
    const recovered = jobQueue.recoverOrphanedJobs();
    console.log(`[Admin] ${req.user!.email} triggered orphaned job recovery: ${recovered} jobs`);
    res.json({ success: true, recovered });
  } catch (error) {
    console.error('[Admin] Error recovering jobs:', error);
    res.status(500).json({ error: 'Failed to recover jobs' });
  }
});

