// DELETE /api/admin/clear-beads/:projectId
router.delete('/clear-beads/:projectId', async (req: Request, res: Response) => {
  try {
    const projectId = req.params.projectId as string;
    await beadOps.deleteByProjectId(projectId);
    await githubSyncOps.deleteByProjectId(projectId);
    await beadSyncStateOps.delete(projectId);
    console.log(`[Admin] ${req.user!.email} cleared beads for project ${projectId}`);
    res.json({ success: true, message: `Cleared all beads for project ${projectId}` });
  } catch (error) {
    console.error('[Admin] Error clearing beads:', error);
    res.status(500).json({ error: 'Failed to clear beads' });
  }
});

// POST /api/admin/reset-user/:userId
router.post('/reset-user/:userId', async (req: Request, res: Response) => {
  try {
    const userId = req.params.userId as string;
    const user = await userOps.findById(userId) as any;
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    const projects = await pgDb.select({ id: s.projects.id }).from(s.projects).where(eq(s.projects.userId, userId));
    const projectIds = projects.map(p => p.id);

    for (const pid of projectIds) {
      await pgDb.delete(s.agentJobs).where(eq(s.agentJobs.projectId, pid));
      await pgDb.delete(s.agentSessions).where(eq(s.agentSessions.projectId, pid));
      await pgDb.delete(s.agents).where(eq(s.agents.projectId, pid));
      await pgDb.delete(s.worktreeRuns).where(eq(s.worktreeRuns.projectId, pid));
      await pgDb.delete(s.planItems).where(eq(s.planItems.projectId, pid));
      await beadOps.deleteByProjectId(pid);
      await beadSyncStateOps.delete(pid);
      await githubSyncOps.deleteByProjectId(pid);
      await projectMemoryOps.deleteByProjectId(pid);
      await pgDb.delete(s.drains).where(eq(s.drains.projectId, pid));
      await projectMemberOps.removeAllByProject(pid);
      await projectInvitationOps.deleteByProjectId(pid);
    }

    await pgDb.delete(s.projects).where(eq(s.projects.userId, userId));
    await pgDb.delete(s.settings).where(eq(s.settings.userId, userId));
    await pgDb.delete(s.notifications).where(eq(s.notifications.userId, userId));
    await pgDb.delete(s.globalMemory).where(eq(s.globalMemory.userId, userId));
    await pgDb.delete(s.credentials).where(eq(s.credentials.userId, userId));
    await pgDb.delete(s.apiTokens).where(eq(s.apiTokens.userId, userId));

    const installations = await installationOps.findByUserId(userId) as any[];
    for (const inst of installations) {
      await installationRepoOps.deleteByInstallation(inst.installationId);
    }
    await pgDb.delete(s.githubInstallations).where(eq(s.githubInstallations.userId, userId));
    await pgDb.delete(s.sessions).where(eq(s.sessions.userId, userId));

    await userOps.updateOnboardingCompleted(false, userId);

    console.log(`[Admin] ${req.user!.email} reset user ${userId} (${user.email})`);
    res.json({
      success: true,
      user: { id: userId, email: user.email, displayName: user.displayName },
      projectsReset: projectIds.length,
    });
  } catch (error) {
    console.error(`[Admin] Error resetting user:`, error);
    res.status(500).json({ error: 'Failed to reset user' });
  }
});

// ─── Auth Events ──────────────────────────────────────────────────────────────

// GET /api/admin/auth-events?limit=50&cursor=...&email=...&event_type=...
router.get('/auth-events', validate({ query: AdminAuthEventsQuery }), async (req: Request, res: Response) => {
  try {
    const { limit, cursor, email, event_type: eventType } = req.query as unknown as AdminAuthEventsQuery;

    // Parse cursor: "created_at|id"
    let cursorCreatedAt: string | undefined;
    let cursorId: string | undefined;
    if (cursor) {
      const parts = cursor.split('|');
      if (parts.length === 2) {
        cursorCreatedAt = parts[0];
        cursorId = parts[1];
      }
    }

    const fetchLimit = limit + 1; // fetch one extra to detect hasMore
    let events: any[];

    // authEventOps use pgDb.execute(sql`...`) which returns QueryResult with .rows
    const unwrapRows = (result: any): any[] => result.rows ?? result ?? [];

    if (email && eventType) {
      const pattern = `%${email}%`;
      events = cursorCreatedAt
        ? unwrapRows(await authEventOps.findFilteredAfterCursor(pattern, eventType, cursorCreatedAt, cursorCreatedAt, cursorId!, fetchLimit))
        : unwrapRows(await authEventOps.findFiltered(pattern, eventType, fetchLimit));
    } else if (email) {
      const pattern = `%${email}%`;
      events = cursorCreatedAt
        ? unwrapRows(await authEventOps.findByEmailAfterCursor(pattern, cursorCreatedAt, cursorCreatedAt, cursorId!, fetchLimit))
        : unwrapRows(await authEventOps.findByEmail(pattern, fetchLimit));
    } else if (eventType) {
      events = cursorCreatedAt
        ? unwrapRows(await authEventOps.findByEventTypeAfterCursor(eventType, cursorCreatedAt, cursorCreatedAt, cursorId!, fetchLimit))
        : unwrapRows(await authEventOps.findByEventType(eventType, fetchLimit));
    } else {
      events = cursorCreatedAt
        ? unwrapRows(await authEventOps.findRecentAfterCursor(cursorCreatedAt, cursorCreatedAt, cursorId!, fetchLimit))
        : unwrapRows(await authEventOps.findRecent(fetchLimit));
    }

    const hasMore = events.length > limit;
    if (hasMore) events = events.slice(0, limit);

    const nextCursor = hasMore && events.length > 0
      ? `${events[events.length - 1].created_at}|${events[events.length - 1].id}`
      : null;

    // Stats — raw SQL returns snake_case
    const typeCountRows = unwrapRows(await authEventOps.countByType());
    const stats: Record<string, number> = {};
    for (const row of typeCountRows) {
      stats[row.event_type] = Number(row.count);
    }
    stats.last_7_days = (await authEventOps.countLast7Days() as any).count;

    // Map snake_case from raw SQL to camelCase
    const mapped = events.map((e: any) => ({
      id: e.id,
      userId: e.user_id,
      email: e.email,
      eventType: e.event_type,
      authMethod: e.auth_method,
      ipAddress: e.ip_address,
      userAgent: e.user_agent,
      metadata: e.metadata ? JSON.parse(e.metadata) : null,
      createdAt: utc(e.created_at),
      displayName: e.display_name || null,
      avatarUrl: e.avatar_url || null,
    }));

    res.json({ events: mapped, stats, nextCursor, hasMore });
  } catch (error) {
    console.error('[Admin] Error listing auth events:', error);
    res.status(500).json({ error: 'Failed to list auth events' });
  }
});

export default router;

