import { describe, it, expect, vi, beforeEach } from 'vitest';
import { detectProjectRuntime, invalidateRuntimeCache } from '../project-runtime.js';
import type { Worker } from '../workers/worker.js';
import { projectMemoryOps } from '../../db/ops.js';

// Mock the DB module so cache tests don't need a real database
vi.mock('../../db/ops.js', () => ({
  projectMemoryOps: {
    findByProjectIdAndKey: vi.fn().mockResolvedValue(null),
    upsert: vi.fn().mockResolvedValue(undefined),
    delete: vi.fn().mockResolvedValue(undefined),
  },
}));

/** Create a mock worker where specific files "exist" in the sandbox */
function createMockWorker(
  existingFiles: string[],
  availableBinaries: string[] = [],
  readFileMap: Record<string, string> = {}
): Worker {
  return {
    exec: vi.fn().mockImplementation((cmd: string, opts?: any) => {
      // Handle `test -f <path>`
      const testMatch = cmd.match(/^test -f (.+)$/);
      if (testMatch) {
        const exists = existingFiles.includes(testMatch[1]);
        return Promise.resolve({ stdout: '', stderr: '', exitCode: exists ? 0 : 1 });
      }
      // Handle `which <binary>`
      const whichMatch = cmd.match(/^which (.+)$/);
      if (whichMatch) {
        const available = availableBinaries.includes(whichMatch[1]);
        return Promise.resolve({
          stdout: available ? `/usr/bin/${whichMatch[1]}` : '',
          stderr: '',
          exitCode: available ? 0 : 1,
        });
      }
      // Handle `ls` glob for .csproj/.sln
      if (cmd.startsWith('ls ')) {
        const pattern = cmd.replace('ls ', '').replace(' 2>/dev/null | head -1', '');
        const match = existingFiles.some(f => {
          if (pattern.includes('*')) {
            const ext = pattern.split('*.')[1];
            return f.endsWith(`.${ext}`);
          }
          return f === pattern;
        });
        return Promise.resolve({ stdout: match ? 'found.csproj' : '', stderr: '', exitCode: match ? 0 : 1 });
      }
      return Promise.resolve({ stdout: '', stderr: '', exitCode: 1 });
    }),
    readFile: vi.fn().mockImplementation((path: string) => {
      if (readFileMap[path]) return Promise.resolve(readFileMap[path]);
      return Promise.reject(new Error('ENOENT'));
    }),
    writeFile: vi.fn(),
    listFiles: vi.fn(),
    gitClone: vi.fn(),
    setupGitCredentials: vi.fn(),
    isRunning: vi.fn().mockReturnValue(true),
    stop: vi.fn(),
    start: vi.fn(),
    getInfo: vi.fn(),
  } as any;
}

describe('detectProjectRuntime', () => {
  const workDir = '/home/user/repo';

  it('detects Rust from Cargo.toml', async () => {
    const worker = createMockWorker(
      [`${workDir}/Cargo.toml`],
      ['cargo']
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('rust');
    expect(runtime.displayName).toBe('Rust');
    expect(runtime.installCommand).toBeUndefined();
    expect(runtime.compileCommand).toBe('cargo check 2>&1');
    expect(runtime.testCommand).toBe('cargo test 2>&1');
  });

  it('detects Go from go.mod', async () => {
    const worker = createMockWorker(
      [`${workDir}/go.mod`],
      ['go']
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('go');
    expect(runtime.installCommand).toBe('go mod download 2>&1');
    expect(runtime.compileCommand).toBe('go build ./... 2>&1');
    expect(runtime.testCommand).toBe('go test ./... 2>&1');
  });

  it('detects Java/Maven from pom.xml', async () => {
    const worker = createMockWorker(
      [`${workDir}/pom.xml`],
      ['mvn']
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('java-maven');
    expect(runtime.installCommand).toBe('mvn dependency:resolve -q 2>&1');
  });

  it('detects Python from requirements.txt', async () => {
    const worker = createMockWorker(
      [`${workDir}/requirements.txt`],
      ['python3']
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('python');
    expect(runtime.installCommand).toBe('pip install -r requirements.txt 2>&1');
    expect(runtime.compileCommand).toBeUndefined();
    expect(runtime.testCommand).toBe('pytest 2>&1');
  });

  it('detects Python from pyproject.toml (no requirements.txt)', async () => {
    const worker = createMockWorker(
      [`${workDir}/pyproject.toml`],
      ['python3']
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('python');
    expect(runtime.installCommand).toBe('pip install -e . 2>&1');
  });

  it('detects Node.js with TypeScript compile check', async () => {
    const worker = createMockWorker(
      [`${workDir}/package.json`, `${workDir}/tsconfig.json`],
      ['node'],
      {
        [`${workDir}/package.json`]: JSON.stringify({
          scripts: { test: 'vitest run', build: 'tsc' },
        }),
      }
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('node');
    expect(runtime.installCommand).toBe('npm install 2>&1');
    expect(runtime.compileCommand).toBe('npx tsc --noEmit 2>&1');
    expect(runtime.testCommand).toBe('npm test 2>&1');
  });

  it('detects Node.js with build script when no tsconfig', async () => {
    const worker = createMockWorker(
      [`${workDir}/package.json`],
      ['node'],
      {
        [`${workDir}/package.json`]: JSON.stringify({
          scripts: { test: 'jest', build: 'webpack' },
        }),
      }
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('node');
    expect(runtime.compileCommand).toBe('npm run build 2>&1');
  });

  it('skips Node.js default test script placeholder', async () => {
    const worker = createMockWorker(
      [`${workDir}/package.json`],
      ['node'],
      {
        [`${workDir}/package.json`]: JSON.stringify({
          scripts: { test: 'echo "Error: no test specified" && exit 1' },
        }),
      }
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('node');
    expect(runtime.testCommand).toBeUndefined();
  });

  it('returns unknown when no recognizable files', async () => {
    const worker = createMockWorker([], []);
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('unknown');
    expect(runtime.installCommand).toBeUndefined();
    expect(runtime.compileCommand).toBeUndefined();
    expect(runtime.testCommand).toBeUndefined();
  });

  it('gracefully degrades when Rust binary not available', async () => {
    const worker = createMockWorker(
      [`${workDir}/Cargo.toml`],
      [] // cargo not available
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('rust');
    expect(runtime.displayName).toContain('not available');
    expect(runtime.compileCommand).toBeUndefined();
    expect(runtime.testCommand).toBeUndefined();
  });

  it('gracefully degrades when Go binary not available', async () => {
    const worker = createMockWorker(
      [`${workDir}/go.mod`],
      [] // go not available
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('go');
    expect(runtime.displayName).toContain('not available');
    expect(runtime.installCommand).toBeUndefined();
  });

  it('Rust takes priority over package.json when both exist', async () => {
    const worker = createMockWorker(
      [`${workDir}/Cargo.toml`, `${workDir}/package.json`],
      ['cargo', 'node']
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('rust');
  });

  it('detects Ruby from Gemfile', async () => {
    const worker = createMockWorker(
      [`${workDir}/Gemfile`],
      ['bundle']
    );
    const runtime = await detectProjectRuntime(worker, workDir);
    expect(runtime.language).toBe('ruby');
    expect(runtime.installCommand).toBe('bundle install 2>&1');
    expect(runtime.testCommand).toBe('bundle exec rake test 2>&1');
  });
});

describe('detectProjectRuntime — caching', () => {
  const workDir = '/home/user/repo';

  beforeEach(() => {
    vi.clearAllMocks();
    // Default: no cache hit
    vi.mocked(projectMemoryOps.findByProjectIdAndKey).mockResolvedValue(null as any);
  });

  it('caches runtime on first detection when projectId is provided', async () => {
    const worker = createMockWorker(
      [`${workDir}/Cargo.toml`],
      ['cargo']
    );
    await detectProjectRuntime(worker, workDir, 'proj-1');

    expect(projectMemoryOps.upsert).toHaveBeenCalledWith(
      expect.any(String), // uuid
      'proj-1',
      'PROJECT_RUNTIME',
      expect.stringContaining('"language":"rust"'),
      expect.stringContaining('"language":"rust"'),
    );
  });

  it('uses cached runtime and skips file probes', async () => {
    // Simulate cache hit
    vi.mocked(projectMemoryOps.findByProjectIdAndKey).mockResolvedValue({
      content: JSON.stringify({ language: 'go', detectedAt: new Date().toISOString() }),
    } as any);

    // Worker has NO go.mod — but cache says Go, so file probes are skipped
    const worker = createMockWorker([], ['go']);
    const runtime = await detectProjectRuntime(worker, workDir, 'proj-1');

    expect(runtime.language).toBe('go');
    expect(runtime.installCommand).toBe('go mod download 2>&1');
    // Should NOT have called test -f (file probes)
    const execCalls = vi.mocked(worker.exec).mock.calls.map(c => c[0]);
    expect(execCalls.every(c => !c.startsWith('test -f'))).toBe(true);
  });

  it('still checks binary availability even with cache hit', async () => {
    vi.mocked(projectMemoryOps.findByProjectIdAndKey).mockResolvedValue({
      content: JSON.stringify({ language: 'rust', detectedAt: new Date().toISOString() }),
    } as any);

    // Cache says Rust, but cargo not available in this sandbox
    const worker = createMockWorker([], []);
    const runtime = await detectProjectRuntime(worker, workDir, 'proj-1');

    expect(runtime.language).toBe('rust');
    expect(runtime.displayName).toContain('not available');
    expect(runtime.compileCommand).toBeUndefined();
  });

  it('does not cache when no projectId is provided', async () => {
    const worker = createMockWorker(
      [`${workDir}/go.mod`],
      ['go']
    );
    await detectProjectRuntime(worker, workDir);

    expect(projectMemoryOps.upsert).not.toHaveBeenCalled();
  });

  it('caches Node.js sub-details (compile variant, test script)', async () => {
    const worker = createMockWorker(
      [`${workDir}/package.json`, `${workDir}/tsconfig.json`],
      ['node'],
      {
        [`${workDir}/package.json`]: JSON.stringify({
          scripts: { test: 'vitest', build: 'tsc' },
        }),
      }
    );
    await detectProjectRuntime(worker, workDir, 'proj-2');

    const cached = JSON.parse(
      vi.mocked(projectMemoryOps.upsert).mock.calls[0][3] as string
    );
    expect(cached.language).toBe('node');
    expect(cached.nodeCompileVariant).toBe('tsc');
    expect(cached.nodeHasTests).toBe(true);
  });

  it('caches Python install variant', async () => {
    const worker = createMockWorker(
      [`${workDir}/requirements.txt`],
      ['python3']
    );
    await detectProjectRuntime(worker, workDir, 'proj-3');

    const cached = JSON.parse(
      vi.mocked(projectMemoryOps.upsert).mock.calls[0][3] as string
    );
    expect(cached.language).toBe('python');
    expect(cached.pythonInstallVariant).toBe('requirements');
  });

  it('invalidateRuntimeCache deletes the cache entry', () => {
    invalidateRuntimeCache('proj-1');
    expect(projectMemoryOps.delete).toHaveBeenCalledWith('proj-1', 'PROJECT_RUNTIME');
  });
});

