async function getCachedRuntime(projectId: string): Promise<CachedRuntime | null> {
  try {
    const row = await projectMemoryOps.findByProjectIdAndKey(projectId, CACHE_KEY) as any;
    if (!row?.content) return null;
    return JSON.parse(row.content) as CachedRuntime;
  } catch {
    return null;
  }
}

/**
 * Write runtime cache to project_memory.
 */
async function cacheRuntime(projectId: string, cached: CachedRuntime): Promise<void> {
