// CLI login: browser-based auth for CLI tools
// Opens in browser, authenticates, redirects token to localhost callback
router.get('/cli-token', async (req, res) => {
  const { port, nonce } = req.query;
  if (!port || !nonce) {
    return res.status(400).send('Missing port or nonce parameter');
  }

  // Store CLI redirect info in session
  (req.session as any).cliRedirect = { port: String(port), nonce: String(nonce) };

  // Check if user is already authenticated via cookie
  const existingToken = req.cookies?.token;
  if (existingToken) {
    const payload = verifyToken(existingToken);
    if (payload) {
      delete (req.session as any).cliRedirect;

      // Create a revocable API token
      const rawToken = `dd_${crypto.randomBytes(32).toString('hex')}`;
      const tokenPrefix = rawToken.slice(0, 10);
      const tokenHash = hashToken(rawToken);
      const tokenId = crypto.randomUUID();
      const hostname = os.hostname();
      await apiTokenOps.create(tokenId, payload.userId, `CLI (${hostname})`, tokenPrefix, tokenHash);

      return res.redirect(`http://127.0.0.1:${port}/callback?token=${encodeURIComponent(rawToken)}&nonce=${nonce}`);
    }
  }

  // Not authenticated — redirect to Google OAuth
  // Pass CLI params as query so they're encoded in OAuth state (survives incognito)
  res.redirect(`/api/auth/google?cli_port=${encodeURIComponent(String(port))}&cli_nonce=${encodeURIComponent(String(nonce))}`);
});

// Legacy: Generate raw JWT token (kept for backward compat, prefer /tokens)
router.post('/api-token', requireAuth, (req, res) => {
  const user = req.user as AuthUser;
  const token = generateLongLivedToken(user.id);
  res.json({ token, expiresIn: '90d', userId: user.id });
});

