  if (await fileExists(worker, `${workDir}/tsconfig.json`)) {
    compileVariant = 'tsc';
  } else {
    // No root tsconfig — check workspace dirs for per-workspace type checking
    try {
      const pkg = JSON.parse(await worker.readFile(`${workDir}/package.json`));
      const rawWorkspaces: string[] = Array.isArray(pkg.workspaces)
        ? pkg.workspaces
        : pkg.workspaces?.packages || [];

      const dirs: string[] = [];
      for (const ws of rawWorkspaces) {
        if (ws.includes('*')) {
          const result = await worker.exec(`ls -d ${ws} 2>/dev/null`, { cwd: workDir, timeout: 5000 });
          if (result.exitCode === 0 && result.stdout.trim()) {
            dirs.push(...result.stdout.trim().split('\n'));
          }
        } else {
          dirs.push(ws);
        }
      }

      const found: string[] = [];
      for (const dir of dirs) {
        if (await fileExists(worker, `${workDir}/${dir}/tsconfig.json`)) {
          found.push(`${dir}/tsconfig.json`);
        }
      }
      if (found.length > 0) {
        compileVariant = 'tsc-workspaces';
        tsconfigPaths = found;
      }
    } catch { /* ignore */ }
  }

  try {
    const pkg = JSON.parse(await worker.readFile(`${workDir}/package.json`));
    hasTests = !!(pkg.scripts?.test && pkg.scripts.test !== 'echo "Error: no test specified" && exit 1');
  } catch { /* ignore */ }
  cached = { language: 'node', nodeCompileVariant: compileVariant, nodeHasTests: hasTests, nodeTsconfigPaths: tsconfigPaths, detectedAt: now };
}

if (!cached) {
  return { runtime: UNKNOWN_RUNTIME, cached: { version: CACHE_VERSION, language: 'unknown', detectedAt: now } };
}

// Stamp cache version and detect expected runtime version
cached.version = CACHE_VERSION;
cached.runtimeVersion = await detectRuntimeVersion(worker, workDir, cached.language);

