}

function makeProject(overrides: Partial<any> = {}) {
  return {
    id: 'proj-1',
    userId: 'user-1',
    name: 'Test Project',
    githubRepo: 'owner/repo',
    mergeStrategy: 'pr',
    aiProvider: 'claude',
    aiModel: 'claude-sonnet-4-20250514',
