import { agentDispatcher } from '../agent-dispatch.js';

// Default exec handler: returns sensible values for common dispatch commands.
// Tests that need custom behavior can override via mockWorker.exec.mockImplementation().
function defaultExecHandler(cmd: string) {
  // Runtime detection: no recognizable files → unknown runtime → skip install/compile/test
  if (cmd.startsWith('test -f')) return { stdout: '', stderr: '', exitCode: 1 };
  if (cmd.startsWith('which')) return { stdout: '', stderr: '', exitCode: 1 };
  if (cmd.startsWith('ls ')) return { stdout: '', stderr: '', exitCode: 1 };
  // Git identity
  if (cmd.startsWith('git config')) return { stdout: '', stderr: '', exitCode: 0 };
  // Default branch
  if (cmd === 'git rev-parse --abbrev-ref HEAD') return { stdout: 'main\n', stderr: '', exitCode: 0 };
  // Feature branch
  if (cmd.startsWith('git checkout -b')) return { stdout: '', stderr: '', exitCode: 0 };
  // Diff checks — return file names so hasChanges = true
  if (cmd === 'git diff --name-only') return { stdout: 'src/index.ts\n', stderr: '', exitCode: 0 };
  if (cmd === 'git diff --cached --name-only') return { stdout: '', stderr: '', exitCode: 0 };
  // Commit, push
  if (cmd.startsWith('git add')) return { stdout: '', stderr: '', exitCode: 0 };
  if (cmd.startsWith('git commit')) return { stdout: '', stderr: '', exitCode: 0 };
  if (cmd.startsWith('git push')) return { stdout: '', stderr: '', exitCode: 0 };
  // Verify push
  if (cmd.startsWith('git log origin/')) return { stdout: '', stderr: '', exitCode: 0 };
  // Collect result
  if (cmd === 'git branch --show-current') return { stdout: 'agent/bead-1\n', stderr: '', exitCode: 0 };
  if (cmd === 'git rev-parse HEAD') return { stdout: 'abc1234\n', stderr: '', exitCode: 0 };
  if (cmd.startsWith('git diff --stat')) return { stdout: ' 1 file changed, 5 insertions(+)\n', stderr: '', exitCode: 0 };
  // Repo structure tree
  if (cmd.startsWith('find .')) return { stdout: './src\n./package.json\n', stderr: '', exitCode: 0 };
  return { stdout: '', stderr: '', exitCode: 0 };
}

// Helper: create a mock worker
function createMockWorker() {
  return {
    exec: vi.fn().mockImplementation(async (cmd: string) => defaultExecHandler(cmd)),
    readFile: vi.fn(),
    writeFile: vi.fn(),
    listFiles: vi.fn(),
    gitClone: vi.fn().mockResolvedValue({ stdout: '', stderr: '', exitCode: 0 }),
    setupGitCredentials: vi.fn().mockResolvedValue(undefined),
    isRunning: vi.fn().mockReturnValue(true),
    stop: vi.fn().mockResolvedValue(undefined),
    getInfo: vi.fn().mockReturnValue({ id: 'w1', isActive: true, type: 'docker' }),
    start: vi.fn().mockResolvedValue('w1'),
  };
}

function makeJob(overrides: Partial<any> = {}) {
  return {
    id: 'job-1',
    projectId: 'proj-1',
    beadId: 'bead-1',
    prompt: 'Fix the login bug',
    status: 'queued',
    workerType: 'docker',
    priority: 2,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    ...overrides,
  };
}

function makeProject(overrides: Partial<any> = {}) {
  return {
    id: 'proj-1',
    userId: 'user-1',
    name: 'Test Project',
    githubRepo: 'owner/repo',
    mergeStrategy: 'pr',
    aiProvider: 'claude',
    aiModel: 'claude-sonnet-4-20250514',
    ...overrides,
  };
}

describe('AgentDispatcher', () => {
  let mockWorker: ReturnType<typeof createMockWorker>;

  beforeEach(() => {
    vi.clearAllMocks();

    mockWorker = createMockWorker();
    mockDockerCreateWorker.mockResolvedValue({ id: 'w1', worker: mockWorker });

    // Default postflight: returns a minimal result with rescue branch
    mockRunFailurePostflight.mockResolvedValue({
      totalTurns: 0,
      totalTokens: 0,
      durationMs: 1000,
      rescueBranch: 'rescue/job-1',
      failureArtifacts: {
        rescueBranch: 'rescue/job-1',
        changedFiles: ['src/index.ts'],
        collectedAt: new Date().toISOString(),
        collectorsRan: ['uncommitted-diff', 'rescue-branch', 'failure-analysis', 'job-metrics'],
      },
    });
  });

  describe('dispatchJob() — credential injection (Step 1)', () => {
    it('calls setupGitCredentials when user has GitHub credential', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue({
        encrypted_value: 'ghp_test_token',
      });
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Done',
        prUrl: 'https://github.com/owner/repo/pull/1',
        totalTurns: 3,
        totalTokens: 5000,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockWorker.setupGitCredentials).toHaveBeenCalledWith('ghp_test_token');
    });

    it('clones via gitClone with HTTPS URL when credentials are available', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue({
        encrypted_value: 'ghp_test_token',
      });
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Done',
        totalTurns: 1,
        totalTokens: 100,
      });

      await agentDispatcher.dispatchJob('job-1');

      // Credentials are set up, then gitClone is called with HTTPS URL
      expect(mockWorker.setupGitCredentials).toHaveBeenCalledWith('ghp_test_token');
      expect(mockWorker.gitClone).toHaveBeenCalledWith(
        'https://github.com/owner/repo.git'
      );
    });

    it('falls back to plain HTTPS clone when no credentials', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Done',
        totalTurns: 1,
        totalTokens: 100,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockWorker.setupGitCredentials).not.toHaveBeenCalled();
      expect(mockWorker.gitClone).toHaveBeenCalledWith(
        'https://github.com/owner/repo.git'
      );
    });
  });

  describe('dispatchJob() — bead lifecycle (Step 2)', () => {
    it('transitions bead to in_progress when job starts', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Done',
        totalTurns: 1,
        totalTokens: 100,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockBeadUpdateStatus).toHaveBeenCalledWith('in_progress', 'bead-1');
    });

    it('transitions bead to completed when code is pushed (PR mode)', async () => {
      const { transitionStatus } = await import('../bead-lifecycle.js');
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Created PR',
        prUrl: 'https://github.com/owner/repo/pull/1',
        totalTurns: 3,
        totalTokens: 5000,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(transitionStatus).toHaveBeenCalledWith('bead-1', 'completed', expect.objectContaining({
        source: 'agent-dispatch',
        projectId: 'proj-1',
        userId: 'user-1',
      }));
    });

    it('reverts bead to pending on failure', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: false,
        error: 'Something went wrong',
        totalTurns: 1,
        totalTokens: 100,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockBeadUpdateStatus).toHaveBeenCalledWith('in_progress', 'bead-1');
      expect(mockBeadUpdateStatus).toHaveBeenCalledWith('pending', 'bead-1');
    });

    it('skips bead transitions when no beadId', async () => {
      const job = makeJob({ beadId: undefined });
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Done',
        totalTurns: 1,
        totalTokens: 100,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockBeadUpdateStatus).not.toHaveBeenCalled();
    });
  });

  describe('dispatchJob() — notifications (Step 3)', () => {
    it('creates success notification on completion', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Fixed the bug',
        prUrl: 'https://github.com/owner/repo/pull/1',
        totalTurns: 3,
        totalTokens: 5000,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockNotificationCreate).toHaveBeenCalledWith(
        expect.any(String),
        'user-1',
        'agent_complete',
        expect.stringContaining('Agent completed'),
        expect.any(String),
        expect.any(String)
      );
    });

    it('creates failure notification on error', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: false,
        error: 'Tests failed',
        totalTurns: 2,
        totalTokens: 3000,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockNotificationCreate).toHaveBeenCalledWith(
        expect.any(String),
        'user-1',
        'agent_failed',
        expect.stringContaining('Agent failed'),
        expect.stringContaining('Tests failed'),
        expect.any(String)
      );
    });
  });

  describe('dispatchJob() — merge strategy (Step 5)', () => {
    it('includes mergeStrategy in job result', async () => {
      const job = makeJob();
      const project = makeProject({ merge_strategy: 'direct' });

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });

      mockWorker.exec.mockImplementation(async (cmd: string) => {
        // Override specific commands, fall back to default handler
        if (cmd === 'git branch --show-current') return { stdout: 'main\n', stderr: '', exitCode: 0 };
        if (cmd.includes('git diff --stat')) return { stdout: ' 2 files changed\n', stderr: '', exitCode: 0 };
        return defaultExecHandler(cmd);
      });

      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Pushed directly',
        totalTurns: 2,
        totalTokens: 1000,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockCompleteJob).toHaveBeenCalledWith(
        'job-1',
        expect.objectContaining({
          mergeStrategy: 'direct',
          commitSha: 'abc1234',
          branchName: 'main',
        }),
        expect.any(String)
      );
    });
  });

  describe('failure postflight (rescue flow)', () => {
    it('runs postflight pipeline on agent loop failure', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });

      mockRunAgentLoop.mockResolvedValue({
        success: false,
        error: 'Agent loop failed',
        totalTurns: 5,
        totalTokens: 10000,
      });

      await agentDispatcher.dispatchJob('job-1');

      // Postflight should be called with the worker and job
      expect(mockRunFailurePostflight).toHaveBeenCalledWith(
        mockWorker,
        expect.objectContaining({ id: 'job-1' }),
        expect.any(String),     // outputLog
        'Agent loop failed',    // error
        expect.any(Number)      // startTime
      );

      // failJob should receive the result from postflight
      expect(mockFailJob).toHaveBeenCalledWith(
        'job-1',
        'Agent loop failed',
        expect.any(String),
        expect.objectContaining({
          failureArtifacts: expect.objectContaining({
            rescueBranch: 'rescue/job-1',
          }),
        })
      );

      // Notification should mention rescue
      expect(mockNotificationCreate).toHaveBeenCalledWith(
        expect.any(String),
        'user-1',
        'agent_failed',
        expect.any(String),
        expect.stringContaining('rescue'),
        expect.any(String)
      );
    });

    it('job still fails gracefully when postflight throws', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });

      // Postflight itself throws
      mockRunFailurePostflight.mockRejectedValue(new Error('Sandbox already dead'));

      mockRunAgentLoop.mockResolvedValue({
        success: false,
        error: 'Agent loop failed',
        totalTurns: 3,
        totalTokens: 5000,
      });

      await agentDispatcher.dispatchJob('job-1');

      // Job should still be marked failed even though postflight threw
      expect(mockFailJob).toHaveBeenCalledWith(
        'job-1',
        'Agent loop failed',
        expect.any(String),
        expect.objectContaining({ totalTurns: 3, totalTokens: 5000 })
      );
    });

    it('runs postflight on catch-all exception path', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });

      // Make the agent loop throw an exception (not a graceful failure)
      mockRunAgentLoop.mockRejectedValue(new Error('Unexpected crash'));

      await agentDispatcher.dispatchJob('job-1');

      // Postflight should still be called
      expect(mockRunFailurePostflight).toHaveBeenCalled();
      expect(mockFailJob).toHaveBeenCalledWith(
        'job-1',
        'Unexpected crash',
        expect.any(String),
        expect.objectContaining({
          failureArtifacts: expect.objectContaining({
            rescueBranch: 'rescue/job-1',
          }),
        })
      );
    });
  });

  describe('integration test bead creation (Step 6)', () => {
    it('creates integration test bead when agent suggests it', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'API refactor', priority: 2 });

      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Refactored the API. This change affects multiple services and needs integration testing.',
        prUrl: 'https://github.com/owner/repo/pull/42',
        totalTurns: 5,
        totalTokens: 8000,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockBeadCreate).toHaveBeenCalledWith(
        expect.any(String),
        'proj-1',
        'Integration test: API refactor',
        expect.stringContaining('integration testing'),
        'pending',
        3,
        null,
        expect.stringContaining('bead-1'),
        null,
        null,
        null,
        null,
        null,
        'bead-1',
        'integration_test',
        null
      );
    });

    it('does NOT create integration test bead when not suggested', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Simple fix', priority: 2 });

      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Fixed a typo in the readme.',
        totalTurns: 1,
        totalTokens: 500,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockBeadCreate).not.toHaveBeenCalled();
    });
  });
});

