import { describe, it, expect, vi, beforeEach } from 'vitest';

// Mock the database module before importing agent-context
vi.mock('../../db/ops.js', () => ({
  projectOps: {
    findById: vi.fn(),
  },
  projectMemoryOps: {
    findByProjectId: vi.fn(),
    findByProjectIdAndKey: vi.fn(),
  },
  credentialOps: {
    findByUserAndService: vi.fn(),
  },
  beadOps: {
    findById: vi.fn(),
  },
}));

import { buildAgentContext, buildSystemPrompt } from '../agent-context.js';
import { projectOps, projectMemoryOps, credentialOps, beadOps } from '../../db/ops.js';

describe('Agent Context', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('buildAgentContext()', () => {
    it('throws when project not found', async () => {
      vi.mocked(projectOps.findById).mockResolvedValue(undefined as any);
      await expect(buildAgentContext('job1', 'missing', 'do stuff')).rejects.toThrow(
        'Project missing not found'
      );
    });

    it('builds context for a project with GitHub repo', async () => {
      vi.mocked(projectOps.findById).mockResolvedValue({
        id: 'p1',
        name: 'Test Project',
        description: 'desc',
        githubRepo: 'owner/repo',
        userId: 'u1',
        aiProvider: 'claude',
        aiModel: 'claude-sonnet-4-20250514',
      } as any);
      vi.mocked(projectMemoryOps.findByProjectId).mockResolvedValue([]);
      vi.mocked(projectMemoryOps.findByProjectIdAndKey).mockResolvedValue(undefined as any);
      vi.mocked(credentialOps.findByUserAndService).mockResolvedValue(undefined as any);

      const ctx = await buildAgentContext('job1', 'p1', 'do stuff');

      expect(ctx.project.githubRepo).toBe('owner/repo');
      // Agent tools are filesystem + shell + status (git/github handled by dispatcher)
      const toolNames = ctx.tools.map(t => t.name);
      expect(toolNames).toContain('read_file');
      expect(toolNames).toContain('write_file');
      expect(toolNames).toContain('run_command');
    });

    it('enriches prompt with bead context', async () => {
      vi.mocked(projectOps.findById).mockResolvedValue({
        id: 'p1',
        name: 'Test',
        description: null,
        githubRepo: null,
        userId: 'u1',
        aiProvider: 'claude',
        aiModel: 'claude-sonnet-4-20250514',
      } as any);
      vi.mocked(projectMemoryOps.findByProjectId).mockResolvedValue([]);
      vi.mocked(projectMemoryOps.findByProjectIdAndKey).mockResolvedValue(undefined as any);
      vi.mocked(credentialOps.findByUserAndService).mockResolvedValue(undefined as any);
      vi.mocked(beadOps.findById).mockResolvedValue({
        subject: 'Fix login bug',
        description: 'Users cannot login with SSO',
        priority: 1,
      } as any);

      const ctx = await buildAgentContext('job1', 'p1', 'fix it', 'bead-123');

      expect(ctx.task.prompt).toContain('Fix login bug');
      expect(ctx.task.prompt).toContain('Users cannot login with SSO');
      expect(ctx.task.priority).toBe(1);
    });

    it('includes project memory entries', async () => {
      vi.mocked(projectOps.findById).mockResolvedValue({
        id: 'p1',
        name: 'Test',
        description: null,
        githubRepo: null,
        userId: 'u1',
      } as any);
      vi.mocked(projectMemoryOps.findByProjectId).mockResolvedValue([
        { key: 'ARCHITECTURE', content: 'React + Express' },
        { key: 'CONVENTIONS', content: 'Use TypeScript strict mode' },
      ] as any);
      vi.mocked(projectMemoryOps.findByProjectIdAndKey).mockResolvedValue(undefined as any);
      vi.mocked(credentialOps.findByUserAndService).mockResolvedValue(undefined as any);

      const ctx = await buildAgentContext('job1', 'p1', 'do stuff');

      expect(ctx.memory['ARCHITECTURE']).toBe('React + Express');
      expect(ctx.memory['CONVENTIONS']).toBe('Use TypeScript strict mode');
    });
  });

  describe('buildSystemPrompt()', () => {
    it('does NOT list tools in the prompt', () => {
      const prompt = buildSystemPrompt({
        jobId: 'j1',
        project: { id: 'p1', name: 'Test', aiProvider: 'claude', aiModel: 'claude-sonnet-4-20250514', mergeStrategy: 'pr' },
        task: { prompt: 'do stuff' },
        memory: {},
        instructions: 'You are an agent.',
        credentials: {},
        tools: [
          { name: 'read_file', description: 'Read a file', input_schema: {} },
          { name: 'write_file', description: 'Write a file', input_schema: {} },
        ],
        workDir: '/home/user/repo',
      });

      expect(prompt).not.toContain('Available Tools');
      expect(prompt).not.toContain('**read_file**');
    });

    it('includes memory entries', () => {
      const prompt = buildSystemPrompt({
        jobId: 'j1',
        project: { id: 'p1', name: 'Test', aiProvider: 'claude', aiModel: 'claude-sonnet-4-20250514', mergeStrategy: 'pr' },
        task: { prompt: 'do stuff' },
        memory: { ARCH: 'React app' },
        instructions: 'You are an agent.',
        credentials: {},
        tools: [],
        workDir: '/home/user/repo',
      });

      expect(prompt).toContain('### ARCH');
      expect(prompt).toContain('React app');
    });

    it('includes repo structure when provided', () => {
      const prompt = buildSystemPrompt({
        jobId: 'j1',
        project: { id: 'p1', name: 'Test', aiProvider: 'claude', aiModel: 'claude-sonnet-4-20250514', mergeStrategy: 'pr' },
        task: { prompt: 'fix it' },
        memory: {},
        instructions: 'You are an agent.',
        credentials: {},
        tools: [],
        workDir: '/home/user/repo',
        repoStructure: './src\n./package.json',
      });

      expect(prompt).toContain('Project Structure');
      expect(prompt).toContain('./src');
      expect(prompt).toContain('./package.json');
    });
  });
});

