import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

// Use vi.hoisted to create mock functions accessible to vi.mock factories
const {
  mockProjectFindById,
  mockCredentialFind,
  mockBeadFindById,
  mockBeadUpdateStatus,
  mockBeadCreate,
  mockNotificationCreate,
  mockGetJob,
  mockStartJob,
  mockCompleteJob,
  mockFailJob,
  mockCancelJob,
  mockCanAcceptJob,
  mockGetNextJob,
  mockUpdateOutputLog,
  mockRunAgentLoop,
  mockDockerCreateWorker,
  mockDockerStopAll,
  mockRunFailurePostflight,
} = vi.hoisted(() => ({
  mockProjectFindById: vi.fn(),
  mockCredentialFind: vi.fn(),
  mockBeadFindById: vi.fn(),
  mockBeadUpdateStatus: vi.fn(),
  mockBeadCreate: vi.fn(),
  mockNotificationCreate: vi.fn(),
  mockGetJob: vi.fn(),
  mockStartJob: vi.fn(),
  mockCompleteJob: vi.fn(),
  mockFailJob: vi.fn(),
  mockCancelJob: vi.fn(),
  mockCanAcceptJob: vi.fn(),
  mockGetNextJob: vi.fn(),
  mockUpdateOutputLog: vi.fn(),
  mockRunAgentLoop: vi.fn(),
  mockDockerCreateWorker: vi.fn(),
  mockDockerStopAll: vi.fn(),
  mockRunFailurePostflight: vi.fn(),
}));

// Mock all DB modules
vi.mock('../../db/sqlite.js', () => ({
  projectOps: {
    findById: { get: mockProjectFindById },
  },
