      const project = makeProject();

      mockGetJob.mockReturnValue(job);
      mockProjectFindById.mockReturnValue(project);
      mockCredentialFind.mockReturnValue(undefined);
      mockBeadFindById.mockReturnValue({ subject: 'Fix login', priority: 2 });

