// Default exec handler: returns sensible values for common dispatch commands.
// Tests that need custom behavior can override via mockWorker.exec.mockImplementation().
function defaultExecHandler(cmd: string) {
  // Runtime detection: no recognizable files → unknown runtime → skip install/compile/test
  if (cmd.startsWith('test -f')) return { stdout: '', stderr: '', exitCode: 1 };
  if (cmd.startsWith('which')) return { stdout: '', stderr: '', exitCode: 1 };
  if (cmd.startsWith('ls ')) return { stdout: '', stderr: '', exitCode: 1 };
  // Git identity
  if (cmd.startsWith('git config')) return { stdout: '', stderr: '', exitCode: 0 };
  // Default branch
  if (cmd === 'git rev-parse --abbrev-ref HEAD') return { stdout: 'main\n', stderr: '', exitCode: 0 };
  // Feature branch
  if (cmd.startsWith('git checkout -b')) return { stdout: '', stderr: '', exitCode: 0 };
  // Diff checks — return file names so hasChanges = true
  if (cmd === 'git diff --name-only') return { stdout: 'src/index.ts\n', stderr: '', exitCode: 0 };
  if (cmd === 'git diff --cached --name-only') return { stdout: '', stderr: '', exitCode: 0 };
  // Commit, push
  if (cmd.startsWith('git add')) return { stdout: '', stderr: '', exitCode: 0 };
  if (cmd.startsWith('git commit')) return { stdout: '', stderr: '', exitCode: 0 };
  if (cmd.startsWith('git push')) return { stdout: '', stderr: '', exitCode: 0 };
  // Verify push
  if (cmd.startsWith('git log origin/')) return { stdout: '', stderr: '', exitCode: 0 };
  // Collect result
  if (cmd === 'git branch --show-current') return { stdout: 'agent/bead-1\n', stderr: '', exitCode: 0 };
  if (cmd === 'git rev-parse HEAD') return { stdout: 'abc1234\n', stderr: '', exitCode: 0 };
  if (cmd.startsWith('git diff --stat')) return { stdout: ' 1 file changed, 5 insertions(+)\n', stderr: '', exitCode: 0 };
  // Repo structure tree
  if (cmd.startsWith('find .')) return { stdout: './src\n./package.json\n', stderr: '', exitCode: 0 };
  return { stdout: '', stderr: '', exitCode: 0 };
}

// Helper: create a mock worker
function createMockWorker() {
  return {
    exec: vi.fn().mockImplementation(async (cmd: string) => defaultExecHandler(cmd)),
    readFile: vi.fn(),
    writeFile: vi.fn(),
    listFiles: vi.fn(),
    gitClone: vi.fn().mockResolvedValue({ stdout: '', stderr: '', exitCode: 0 }),
    setupGitCredentials: vi.fn().mockResolvedValue(undefined),
    isRunning: vi.fn().mockReturnValue(true),
    stop: vi.fn().mockResolvedValue(undefined),
    getInfo: vi.fn().mockReturnValue({ id: 'w1', isActive: true, type: 'docker' }),
    start: vi.fn().mockResolvedValue('w1'),
  };
}

