      await agentDispatcher.dispatchJob('job-1');

      expect(mockWorker.setupGitCredentials).toHaveBeenCalledWith('ghp_test_token');
    });

    it('clones via gitClone with HTTPS URL when credentials are available', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue({
        encrypted_value: 'ghp_test_token',
      });
      mockBeadFindById.mockResolvedValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Done',
        totalTurns: 1,
        totalTokens: 100,
      });

      await agentDispatcher.dispatchJob('job-1');

      // Credentials are set up, then gitClone is called with HTTPS URL
      expect(mockWorker.setupGitCredentials).toHaveBeenCalledWith('ghp_test_token');
      expect(mockWorker.gitClone).toHaveBeenCalledWith(
        'https://github.com/owner/repo.git'
      );
    });

    it('falls back to plain HTTPS clone when no credentials', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Done',
        totalTurns: 1,
        totalTokens: 100,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockWorker.setupGitCredentials).not.toHaveBeenCalled();
      expect(mockWorker.gitClone).toHaveBeenCalledWith(
        'https://github.com/owner/repo.git'
      );
    });
  });

  describe('dispatchJob() — bead lifecycle (Step 2)', () => {
    it('transitions bead to in_progress when job starts', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Done',
        totalTurns: 1,
        totalTokens: 100,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockBeadUpdateStatus).toHaveBeenCalledWith('in_progress', 'bead-1');
    });

    it('transitions bead to completed when code is pushed (PR mode)', async () => {
      const { transitionStatus } = await import('../bead-lifecycle.js');
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Created PR',
        prUrl: 'https://github.com/owner/repo/pull/1',
        totalTurns: 3,
        totalTokens: 5000,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(transitionStatus).toHaveBeenCalledWith('bead-1', 'completed', expect.objectContaining({
        source: 'agent-dispatch',
        projectId: 'proj-1',
        userId: 'user-1',
      }));
    });

    it('reverts bead to pending on failure', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: false,
        error: 'Something went wrong',
        totalTurns: 1,
        totalTokens: 100,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockBeadUpdateStatus).toHaveBeenCalledWith('in_progress', 'bead-1');
      expect(mockBeadUpdateStatus).toHaveBeenCalledWith('pending', 'bead-1');
    });

    it('skips bead transitions when no beadId', async () => {
      const job = makeJob({ beadId: undefined });
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Done',
        totalTurns: 1,
        totalTokens: 100,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockBeadUpdateStatus).not.toHaveBeenCalled();
    });
  });

  describe('dispatchJob() — notifications (Step 3)', () => {
    it('creates success notification on completion', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Fixed the bug',
        prUrl: 'https://github.com/owner/repo/pull/1',
