        'user-1',
        'agent_complete',
        expect.stringContaining('Agent completed'),
        expect.any(String),
        expect.any(String)
      );
    });

    it('creates failure notification on error', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'Fix login', priority: 2 });
      mockRunAgentLoop.mockResolvedValue({
        success: false,
        error: 'Tests failed',
        totalTurns: 2,
        totalTokens: 3000,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockNotificationCreate).toHaveBeenCalledWith(
        expect.any(String),
        'user-1',
        'agent_failed',
        expect.stringContaining('Agent failed'),
        expect.stringContaining('Tests failed'),
        expect.any(String)
