      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'Fix login', priority: 2 });

      // Postflight itself throws
      mockRunFailurePostflight.mockRejectedValue(new Error('Sandbox already dead'));

      mockRunAgentLoop.mockResolvedValue({
        success: false,
        error: 'Agent loop failed',
        totalTurns: 3,
        totalTokens: 5000,
      });

      await agentDispatcher.dispatchJob('job-1');

      // Job should still be marked failed even though postflight threw
      expect(mockFailJob).toHaveBeenCalledWith(
        'job-1',
        'Agent loop failed',
        expect.any(String),
        expect.objectContaining({ totalTurns: 3, totalTokens: 5000 })
      );
    });

    it('runs postflight on catch-all exception path', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'Fix login', priority: 2 });

      // Make the agent loop throw an exception (not a graceful failure)
      mockRunAgentLoop.mockRejectedValue(new Error('Unexpected crash'));

      await agentDispatcher.dispatchJob('job-1');

      // Postflight should still be called
      expect(mockRunFailurePostflight).toHaveBeenCalled();
      expect(mockFailJob).toHaveBeenCalledWith(
        'job-1',
        'Unexpected crash',
        expect.any(String),
        expect.objectContaining({
          failureArtifacts: expect.objectContaining({
            rescueBranch: 'rescue/job-1',
          }),
        })
      );
    });
  });

  describe('integration test bead creation (Step 6)', () => {
    it('creates integration test bead when agent suggests it', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'API refactor', priority: 2 });

      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Refactored the API. This change affects multiple services and needs integration testing.',
        prUrl: 'https://github.com/owner/repo/pull/42',
        totalTurns: 5,
        totalTokens: 8000,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockBeadCreate).toHaveBeenCalledWith(
        expect.any(String),
        'proj-1',
        'Integration test: API refactor',
        expect.stringContaining('integration testing'),
        'pending',
        3,
        null,
        expect.stringContaining('bead-1'),
        null,
        null,
        null,
        null,
        null,
        'bead-1',
        'integration_test',
        null
      );
    });

    it('does NOT create integration test bead when not suggested', async () => {
      const job = makeJob();
      const project = makeProject();

      mockGetJob.mockResolvedValue(job);
      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'Simple fix', priority: 2 });

      mockRunAgentLoop.mockResolvedValue({
        success: true,
        summary: 'Fixed a typo in the readme.',
        totalTurns: 1,
        totalTokens: 500,
      });

      await agentDispatcher.dispatchJob('job-1');

      expect(mockBeadCreate).not.toHaveBeenCalled();
    });
  });
});

