      mockProjectFindById.mockResolvedValue(project);
      mockCredentialFind.mockResolvedValue(undefined);
      mockBeadFindById.mockResolvedValue({ subject: 'Fix login', priority: 2 });

      mockRunAgentLoop.mockResolvedValue({
        success: false,
        error: 'Agent loop failed',
        totalTurns: 5,
        totalTokens: 10000,
      });

      await agentDispatcher.dispatchJob('job-1');

      // Postflight should be called with the worker and job
      expect(mockRunFailurePostflight).toHaveBeenCalledWith(
        mockWorker,
        expect.objectContaining({ id: 'job-1' }),
        expect.any(String),     // outputLog
        'Agent loop failed',    // error
        expect.any(Number)      // startTime
      );

      // failJob should receive the result from postflight
      expect(mockFailJob).toHaveBeenCalledWith(
        'job-1',
        'Agent loop failed',
        expect.any(String),
